// Üretilen dosya: tool/ozgun/uret.py. Doğa · Ağaç türleri, orman kuşakları, tohum yayılma yolları ve bitki uyumları (iğne ve geniş yapraklılar, maki, garig, kurakçıl uyumlar, yaş halkaları) (orta).
const ozNature15Orta = <(String, String, List<String>, String)>[
  ('İbreli ağaçların büyük çoğunluğu her dem yeşil kalırken, sonbaharda iğne yapraklarını tamamen sarartıp döken açık tohumlu cins aşağıdakilerden hangisidir?', 'Melez (Larix)', ['Porsuk (Taxus)', 'Servi (Cupressus)', 'Ladin (Picea)'], 'Larix cinsine ait melez ağaçları ve bataklık servileri açık tohumlu olmalarına karşın kış kuraklığına uyum amacıyla sonbaharda ibrelerini döker.'),
  ('Göknar ile ladin ağaçlarını arazide incelerken kozalakların dal üzerindeki duruş yönü nasıl bir ayırt edici fark ortaya koyar?', 'Göknar kozalakları dal üzerinde dik dururken ladin kozalakları aşağı sarkar', ['Göknar kozalakları dal uçlarından sarkarken ladin kozalakları dik yükselir', 'Her iki cinsin kozalakları da sürgün altında çiftler halinde asılı durur', 'Ladin kozalakları etli ve üzümsü yapıda iken göknar kozalakları dikenlidir'], 'Göknar (Abies) kozalakları sürgün üzerinde mum gibi dik durur ve olgunlaşınca pulları dökülür; ladin (Picea) kozalakları ise salkım gibi aşağı sarkar ve bütün halde düşer.'),
  ('Antik Çağ\'da Fenikeliler ve Mısırlılar tarafından dayanıklı gemi omurgası yapımında ve tapınak inşasında tercih edilen, çürümeye dirençli kokulu odunuyla ünlü Anadolu ağacı hangisidir?', 'Toros sediri', ['Kazdağı göknarı', 'Sahil çamı', 'Doğu mazısı'], 'Lübnan ve Toros sediri (Cedrus libani), reçineli ve böceklere dayanıklı odunu nedeniyle antik denizcilikte en değerli kereste kaynağı olmuştur.'),
  ('Açık tohumlu bir ağaç olmasına rağmen odunsu kozalak oluşturmayan, tohumunun çevresi parlak kırmızı ve tatlı etli bir örtü (arillus) ile sarılı zehirli ibreli tür hangisidir?', 'Adi porsuk', ['Kokulu ardıç', 'Mavi servi', 'Gümüşi göknar'], 'Porsuk ağacında (Taxus baccata) kırmızı etli arillus dışında tüm bitki kısımları ve tohumun kendisi ölümcül taksin alkaloidi içerir; kuşlar etli kısmı yiyerek tohumu yayar.'),
  ('Kaliforniya kıyılarındaki sisli ormanlarda yaşayan ve yeryüzünün boyca en uzun yaşayan ağaçları arasında ilk sırada yer alan kızıl odunlu açık tohumlu tür hangisidir?', 'Sahil sekoyası (Sequoia sempervirens)', ['Mamut ağacı (Sequoiadendron giganteum)', 'Douglas göknarı (Pseudotsuga menziesii)', 'Batı boylu mazısı (Thuja plicata)'], 'Sahil sekoyası 115 metreyi aşan boyuyla dünyanın en uzun ağacıdır; dev sekoya (mamut ağacı) ise gövde hacmi bakımından en büyüğüdür.'),
  ('Gövde hacmi bakımından dünyadaki en devasa tekil ağaç unvanını taşıyan ve Sierra Nevada Dağları\'nın batı yamaçlarında doğal yayılış gösteren tür hangisidir?', 'Dev sekoya (Sequoiadendron giganteum)', ['Bristlecone çamı (Pinus longaeva)', 'Kauri ağacı (Agathis australis)', 'Japon çamı (Cryptomeria japonica)'], 'General Sherman gibi bireyleriyle bilinen dev sekoya, boyca sahil sekoyasından kısa olsa da gövde çapı ve odun hacmiyle dünyanın en hacimli ağacıdır.'),
  ('Çam cinsine (Pinus) ait ağaçlarda iğne yaprakların sürgün üzerindeki diziliş biçimi hangi anatomik özellikle tanımlanır?', 'Kısa sürgünler üzerinde ikili, üçlü veya beşli demetler halinde kınla sarılı çıkmaları', ['Uzun sürgün boyunca tek tek ve karşılıklı çiftler halinde sapsız dizilmeleri', 'Sürgün yüzeyini kiremit gibi örten küçük üçgenimsi pullar biçiminde kapanmaları', 'Yelpaze şeklinde çatallı damarlanma göstererek yaprak sapıyla dala bağlanmaları'], 'Çamlarda ibreler dip kısmı zarsı bir kınla çevrili kısa sürgünler (brahiblast) üzerinde türe özgü sabit sayılarda (örneğin kızılçamda 2, bazı Amerikan çamlarında 3 veya 5) bulunur.'),
  ('Park ve caddelerde peyzaj amacıyla Ginkgo biloba dikilirken genellikle yalnız erkek bireylerin tercih edilmesinin temel nedeni nedir?', 'Dişi ağaçların olgunlaşıp yere düşen etli tohum örtülerinin bütirik asit nedeniyle ağır koku yayması', ['Dişi bireylerin ilkbaharda yoğun alerjik polen bulutları oluşturarak solunumu zorlaştırması', 'Dişi ağaçların kök sisteminin kaldırım taşlarını erkek bireylere göre çok daha fazla çatlatması', 'Dişi bireylerin soğuk kış donlarına ve kentteki hava kirliliğine karşı dayanıksız olması'], 'Dişi ginkgo tohumlarının dış etli tabakası (sarkotesta) ezildiğinde bozulmuş tereyağına benzer keskin bütirik asit kokusu çıkarır.'),
  ('Türkiye\'de doğal olarak yalnızca Doğu Karadeniz\'in nemli ve sisli dağ yamaçlarında (Ordu\'dan Artvin\'e kadar) yayılış gösteren ibreli orman ağacı hangisidir?', 'Doğu ladini (Picea orientalis)', ['Toros göknarı (Abies cilicica)', 'Kokulu ardıç (Juniperus foetidissima)', 'Dallı servi (Cupressus sempervirens)'], 'Doğu ladini yüksek hava nemi isteyen bir tür olup Türkiye\'de Melet Irmağı doğusundaki Karadeniz dağ kuşağında saf veya kayın-göknar karışık ormanları oluşturur.'),
  ('Batı Anadolu ve Toroslar\'da yetişen, yaklaşık 2-2,5 cm çapındaki iri odunsu-etli kozalaklarından geleneksel olarak yoğun kıvamlı pekmez elde edilen ağaç hangisidir?', 'Andız (Arceuthos drupacea / Juniperus drupacea)', ['Kokulu ardıç (Juniperus foetidissima)', 'Adi porsuk (Taxus baccata)', 'Kızılçam (Pinus brutia)'], 'Andız ağacı ardıçların en iri kozalaklı türüdür; içinde üç tohumun kaynaşmasıyla oluşan sert bir çekirdek bulunan tatlımsı kozalaklarından Toroslar\'da andız pekmezi yapılır.'),
  ('İğne yapraklı ağaçların odununun marangozlukta \'yumuşak odun\' (softwood) olarak adlandırılmasının anatomik dayanağı nedir?', 'Ksilem dokusunun tekdüze trakeidlerden oluşması ve yoğun sklerankima lifleri içermemesi', ['Gövde merkezinde hiç lignin birikmemesi ve hücre duvarlarının yalnız selülozdan oluşması', 'Yıllık yaş halkalarının oluşmaması nedeniyle odunun süngerimsi boşluklar barındırması', 'Kabuk altındaki kambiyumun yalnızca ilkbaharda çalışıp yaz odunu üretmemesi'], 'Yumuşak odun terimi her zaman fiziksel yumuşaklığı değil, açık tohumlu odununun trake ve odun liflerinden yoksun, homojen trakeid yapısını ifade eder.'),
  ('Kuzey yarımkürenin yüksek enlemlerindeki boreal ormanlarda ibreli ağaçların geniş yapraklılara göre çok daha baskın olmasını sağlayan temel fizyolojik avantaj nedir?', 'Kışın yaprak yenileme maliyeti olmadan kısa yaz mevsimi başlar başlamaz fotosenteze geçebilmeleri', ['Donmuş topraktan eksi yirmi derecede bile hızlı su çekebilen geniş trake borularına sahip olmaları', 'Kar tabakasının dallar üzerinde kalın biçimde birikmesini sağlayarak gövdeyi sıcak tutmaları', 'Köklerinde azot bağlayan nodül bakterileri barındırarak bataklık toprağını gübrelemeleri'], 'Kısa vejetasyon süreli soğuk kuşaklarda her yıl yeni yaprak üretmek enerji açısından pahalıdır; kalın kütikulalı ibreler birkaç yıl görev yaparak ilkbahar güneşini anında değerlendirir.'),
  ('Bir çam tohumu çimlenip toprak yüzüne çıktığında gövde ucunda şemsiye telleri gibi açılan çok sayıdaki ilk yeşil yaprakçıklara ne ad verilir?', 'Çenek yaprakları', ['Pulsu koruyucu katafiller', 'Kısa sürgün brahiblastları', 'Üretken sporofil yaprakları'], 'Kapalı tohumlularda çenek sayısı bir veya iki iken, çam ve göknar gibi açık tohumlularda tohum çimlendiğinde 4 ila 18 adet iğnemsi çenek yaprağı (polikotiledoni) görülür.'),
  ('Türkiye\'de Adana-Osmaniye\'den başlayıp Kahramanmaraş ve Antakya\'ya uzanan Amanos ve Doğu Toros kuşağında doğal yayılış gösteren göknar türü hangisidir?', 'Toros göknarı (Abies cilicica)', ['Uludağ göknarı (Abies nordmanniana subsp. bornmuelleriana)', 'Kazdağı göknarı (Abies nordmanniana subsp. equi-trojani)', 'Doğu Karadeniz göknarı (Abies nordmanniana subsp. nordmanniana)'], 'Toros göknarı Güney Anadolu\'nun yüksek dağ kuşağında (1100-2000 m) genellikle Toros sediri ve karaçam ile karışık veya saf ormanlar kurar.'),
  ('Güney Yarımküre\'ye özgü olan, gövde ve dallarını kiremit gibi saran sert üçgenimsi dikenli yaprakları nedeniyle \'maymun çıkmaz ağacı\' olarak bilinen açık tohumlu hangisidir?', 'Şili arokaryası (Araucaria araucana)', ['Tasmanya sediri (Athrotaxis cupressoides)', 'Mavi ladin (Picea pungens)', 'Atlas sediri (Cedrus atlantica)'], 'And Dağları kökenli Araucaria araucana, sürüngen pullarını andıran keskin kenarlı ve çok sert yapraklarıyla tırmanmayı imkânsız kıldığı için bu adla anılır.'),
  ('İbreli ağaçlarda erkek ve dişi kozalakların aynı ağaç üzerindeki tipik konumlanması kendi kendine tozlaşmayı azaltacak biçimde nasıl düzenlenmiştir?', 'Dişi kozalaklar genellikle ağacın üst dallarında, erkek kozalaklar ise alt dallarda yer alır', ['Erkek kozalaklar yalnızca tepe sürgününde, dişi kozalaklar kök boğazına yakın gövdede çıkar', 'Her bir ağaç bireyi ömrünün ilk yarısında yalnız erkek, ikinci yarısında yalnız dişi kozalak üretir', 'Dişi ve erkek sporofiller her zaman aynı tekil kozalak ekseni üzerinde iç içe dizilir'], 'Çoğu tek evcikli çam ve göknarda dişi kozalakların üstte olması, alt dallardan yükselen kendi polenlerinden ziyade yan ağaçlardan rüzgârla gelen polenleri yakalamayı kolaylaştırır.'),
  ('İğne yaprakların enine kesiti incelendiğinde stomaların yaprak yüzeyinden içeriye doğru çukurlara gömülü olmasının bitkiye sağladığı temel yarar nedir?', 'Durgun hava tabakası oluşturarak rüzgârlı ve donlu havalarda terlemeyle su kaybını düşürmek', ['Yağmur damlalarının doğrudan mezofil dokusuna girerek hücre turgorunu artırmasını sağlamak', 'Kloroplastların doğrudan morötesi ışınlara maruz kalarak daha hızlı ATP üretmesini sağlamak', 'Kış aylarında polen tanelerinin yaprak gözeneklerine tutunarak çimlenmesini kolaylaştırmak'], 'Toprak donduğunda kökler su alamadığı için ibreliler fizyolojik kuraklık yaşar; gömülü stoma ve kalın mumlu kütikula kışın su kaybını minimuma indirir.'),
  ('Park ve bahçelerde çit bitkisi olarak da sıkça yetiştirilen, yapraklı sürgünleri yanlardan basık düzlemler oluşturan ve küçük odunsu kozalak pulları geriye çengel gibi kıvrık olan ağaççık hangisidir?', 'Doğu mazısı (Platycladus orientalis)', ['Katran ardıcı (Juniperus oxycedrus)', 'Sahil çamı (Pinus pinaster)', 'Gümüşi ıhlamur (Tilia tomentosa)'], 'Servigillerden Doğu mazısı, dikey düzlemler halinde dizilmiş yassı pul yapraklı sürgünleri ve çengelli pullara sahip küçük kozalaklarıyla kolayca tanınır.'),
  ('Bir çam kozalağı yağmurlu ve nemli bir günde incelendiğinde pullarının sımsıkı kapandığı, kuru ve güneşli günde ise geriye doğru açıldığı gözlenir. Bu higroskopik hareketin amacı nedir?', 'Kanatlı tohumların yalnızca rüzgârla uzağa uçabileceği kuru havalarda serbest kalmasını sağlamak', ['Yağmur suyunu kozalak içine hapsederek tohumların dal üzerindeyken çimlenmesini başlatmak', 'Nemli havalarda polen keselerini koruyup kuru havalarda polen tüpünü yumurtalığa uzatmak', 'Kozalak pullarındaki klorofil miktarını güneşli günlerde artırarak ek fotosentez yapmak'], 'Ölü sklerankima liflerinin iç ve dış katmanlarındaki farklı su çekme-büzülme oranı kozalak pullarını nemde kapatır, kuruda açar; böylece tohumlar yağmurda yere yapışmak yerine kuru havada uçuşur.'),
  ('Himalaya Dağları\'nın nemli yamaçlarına özgü olan ve yan dallarının uçları ile tepe sürgünü zarifçe aşağı doğru sarktığı için diğer gerçek sedirlerden kolayca ayrılan tür hangisidir?', 'Himalaya sediri (Cedrus deodara)', ['Kıbrıs sediri (Cedrus brevifolia)', 'Toros sediri (Cedrus libani)', 'Mavi ladin (Picea pungens)'], 'Cedrus deodara uzun ibreleri (3-5 cm) ve belirgin biçimde sarkan tepe ve dal uçlarıyla Toros ve Atlas sedirinden hemen ayırt edilir.'),
  ('Fransa\'nın Landes bölgesinde kıyı kumullarını sabitlemek amacıyla geniş çapta dikilen ve Türkiye\'de de Karadeniz ile Marmara kıyı kumullarında ağaçlandırmada kullanılan iri kozalaklı çam hangisidir?', 'Sahil çamı (Pinus pinaster)', ['Sarıçam (Pinus sylvestris)', 'İsviçre fıstıkçamı (Pinus cembra)', 'Dağ çamı (Pinus mugo)'], 'Batı Akdeniz kökenli sahil çamı (Pinus pinaster), tuzlu deniz rüzgârlarına ve fakir kumul topraklarına dayanıklılığı ile erozyon kontrolünde öne çıkar.'),
  ('Kemanda ses tahtası (rezonans kapağı) ve piyano gövdesi yapımında düzgün lifli, hafif ama esnek yapısı nedeniyle en çok aranan ağaç odunu hangi ibreli cinse aittir?', 'Ladin (Picea)', ['Ardıç (Juniperus)', 'Porsuk (Taxus)', 'Fıstıkçamı (Pinus)'], 'Avrupa ladini ve Sitka ladini gibi türlerin eşit aralıklı yıllık halkalara sahip, düşük yoğunluklu ve yüksek ses iletim hızlı odunu yaylı çalgı yapımında standarttır.'),
  ('Çam ve ladin fidelerinin orman toprağında sağlıklı büyüyebilmesi için kök uçlarını eldiven gibi saran simbiyotik mantar birlikteliğine ne ad verilir?', 'Ektomikoriza', ['Azot bağlayıcı rizobyum nodülü', 'Parazitik ökseotu emeçleri', 'Liken soredyum birliği'], 'İbreli orman ağaçlarının büyük çoğunluğu Basidiomycota ve Ascomycota mantarlarıyla ektomikoriza kurar; mantar hifleri su ve fosfor emilim yüzeyini katbekat artırır.'),
  ('Bozkırdan ibreli orman kuşağına yeni dönüştürülen çıplak bir arazide çam fidanlarının sararıp gelişememesi üzerine fidan çukurlarına eski çam ormanından bir avuç toprak eklenmesinin bilimsel nedeni nedir?', 'Toprağa fidan kökleriyle ortak yaşam kuracak mikoriza mantarı sporlarını aşılamak', ['Eski orman toprağındaki çürümüş reçine asitleriyle yabancı ot tohumlarını yakmak', 'Toprağın pH değerini hızla bazikleştirerek kireç oranını en üst düzeye çıkarmak', 'Çam kese böceği larvalarını ortama taşıyarak doğal besin zincirini başlatmak'], 'Ağaçsız bozkır topraklarında çamlara özgü ektomikorizal mantar florası bulunmayabilir; orman toprağı aşısı fidanların mineral alımını ve tutunma başarısını büyük ölçüde yükseltir.'),
  ('Ormancılıkta çam kese böceğiyle kimyasal ilaç kullanmadan biyolojik mücadele yürütülürken orman içine salınan \'Calosoma sycophanta\' adlı canlı hangi işlevi üstlenir?', 'Hem ergin hem larva döneminde çam kese böceği tırtıllarını avlayan yırtıcı böcek olarak görev yapar', ['Kızılçam ibrelerinin üzerini mumsu bir salgıyla kaplayarak tırtılların yaprağı ısırmasını engeller', 'Çam kozalaklarının içine yumurta bırakarak tohumların daha erken çimlenmesini hızlandırır', 'Ağaç kabuklarındaki reçine kanallarını genişleterek mantar hastalıklarını temizler'], 'Metalik yeşil renkli güzel avcı böcek (Calosoma sycophanta), ağaçlara tırmanarak kese böceği tırtıllarını ve pupalarını tüketen en etkili biyolojik mücadele ajanıdır.'),
  ('Görünüşte gövdesi ve tüysü yaprak tacı nedeniyle palmiyelerle sıkça karıştırılan ancak çiçek yerine gövde tepesinde iri kozalaklar oluşturan tropikal açık tohumlu grup hangisidir?', 'Sikaslar (Cycadophyta)', ['Bambular (Poaceae)', 'Ağaç eğreltileri (Cyatheales)', 'Pandanuslar (Pandanaceae)'], 'Cycas revoluta (sago palmiyesi) gibi sikaslar gerçekte palmiye (kapalı tohumlu monokotil) olmayıp Mezozoik\'te yaygınlaşmış ayrı eşeyli açık tohumlu bitkilerdir.'),
  ('Yüksek dağlarda orman sınırının hemen üzerinde yatık ve çalımsı formda büyüyerek çığ düşmesini engelleyen, çok gövdeli bodur Avrupa çamı aşağıdakilerden hangisidir?', 'Dağ çamı (Pinus mugo)', ['Fıstıkçamı (Pinus pinea)', 'Halep çamı (Pinus halepensis)', 'Kanarya çamı (Pinus canariensis)'], 'Orta ve Güney Avrupa dağlarının subalpin kuşağında yayılan Pinus mugo, sert rüzgâr ve kar yükü altında yere yatık çalı toplulukları (krummholz) kurar.'),
  ('Orman yangınlarına karşı kalın mantarımsı kabuğu sayesinde ileri yaşlarda yüksek direnç gösteren, yaşlandıkça tepe tacı şemsiye gibi düzleşen Anadolu dağ çamı hangisidir?', 'Karaçam (Pinus nigra)', ['Doğu ladini (Picea orientalis)', 'Adi porsuk (Taxus baccata)', 'Uludağ göknarı (Abies nordmanniana)'], 'Yaşlı karaçam bireyleri derin çatlaklı ve kalın kabukları sayesinde örtü yangınlarını gövde kambiyumu zarar görmeden atlatabilir; yaşlılıkta tepeleri yassılaşır.'),
  ('Çamgiller familyasındaki ağaçların çoğunda tohumun bir ucuna bağlı ince zarsı bir kanat bulunurken, fıstıkçamında (Pinus pinea) bu kanadın çok körelmiş ve işlevsiz olmasının ekolojik karşılığı nedir?', 'Ağır ve yağlı tohumların rüzgâr yerine sincap ve kargagiller gibi hayvanlarca taşınarak yayılması', ['Tohumların deniz akıntılarıyla kıtalar arası yüzerek kıyı kumullarına yerleşmesi', 'Kozalak pullarının patlayıcı basınçla tohumları otuz metre uzağa fırlatması', 'Tohumların ağaç üzerindeyken çimlenip fide halinde toprağa saplanması'], 'İri ve besin deposu yüksek fıstıkçamı tohumları rüzgârla uçamayacak kadar ağırdır; kışlık besin saklayan kuş ve kemirgenlerin gömdüğü tohumlar yeni fidanları oluşturur.'),
  ('Sarıçam ve kızılçam gibi çam türlerinde yeni uzayan yıllık sürgünlerin ilkbaharda mum gibi dik yükselmesine ormancılık terminolojisinde ne ad verilir?', 'Mayıs sürgünü', ['Kök boğazı piçi', 'Kütük sürgünü', 'Hava kökü uzantısı'], 'Çamlarda ilkbaharda tomurcuktan hızla uzayan ve henüz ibreleri yanlara açılmamış dik sürgünler mumlara benzediği için mum sürgünü olarak adlandırılır.'),
  ('Geleneksel olarak çam ağaçlarının gövdesinde V biçimli oluklar açılarak toplanan ham reçinenin su buharı distilasyonuyla işlenmesi sonucunda hangi iki temel sanayi ürünü elde edilir?', 'Terebentin yağı ve kolofan', ['Etil alkol ve selüloz asetat', 'Tanen özütü ve doğal kauçuk lateksi', 'Kinin kristali ve salisilik asit'], 'Kızılçam ve sahil çamı reçinesi damıtıldığında uçucu sıvı fraksiyon olarak terebentin çözücüsü, katı reçine kalıntısı olarak da keman yayı ve lehimde kullanılan kolofan elde edilir.'),
  ('Gölgeye dayanıklılık (tolerans) bakımından Türkiye\'deki ibreli ağaçlar karşılaştırıldığında, yaşlı bir ormanın kapalılığı altında uzun yıllar gölgede yaşayıp ışık açıldığında hızla büyüyebilen tür hangisidir?', 'Göknar', ['Kızılçam', 'Sarıçam', 'Fıstıkçamı'], 'Göknar ve porsuk tipik gölge ağaçlarıdır; kızılçam, sarıçam ve fıstıkçamı ise mutlak ışık ağaçları olup kapalı orman altında gençlikleri yaşayamaz.'),
  ('Tam bir ışık ağacı olan sarıçam veya kızılçamın sık ve kapalı büyüyen meşcerelerinde gövdenin alt kısımlarındaki dalların kuruyup kendiliğinden dökülmesi olayı nasıl adlandırılır?', 'Doğal dal budanması', ['Tepe kuruma sendromu', 'Mevsimsel absisyon', 'Kambiyum nekrozu'], 'Işık ağaçlarında alt dallar yeterli güneş alamayınca fotosentez solunumu karşılayamaz; bu dallar kuruyup dökülür ve düğümsüz (budaksız) düzgün kereste gövdesi oluşur.'),
  ('Toros sedirinin gençlik yıllarında piramidal yükselen tepe tacının ileri yaşlarda şemsiye veya tabla gibi düzleşmesinin ekolojik nedeni nedir?', 'Yüksek dağ kuşağındaki şiddetli rüzgârlar, kar baskısı ve tepe sürgünü büyümesinin yavaşlaması', ['Yaşlı ağaçların kök sisteminin kireçtaşı tabakasına ulaştığında su alımını tamamen kesmesi', 'Sedir kelebeği larvalarının yalnızca yüz yaşını geçen ağaçların tepe tomurcuğunu yemesi', 'Alt dalların yukarı doğru bükülerek ana gövdeyle tepe noktasında kaynaşması'], 'Toros sediri gençken sivri konik taç yaparken 80-100 yaşından sonra boy büyümesi yavaşlar, yan dallar kalınlaşıp yatay uzar ve karakteristik düz tepeli anıtsal görünüm kazanır.'),
  ('Ardıç türlerinin kerestesi geçmişte kurşun kalem gövdesi yapımında dünya çapında neden yoğun biçimde tercih edilmiştir?', 'Düzgün dokulu, kolay yontulabilen, kıymıklanmayan ve hoş kokulu pembe-kızıl öz oduna sahip olması', ['Grafit ucu kendi reçinesiyle siyaha boyayarak ek maden kullanımını gerektirmemesi', 'Suyla temas ettiğinde taşlaşarak kırılmaz bir seramik sertliğine ulaşması', 'Hiç yaş halkası içermediği için bükülebilir kauçuk esnekliği göstermesi'], 'Doğu kırmızı sediri (Juniperus virginiana) ve boylu/kokulu ardıç türlerinin homojen, yumuşak ve kalemtıraşta pürüzsüz açılan hoş kokulu odunu kalem sanayisinin temel hammaddesi olmuştur.'),
  ('Japonya\'nın ulusal ağacı kabul edilen, tapınak yollarında yüzlerce yıllık dev sıralar oluşturan ve \'Sugi\' adıyla bilinen ibreli tür aşağıdakilerden hangisidir?', 'Japon çamı / Japon sediri (Cryptomeria japonica)', ['Kore göknarı (Abies koreana)', 'Çin ardıcı (Juniperus chinensis)', 'Himalaya ladini (Picea smithiana)'], 'Servigiller (Cupressaceae) familyasına dahil olan Cryptomeria japonica, biz biçimli kıvrık ibreleri ve kızılımsı lifli kabuğuyla Japon ormancılığının en önemli türüdür.'),
  ('Kök ve gövde büyümesi kap içinde sınırlandırılıp düzenli tel sarma ve budama teknikleriyle minyatür yaşlı ağaç görünümü kazandırılan \'bonsai\' sanatında en sık kullanılan beş ibreli çam hangisidir?', 'Japon beyaz çamı (Pinus parviflora)', ['Kızılçam (Pinus brutia)', 'Sahil çamı (Pinus pinaster)', 'Uzun yapraklı çam (Pinus palustris)'], 'Pinus parviflora kısa, mavimsi yeşil beşli ibre demetleri ve kolay şekil alan gövdesiyle klasik bonsai sanatının en gözde ibreli türlerindendir.'),
  ('Türkiye\'de doğal yayılış gösteren ardıç türleri arasında sürgünleri elle ovuşturulduğunda ağır ve keskin bir koku yayan, yüksek dağ kuşağında anıtsal bireyler yapabilen tür hangisidir?', 'Kokulu ardıç (Juniperus foetidissima)', ['Adi ardıç (Juniperus communis)', 'Bodur ardıç (Juniperus nana)', 'Finike ardıcı (Juniperus phoenicea)'], 'Kokulu ardıç kalın dört köşeli pul yapraklı sürgünleri ve ezildiğinde yaydığı karakteristik keskin kokusuyla boylu ardıçtan ayrılır; Toroslar\'da bin yaşını aşan bireyleri vardır.'),
  ('Ağaç halkaları bilimi olan dendrokronolojide geçmiş bin yılların iklim ve kuraklık kayıtlarını çıkarmak için ibreli dağ ağaçlarının özellikle tercih edilmesinin nedeni nedir?', 'Uzun ömürlü olmaları ve ekstrem yüksek irtifa sınırında iklim dalgalanmalarına duyarlı net yıllık halkalar üretmeleri', ['Her mevsimde dört ayrı halka oluşturarak aylık yağış miktarını milimetrik göstermeleri', 'Gövde merkezindeki öz odunun zamanla eriyip yalnızca son yüz yılın halkalarını saklaması', 'Tropikal yağmur ormanlarında yetişerek ekvatoral sıcaklık değişimlerini kaydetmeleri'], 'Bristlecone çamı, Toros sediri ve ardıç gibi ağaçlar yarı kurak/soğuk sınırda büyüdüklerinden yağışlı ve kurak yıllar halka genişliklerine çok belirgin yansır.'),
  ('Toros sedirinin doğal gençleştirmesinde ormancıların kozalak pulları dağılmadan sonbaharda topladıkları tohumları kar altına veya sonbahar sonuna ekmelerinin fizyolojik nedeni nedir?', 'Tohum kabuğundaki çimlenme engelini kırmak için soğuk-nemli katlama ihtiyacını karşılamak', ['Tohumların kış ortasında otuz derece sıcaklıkta hızla kök salmasını sağlamak', 'Reçineli tohumların güneş ışığı görmeden karanlıkta fotosentez yapmasını başlatmak', 'Topraktaki kireci eritmek için tohumlardan sitrik asit salgılanmasını tetiklemek'], 'Sedir ve birçok yüksek dağ ibrelisinin tohumları kış soğuğunu ve nemini yaşadıktan (vernalizasyon/soğuk katlama) sonra erken ilkbaharda kar erirken çimlenir.'),
  ('Kızılçam ibreleri ile karaçam ibreleri yan yana getirilip büküldüğünde ve uçlarına dokunulduğunda arazide hangi pratik fark gözlemlenir?', 'Karaçam ibreleri daha kalın, sert, koyu yeşil ve batıcı iken kızılçam ibreleri daha ince, esnek ve açık yeşildir', ['Kızılçam ibreleri beşli demetler halinde sert dikenli iken karaçam ibreleri tekli ve yumuşaktır', 'Karaçam ibreleri yassı ve alt yüzü beyaz çizgili iken kızılçam ibreleri dört köşeli pul şeklindedir', 'Her iki türün ibreleri de sonbaharda tamamen döküldüğü için kışın yalnız tomurcuktan ayrılır'], 'İkisi de ikili ibre demetine sahip olsa da karaçamın ibreleri serttir ve ikiye katlandığında kırılmaya dirençli/batıcıdır; kızılçamınkiler ince ve açık çimen yeşilidir.'),
  ('Mavi ladin veya göknar ağaçlarının budama sırasında tepe sürgünü (lider sürgün) kesilirse ağaçta hangi gelişim tepkisi ortaya çıkar?', 'Üst halkadaki yan dallardan biri veya birkaçı yukarı kıvrılarak yeni lider tepe sürgünü olmaya çalışır', ['Ağaç boyuna ve enine büyümeyi ömür boyu tamamen durdurarak çalı kalır', 'Kök boğazından onlarca yeni gövde çıkararak ana gövdeyi tamamen kurutur', 'Kozalak üretimi tamamen durur ve tüm ibreler bir ay içinde dökülür'], 'Tepe tomurcuğunun salgıladığı oksin kalkınca apikal dominans bozulur; üst yan dallar negatif geotropizma göstererek yukarı döner ve bazen çift tepeli (çatallı) gövde oluşur.'),
  ('Akdeniz kıyılarında denize çok yakın kayalık yamaçlarda doğal olarak yetişen, koyu kırmızımsı-kahverengi küremsi kozalaklara ve pul yapraklara sahip ardıç türümüz hangisidir?', 'Finike ardıcı (Juniperus phoenicea)', ['Sarıçam (Pinus sylvestris)', 'Doğu ladini (Picea orientalis)', 'Uludağ göknarı (Abies nordmanniana)'], 'Finike ardıcı Batı ve Güney Anadolu\'nun kıyı maki kuşağında kireçli kayalıklarda yetişen, tuza ve kuraklığa çok dayanıklı pul yapraklı bir ardıç türüdür.'),
  ('Ege Bölgesi\'nde geleneksel deri tabaklamada kullanılan yüksek tanenli dev kadehleriyle ünlü olan ve kırsal tarım arazilerinde tekil anıt ağaçlar halinde korunan meşe türü hangisidir?', 'Palamut meşesi (Quercus ithaburensis subsp. macrolepis)', ['Saplı meşe (Quercus robur)', 'Karadeniz sapsız meşesi (Quercus petraea)', 'Kermes meşesi (Quercus coccifera)'], 'Palamut meşesinin \'valeks\' adı verilen iri pullu kadehleri çok yüksek oranda tanen içerdiğinden yüzyıllarca dericilik sanayisinde ve boyamacılıkta kullanılmıştır.'),
  ('Akdeniz maki kuşağında sert, batıcı dikenli kenarlara sahip küçük yapraklarıyla dört mevsim yeşil kalan ve keçi otlatmasına karşı sık çalı kümeleri oluşturan meşe hangisidir?', 'Kermes meşesi (Quercus coccifera)', ['Macar meşesi (Quercus frainetto)', 'İspir meşesi (Quercus macranthera)', 'Kasnak meşesi (Quercus vulcanica)'], 'Piynar veya pırnal meşesi olarak da bilinen kermes meşesi her dem yeşil, sert ve dikenli yapraklı tipik bir maki elemanıdır.'),
  ('Isparta Eğirdir Yukarıgökdere ve Kütahya Türkmenbaba çevresinde sınırlı yayılış gösteren, düzgün gövdesi nedeniyle geçmişte fıçı ve elek kasnağı yapımında kullanılmış endemik meşe türümüz hangisidir?', 'Kasnak meşesi (Quercus vulcanica)', ['Boz pırnal meşesi (Quercus aucheri)', 'Saçlı meşe (Quercus cerris)', 'Mazı meşesi (Quercus infectoria)'], 'Kasnak meşesi Türkiye\'nin en değerli endemik geniş yapraklı ağaçlarından biri olup gözeneksiz ve kolay bükülebilen kaliteli odunu nedeniyle bu adı almıştır.'),
  ('Ormanda sıkça birbirine karıştırılan kayın ve gürgen ağaçlarının yaprak kenarları incelendiğinde hangi güvenilir morfolojik fark görülür?', 'Kayın yaprağı tam veya hafif dalgalı kenarlı ve kirpikli iken gürgen yaprağı keskin çift sıra dişlidir', ['Kayın yaprağı elsi beş loblu ve derin parçalı iken gürgen yaprağı iğnemsi şerit biçimlidir', 'Gürgen yaprağı tüysü bileşik yapıda on bir yaprakçıklı iken kayın yaprağı kalkan şeklindedir', 'Her iki türün yaprakları da sert dikenli olup kış aylarında dal üzerinde koyu yeşil kalır'], 'Kayın (Fagus) yaprakları tam/dalgalı kenarlı ve gençken kenarı ipeksi tüylüdür; gürgen (Carpinus) yaprakları ise belirgin paralel yan damarlı ve keskin çift dişli kenarlıdır.'),
  ('Kuzey yarımkürenin soğuk bölgelerinde ve Doğu Anadolu\'nun yüksek dağlarında (örneğin Nemrut Kalderası ve Ağrı Dağı eteklerinde) tebeşir beyazı soyulan gövde kabuğuyla hemen seçilen ağaç hangisidir?', 'Siğilli huş (Betula pendula)', ['Çoruh meşesi (Quercus petraea)', 'Kafkas ıhlamuru (Tilia rubra)', 'Dağ karaağacı (Ulmus glabra)'], 'Huş ağaçlarının dış kabuğunda bulunan \'betulin\' adlı beyaz triterpen pigmenti gövdeye parlak beyaz renk verir ve kış güneşinin gövdeyi çatlatmasını önler.'),
  ('Kış çaylarının sevilen bitkisi olan ıhlamur ağacında çiçek salkımının sapına yarıya kadar kaynaşmış halde bulunan kayış biçimli açık yeşil yaprakçığın (brakte) temel görevi nedir?', 'Olgunlaşan küremsi meyvelerin rüzgârda pervane gibi dönerek ana ağaçtan uzağa taşınmasını sağlamak', ['Gece uçan güveleri zehirli salgısıyla uzaklaştırarak çiçek nektarını yalnızca arılara saklamak', 'Yağmur suyunu oluk gibi toplayarak doğrudan çiçeğin tepecik yüzeyine akıtmak', 'Kış aylarında dökülmeyerek gövde kabuğunun yerini alıp fotosentezi sürdürmek'], 'Ihlamur çiçek kurulundaki dil biçimli brakte hem şifalı çayda kullanılır hem de sonbaharda tohum salkımı koptuğunda dönerek süzülen bir uçma kanadı işlevi görür.'),
  ('Bursa, Yalova ve Batı Karadeniz kuşağında ıhlamur balı üretiminin ana kaynağını oluşturan, yapraklarının alt yüzü yıldız tüylerle kaplı olduğu için rüzgârda gümüş gibi parlayan tür hangisidir?', 'Gümüşi ıhlamur (Tilia tomentosa)', ['Küçük yapraklı ıhlamur (Tilia cordata)', 'Büyük yapraklı ıhlamur (Tilia platyphyllos)', 'Amerikan ıhlamuru (Tilia americana)'], 'Gümüşi ıhlamurun yaprak altındaki yoğun beyaz-gümüşi tüy örtüsü hem terlemeyi azaltarak kuraklığa direnç sağlar hem de ağaca uzaktan parlak görünüm verir.'),
  ('Parklarda gölge ağacı olarak yetişen \'at kestanesi\' (Aesculus hippocastanum) ile yenilebilir \'Anadolu kestanesi\' (Castanea sativa) karşılaştırıldığında hangi ifade doğrudur?', 'Farklı familyalarda yer alırlar; at kestanesinin yaprakları elsi bileşik ve tohumları insanlar için acı-zehirlidir', ['Aynı cinsin iki alt türüdürler; at kestanesi aşılandığında doğrudan tatlı kestane meyvesi verir', 'At kestanesi açık tohumlu bir ağaç iken Anadolu kestanesi tek çenekli otsu gövdeli bir bitkidir', 'Anadolu kestanesinin yaprakları yedi parçalı elsi bileşik iken at kestanesinin yaprakları iğnemsidir'], 'At kestanesi Sapindaceae familyasındandır, 5-7 yaprakçıklı elsi bileşik yaprakları vardır ve tohumları saponin (eskülin) içerdiği için yenmez; tatlı kestane ise basit mızraksı yapraklıdır.'),
  ('En hafif esintide bile yapraklarının hışırtıyla titremesini sağlayan ve türe \'titrek kavak\' (Populus tremula) adını kazandıran yaprak sapı özelliği aşağıdakilerden hangisidir?', 'Uzun yaprak sapının yaprak ayası düzlemine dik gelecek biçimde yanlardan yassılaşmış olması', ['Yaprak tabanında su basıncını saniyede bir değiştiren motor hücre yastıkçıkları bulunması', 'Yaprak ayasının ortasında rüzgârı içeri alıp döndüren huni şeklinde bir delik yer alması', 'Her yaprağın ucunda havadaki elektrostatik yükle itilen ince tüysü uzantılar bulunması'], 'Titrek kavakta yaprak sapı (petiyol) yanal olarak yassıdır; bu biyomekanik yapı en küçük hava akımında bile yaprağın sağa sola bükülmesini sağlayarak aşırı ısınmayı ve rüzgâr direncini azaltır.'),
  ('Kavak ve söğüt ağaçlarının bulunduğu mahallelerde mayıs-haziran aylarında havada uçuşan beyaz pamukçukların biyolojik işlevi nedir?', 'Dişi ağaçların kapsül meyvelerinden çıkan çok küçük tohumları rüzgârla uzaklara taşımak', ['Erkek ağaçların ürettiği ağır polen tanelerini arıların bacaklarına yapıştırmak', 'Ağaç yapraklarını yaz başında yakıcı güneş ışınlarından koruyan tüy örtüsünü yenilemek', 'Kavak kese yaprakbitlerinin salgıladığı mumsu ipliklerle yeni sürgünlere göç etmesini sağlamak'], 'Salicaceae familyası iki evciklidir; pamukçuklar polen değil, dişi bireylerin olgun kapsüllerinden çıkan tüylü (komalı) tohumlardır.'),
  ('Akdeniz ikliminin simgesi olan zeytin ağacının (Olea europaea) yapraklarının üst yüzü koyu yeşil ve derimsi, alt yüzü ise gümüşi-beyaz pullu tüylerle kaplıdır. Bu yapının sağladığı uyum nedir?', 'Yaz kuraklığında güneş ışığını geri yansıtmak ve alt yüzdeki stomaların su kaybını azaltmak', ['Kış yağmurlarını yaprak altındaki tüylerden doğrudan floem borularına emmek', 'Tuzlu deniz serpintisini yaprak dokusunda biriktirerek meyvelerin yağ oranını yükseltmek', 'Gece karanlığında ay ışığını toplayarak kesintisiz fotosentez yapılmasını sağlamak'], 'Sklerofil (sert yapraklı) bir ağaç olan zeytinde şemsiyemsi kalkan tüyler (peltat trikomlar) alt yüzde bulunan stomaları örterek sıcak yaz rüzgârlarında terlemeyi frenler.'),
  ('Tohumlarının kütlesi doğada birbirine şaşırtıcı derecede yakın (yaklaşık 0,2 gram) olduğu için tarih boyunca elmas ve altın tartımında \'karat\' ölçü birimine kaynaklık eden Akdeniz ağacı hangisidir?', 'Keçiboynuzu / Harnup (Ceratonia siliqua)', ['Zeytin ağacı (Olea europaea)', 'Sakız ağacı (Pistacia lentiscus)', 'Hünnap ağacı (Ziziphus jujuba)'], 'Yunanca \'keration\' ve Arapça \'kırat\' sözcüklerinden türeyen karat birimi, bakla biçimli tatlı meyveler veren keçiboynuzu ağacının sert tohumlarına dayanır.'),
  ('Karadeniz Bölgesi\'nde özellikle Sürmene ve Rize çevresinde kaşık, kepçe ve tarak gibi el sanatları ürünlerinin yapımında kullanılan; çok yavaş büyüdüğü için kemik kadar sert ve ağır odun üreten çalı/ağaççık hangisidir?', 'Adi şimşir (Buxus sempervirens)', ['Adi fındık (Corylus avellana)', 'Taflan / Karayemiş (Prunus laurocerasus)', 'Mor çiçekli ormangülü (Rhododendron ponticum)'], 'Şimşir ağacının odunu suya bırakıldığında batacak kadar yüksek yoğunlukludur (yaklaşık 0,95-1,05 g/cm³), gözeneksiz ve sarımsı fildişi dokusuyla oymacılıkta eşsizdir.'),
  ('Aynı tekil dut veya incir ağacının dallarına bakıldığında bazı yaprakların hiç bölünmemiş tam ayalı, hemen yanındaki yaprakların ise üç veya beş derin loblu olması hangi botanik kavramla açıklanır?', 'Heterofili (farklı yapraklılık)', ['Partenokarpi (çekirdeksiz meyve)', 'Fotoperiyodizm (gün uzunluğu tepkisi)', 'Epikotil uzaması'], 'Bir bitki bireyi üzerinde yaşa, ışıklanmaya veya sürgün tipine bağlı olarak farklı morfolojide yaprakların bir arada bulunmasına heterofili denir; dut ve sığla ağaçlarında çok belirgindir.'),
  ('Güneydoğu ve Akdeniz dağlarında doğal olarak yetişen yabani menengiç (Pistacia terebinthus) ağaçlarına köylülerin kalem aşısı uygulayarak dönüştürdüğü yüksek ekonomik değerli kültür ağacı hangisidir?', 'Antepfıstığı (Pistacia vera)', ['Badem ağacı (Prunus dulcis)', 'Ceviz ağacı (Juglans regia)', 'Zerdali ağacı (Prunus armeniaca)'], 'Kurak ve taşlık yamaçlarda kendiliğinden yetişen menengiç ve buttum ağaçları güçlü kök sistemine sahip doğal anaçlardır; üzerlerine Antepfıstığı aşılanarak verimli bahçeler kurulur.'),
  ('Meşe, kayın, ceviz, fındık ve kestane ağaçlarında ise aynı tekil ağaç üzerinde erkek çiçekler sarkık kedicikler halinde, dişi çiçekler ise ayrı tomurcuklarda bulunur. Bu üreme düzeni nasıl adlandırılır?', 'Tek evcikli (monoik) ve ayrı eşeyli çiçekli olma', ['İki evcikli (dioik) ve yalnız rüzgârsız tozlaşma yapma', 'Çiçek yaprakları kaynaşmış tam erselik olma', 'Vejetatif yumrularla eşeysiz klonal çoğalma'], 'Monoik ağaçlarda erkek ve dişi çiçekler ayrı ayrıdır (tek eşeyli çiçek) fakat her ikisi de aynı ağaç bireyinin dalları üzerinde yer alır.'),
  ('Karadeniz kıyı kuşağının tarımsal simgesi olan fındık ocağının (Corylus avellana) kış ortasında (ocak-şubat aylarında) dallarından sarkan sarı püsküller hangi işlevi görür?', 'Henüz yapraklanma başlamadan rüzgârla tozlaşmayı gerçekleştiren erkek çiçek kurullarıdır', ['Geçen yıldan kalan ve ilkbaharda yere düşüp kök salacak olan çimlenmiş tohum salkımlarıdır', 'Kış donlarına karşı tomurcukları ısıtan reçineli koruyucu sürgün kılıflarıdır', 'Bal arılarını kış uykusundan uyandırmak için nektar salgılayan taç yaprak demetleridir'], 'Fındık rüzgârla tozlaşır; kış ortasında uzayan sarı kedicikler polen saçar, dişi çiçekler ise tomurcuk ucundan çıkan minik kırmızı püsküller (stigma) halindedir.'),
  ('Bozkır ve yarı kurak Anadolu vadilerinde yetişen, gümüşi pullu dar yapraklara sahip olan ve köklerindeki simbiyotik bakterilerle toprağa azot bağladığı için erozyon sahalarında dikilen kokulu çiçekli ağaç hangisidir?', 'Kuş iğdesi / İğde ağacı (Elaeagnus angustifolia)', ['Ahlat / Yabani armut (Pyrus elaeagnifolia)', 'Alıç ağacı (Crataegus monogyna)', 'Muşmula ağacı (Mespilus germanica)'], 'İğde ağacı kuraklığa, tuzluluğa ve fakir topraklara olağanüstü dayanıklıdır; köklerindeki Frankia aktinomisetleri sayesinde azot bağlar ve ilkbahar sonunda keskin hoş kokulu sarı çiçekler açar.'),
  ('İç Anadolu bozkırlarında tek başına yükselen dikenli dallı \'ahlat\' (Pyrus elaeagnifolia) ağaçlarının kurak mera ortasında kesilmeden korunmasının ve çobanlarca aşılanmasının temel nedeni nedir?', 'Derin kazık köküyle susuz kıraçta yaşayabilmesi ve kültür armudu için mükemmel kuraklık anacı olması', ['Yapraklarının kış ortasında bile dökülmeyerek koyun sürülerine taze yeşil yem sağlaması', 'Gövde kabuğundan elde edilen beyaz lateksin çoban kepeneklerini su geçirmez yapması', 'Köklerinden çıkan yan sürgünlerin bir yılda on metre boylanarak kereste vermesi'], 'Yabani armut (ahlat), bozkır kuraklığına dayanıklı derin kök sistemi sayesinde Anadolu\'da yüzyıllardır kültür armudu çeşitlerinin aşılandığı hayati bir ağaçtır.'),
  ('Güney Amerika ve Karayipler\'e özgü olan, kano ve model uçak yapımında tercih edilen \'balsa ağacı\' (Ochroma pyramidale) odununun sudan çok daha hafif (yoğunluğu ~0,12 g/cm³) olmasının anatomik nedeni nedir?', 'Çok hızlı büyüyen odun dokusunun ince çeperli, geniş boşluklu ve hava dolu büyük parankima hücrelerinden oluşması', ['Hücre duvarlarında selüloz yerine yalnızca içi helyum gazı dolu lipit kesecikleri bulunması', 'Gövdenin merkez kısmının bambu gibi tamamen boş bir boru şeklinde gelişmesi', 'Ağacın yalnızca su yüzeyinde yüzen bir su bitkisi olup kök ve gövde lifi üretmemesi'], 'Balsa bir yağmur ormanı öncü ağacıdır; ışık boşluklarını hızla doldurmak için kalın duvarlı liflere yatırım yapmaz, ince çeperli dev hücreleri kuruduğunda hava ile dolarak strafor hafifliği verir.'),
  ('Ormancılıkta \'baltalık işletmesi\' olarak adlandırılan üretim yönteminde meşe, kestane ve gürgen ağaçlarının kesildikten sonra fidan dikmeye gerek kalmadan yenilenmesi hangi biyolojik özelliğe dayanır?', 'Kesilen kütüğün kambiyum ve kök boğazındaki uyur tomurcuklarından güçlü kütük sürgünleri vermesine', ['Kesim sırasında yere dökülen talaş parçalarının nemli toprakta köklenerek yeni birey olmasına', 'İğne yapraklı ağaçlar gibi kesildikten sonra köklerinin kozalak üretmeye devam etmesine', 'Yalnızca rüzgârla yirmi kilometre uzaktan gelen yabancı polenlerin kütük yüzeyinde çimlenmesine'], 'Çoğu ibreli ağaç kesildiğinde kütükten sürgün veremezken, meşe, kestane, kayın, gürgen, kızılağaç ve söğüt gibi geniş yapraklılar güçlü kütük ve kök sürgünü (vejetatif yenilenme) yeteneğine sahiptir.'),
  ('Bir göletin kenarındaki toprağa baharda yapraksız bir söğüt dalı çelik olarak saplandığında birkaç hafta içinde hızla kök salarak yeni bir ağaca dönüşmesini kolaylaştıran içsel etken nedir?', 'Söğüt sürgünlerinde doğal oksin (indol bütirik asit) ve salisilik türevi köklendirme öncüllerinin yüksek olması', ['Söğüt kabuğunun topraktaki taşları eriterek hazır kök kanalları açan enzimler salgılaması', 'Dalın içindeki öz boşluğunun suyla dolup hidrolik basınçla alt ucu köke dönüştürmesi', 'Söğüdün kök oluşturmadan doğrudan gövde lentiselleriyle ömür boyu su emebilmesi'], 'Söğüt dalları kabuk altında önceden şekillenmiş kök taslakları (primordiyumlar) ve yüksek düzeyde doğal oksin hormonları barındırdığından en kolay çelikten köklenen odunsu bitkidir.'),
  ('Karadeniz bahçelerinde bolca yetiştirilen, büyük parlak derimsi yaprakları ezildiğinde acı badem kokusu veren ve siyah-koyu mor salkım meyveli her dem yeşil ağaççık hangisidir?', 'Karayemiş / Taflan (Prunus laurocerasus)', ['Kocayemiş (Arbutus unedo)', 'Trabzon hurması (Diospyros kaki)', 'Üvez ağacı (Sorbus aucuparia)'], 'Gülgillerden karayemişin (taflan) etli meyve kısmı yenir ancak çekirdekleri ve taze yaprakları ezildiğinde siyanojenik glikozit (prunasin) parçalanarak acı badem kokulu hidrojen siyanür açığa çıkarır.'),
  ('Kent içindeki kaldırım çatlaklarında, terk edilmiş duvar diplerinde bile hızla büyüyebilen; tüysü bileşik yaprakları ovuşturulduğunda hoş olmayan bir koku yaydığı için \'kokar ağaç\' denilen istilacı tür hangisidir?', 'Aylantus (Ailanthus altissima)', ['Dişbudak yapraklı akçaağaç (Acer negundo)', 'Tespih ağacı (Melia azedarach)', 'Katalpa ağacı (Catalpa bignonioides)'], 'Doğu Asya kökenli Ailanthus altissima hava kirliliğine yüksek toleransı, kök sürgünleri ve \'ailanton\' adlı allelopatik maddesiyle doğal bitki örtüsünü baskılayan güçlü bir istilacı ağaçtır.'),
  ('Yaz ortasında pembe fırça püskülü gibi zarif çiçekler açan ve tüysü bileşik yaprakçıklarını akşam karanlık çöktüğünde karşılıklı olarak birbirine kapatarak uyku hareketi yapan süs ağacı hangisidir?', 'Gülibrişim (Albizia julibrissin)', ['Erguvan (Cercis siliquastrum)', 'Oya ağacı (Lagerstroemia indica)', 'Manolya (Magnolia grandiflora)'], 'İpek ağacı da denilen gülibrişimde yaprakçık tabanındaki pulvinus yastıkçıklarının turgor değişimiyle geceleri yaprakların kapanması (niktinasti), çiy ve ısı kaybını dengeler.'),
  ('Ihlamur ağacının odunu çivi ve mobilya taşıyıcı aksamı için yumuşak kalmasına karşın geleneksel ahşap heykel ve müzik aleti oymacılığında neden çok sevilir?', 'Liflerinin çok homojen olması, budak ve sert damar farkı yaratmadan her yönde tereyağı gibi pürüzsüz oyulabilmesi', ['Doğada doğal olarak parlak mavi ve kırmızı halkalar içerdiği için hiç boya istememesi', 'Yoğun reçine ve silisyum kristalleri içerdiği için ateşle temas ettiğinde hiç yanmaması', 'Su içinde bekletildiğinde demir kadar ağırlaşıp gemi çapası olarak kullanılabilmesi'], 'Ihlamur (Tilia) dağınık traheli, çok ince ve tekdüze dokulu, açık krem renkli hafif bir oduna sahiptir; kesici bıçak altında yarılmadan ince detay vermesi oymacılar için idealdir.'),
  ('Güneydoğu Asya ve Hindistan kökenli \'banyan inciri\' (Ficus benghalensis) tek bir ağaç bireyi olmasına rağmen yüzlerce sütun gövdeli küçük bir koru görünümünü nasıl kazanır?', 'Yatay uzanan ağır dallarından aşağıya sarkıttığı destek hava köklerinin toprağa ulaşınca kalınlaşıp sütun gövdelere dönüşmesiyle', ['Dökülen her yaprağının toprakta çimlenip ana ağacın dallarına aşağıdan yukarıya kaynaşmasıyla', 'Köklerinden fışkıran binlerce otsu sürgünün sarmaşık gibi birbirine dolanarak sertleşmesiyle', 'Çevresindeki diğer ağaç türlerini aşılayarak hepsinin genetik yapısını kendisine çevirmesiyle'], 'Banyan ağacının dallarından inen adventif destek kökleri (prop roots) toprağa girdiğinde sekonder kalınlaşma geçirerek sütunlaşır ve tacın hektarlarca alana yayılmasını sağlar.'),
  ('Fas\'ın güneybatısındaki yarı kurak bölgelere endemik olan, keçilerin meyvelerini yemek için dallarına tırmandığı ve çekirdeklerinden kozmetik sanayisinde çok değerli yağ çıkarılan dikenli ağaç hangisidir?', 'Argan ağacı (Argania spinosa)', ['Karite / Shea ağacı (Vitellaria paradoxa)', 'Makadamya ağacı (Macadamia integrifolia)', 'Brezilya cevizi (Bertholletia excelsa)'], 'UNESCO biyosfer rezervleriyle korunan Argania spinosa Sahra Çölü\'nün ilerleyişini durduran derin köklü bir ağaç olup sert çekirdek içlerinden argan yağı sıkılır.'),
  ('Orta Anadolu ve Doğu Anadolu\'da dere boylarında köylülerce \'selvi kavağı\' olarak dikilen, dalları gövdeye çok dar açıyla dik yükseldiği için sütun görünümü veren kavak formu hangisidir?', 'Ehrami kara kavak / Piramidal kavak (Populus nigra \'Italica\')', ['Fırat kavağı (Populus euphratica)', 'Ak kavak (Populus alba)', 'Melez kavak (Populus euramericana)'], 'Anadolu\'nun kırsal peyzajına damgasını vuran selvi kavağı, kara kavağın dar sütunsu dallanan erkek bir klonudur ve çelikle çoğaltılır.'),
  ('Bir ormancının elindeki dalda tek bir ortak yaprak ekseninin iki yanına dizilmiş 9 adet yaprakçık görmesi ancak sadece ana eksenin gövdeyle birleştiği tabanda koltuk tomurcuğu bulması neyi kanıtlar?', 'İncelenen yapının dokuz ayrı basit yaprak değil, dişbudak veya ceviz gibi tüysü bileşik bir tek yaprak olduğunu', ['Ağacın genetik mutasyon geçirerek yaprak koltuklarında tomurcuk üretme yeteneğini kaybettiğini', 'Sürgünün dokuz yıllık büyüme halkasını tek bir mevsimde tamamlamış olduğunu', 'Bitkinin açık tohumlu bir sikas türü olup spor yaprakları taşıdığını'], 'Basit yaprak ile bileşik yaprağın yaprakçığını (foliyol) ayıran kesin kriter koltuk tomurcuğudur: Tomurcuk yaprakçık diplerinde bulunmaz, yalnızca bileşik yaprağın ana sap tabanında yer alır.'),
  ('Orta Amerika kökenli olan, sütlü öz suyundan (chikle lateksi) modern sentetik bazlar öncesinde doğal çiklet (sakız) üretilen tropikal geniş yapraklı ağaç hangisidir?', 'Sapodilla ağacı (Manilkara zapota)', ['Brezilya kauçuk ağacı (Hevea brasiliensis)', 'Kakao ağacı (Theobroma cacao)', 'Kola ağacı (Cola nitida)'], 'Mayalar ve Aztekler tarafından da çiğnenen \'chicle\', Meksika ve Orta Amerika ormanlarındaki Manilkara zapota ağacının kabuğundan sızan doğal latekstir.'),
  ('And Dağları\'nın doğu yamaçlarında yetişen ve sıtma hastalığının ilk etkili tedavisi olan \'kinin\' alkaloidinin kabuklarından elde edildiği Güney Amerika ağacı hangisidir?', 'Kınakına ağacı (Cinchona officinalis)', ['Koka çalısı (Erythroxylum coca)', 'Mate ağacı (Ilex paraguariensis)', 'Brezilya boya ağacı (Paubrasilia echinata)'], 'Kökboyasıgiller (Rubiaceae) üyesi kınakına ağacının acı kabukları, Plasmodium parazitini durduran kinin maddesi sayesinde yüzyıllarca sıtmaya karşı tek hayat kurtarıcı ilaç olmuştur.'),
  ('Tarçın baharatı mutfaklarda sıklıkla ağaç meyvesi veya kökü sanılsa da gerçekte \'Cinnamomum verum\' ağacının hangi bitkisel dokusunun kurutulup kıvrılmasıyla elde edilir?', 'Genç sürgünlerin dış mantarı kazındıktan sonra soyulan iç kabuk (floem) tabakasının', ['Toprak altındaki odunsu yan köklerin haşlanıp dilimlenmiş öz kısmının', 'Olgunlaşmamış çiçek tomurcuklarının güneşte karartılmış çanak yapraklarının', 'Gövde merkezindeki yaşlı öz odunun talaş haline getirilip preslenmiş dilimlerinin'], 'Sri Lanka kökenli gerçek tarçın (Cinnamomum verum), genç sürgünlerin aromatik sinnamaldehitçe zengin iç kabuğunun (sekonder floem) soyulmasıyla kururken kendi içine rulo olur.'),
  ('Kuzey Amerika ve Avrasya\'da geniş alanlar kaplayan titrek kavak (Populus tremuloides / tremula) koruluklarında yüzlerce ağacın sonbaharda aynı gün sararıp aynı genetik dizilime sahip olması neyi gösterir?', 'Yüzeydeki tüm gövdelerin toprak altındaki tek bir ortak kök sisteminden çıkan kök sürgünleri (klon) olduğunu', ['Koruluktaki ağaçların her birinin rüzgârla aynı gün çimlenmiş ayrı tohum kardeşleri olduğunu', 'Mikoriza mantarlarının ağaçlar arasında DNA aktararak genetik yapıyı eşitlediğini', 'Bölgedeki soğuk havanın tüm türlerde özdeş mutasyonlara yol açtığını'], 'Utah\'taki ünlü \'Pando\' koruluğunda olduğu gibi titrek kavak yatay köklerinden binlerce sürgün (ramet) çıkararak dev klonal organizmalar (genet) oluşturabilir.'),
  ('Akdeniz ve Ege vadilerinde dere kenarlarında mor-mavi salkım çiçekler açan, parmak gibi 5-7 parçalı aromatik yapraklara sahip çalı/ağaççık aşağıdakilerden hangisidir?', 'Hayıt (Vitex agnus-castus)', ['Zakkum (Nerium oleander)', 'Defne (Laurus nobilis)', 'Mersin (Myrtus communis)'], 'Hayıt bitkisi yaz ortasında açan mor çiçek başakları, elsi bileşik yaprakları ve karabibere benzeyen kokulu tohumlarıyla Akdeniz dere yataklarının karakteristik türüdür.'),
  ('Geleneksel Türk bahçelerinde ve köy avlularında ilkbaharda açan keskin hoş kokulu mor veya beyaz salkım çiçekleriyle sevilen \'leylak\' (Syringa vulgaris) hangi ağaç ailesinin üyesidir?', 'Zeytingiller (Oleaceae)', ['Gülgiller (Rosaceae)', 'Kayıngiller (Fagaceae)', 'Söğütgiller (Salicaceae)'], 'Zeytin, dişbudak ve kurtbağrı ile birlikte Oleaceae familyasında yer alan leylak, karşılıklı dizilişli kalp biçimli yapraklara ve dört loblu kaynaşık taç yapraklı çiçeklere sahiptir.'),
  ('Afrika\'nın batı ve orta kesimlerindeki savan kuşağında yetişen, iri yağlı tohumlarından elde edilen katı bitkisel yağ cilt nemlendiricilerinde ve çikolata sanayisinde kullanılan ağaç hangisidir?', 'Karite / Shea ağacı (Vitellaria paradoxa)', ['Kola ağacı (Cola acuminata)', 'Maun ağacı (Khaya senegalensis)', 'Abanoz ağacı (Diospyros crassiflora)'], 'Sahel-savan kuşağındaki yerel ekonominin temel direklerinden olan Vitellaria paradoxa ağacının tohumlarından soğuk sıkım veya kaynatmayla ünlü shea (karite) yağı üretilir.'),
  ('Piyano siyah tuşları, klarnet gövdesi ve keman burgusu yapımında tercih edilen; öz odunu doğal olarak kömür siyahı renginde ve son derece ağır olan tropikal ağaç grubu hangisidir?', 'Abanoz ağacı (Diospyros ebenum)', ['Balsa ağacı (Ochroma pyramidale)', 'Huş ağacı (Betula pendula)', 'Kavak ağacı (Populus alba)'], 'Trabzon hurması (Diospyros kaki) ile aynı cinste yer alan abanoz ağacı, koyu siyah ekstraktif maddelerle dolmuş ultra yoğun ve sert öz odunuyla müzik aleti yapımında ünlüdür.'),
  ('Trabzon hurması (cennet elması - Diospyros kaki) meyvesi tam olgunlaşmadan ısırıldığında ağızda şiddetli bir burukluk ve kuruluk hissi bırakmasının biyokimyasal nedeni nedir?', 'Meyve etindeki çözünür tanenlerin ağızdaki tükürük proteinlerini çöktürmesi', ['Meyve kabuğundaki sitrik asidin diş minesindeki kalsiyumla tepkimeye girmesi', 'Çekirdek çevresindeki kapsaisin maddesinin dildeki ısı reseptörlerini uyarması', 'Ham meyvedeki nişasta tanelerinin tükürükteki suyu anında emerek kristalleşmesi'], 'Ham hurmadaki çözünür polifenolik tanenler tükürük müsin proteinlerine bağlanarak kayganlığı yok eder (astrenjan etki); meyve yumuşayıp olgunlaştıkça tanenler çözünmez forma geçer ve tatlanır.'),
  ('Kış henüz bitmeden (şubat-mart başında) ormandaki diğer tüm ağaçlardan önce çıplak dallarında sapsarı küçük çiçek şemsiyeleri açan ve sonbaharda ekşi-mayhoş kırmızı çekirdekli meyveler veren ağaççık hangisidir?', 'Kızılcık / Ergen (Cornus mas)', ['Kuşburnu (Rosa canina)', 'Böğürtlen (Rubus sanctus)', 'Yaban mersini (Vaccinium myrtillus)'], 'Kızılcık çok erken ilkbaharda açan sarı çiçekleri nedeniyle Anadolu\'da \'aldanmış ağaç\' fıkralarına konu olur; meyveleri ise ancak yaz sonu-sonbaharda olgunlaşır ve çok sert odunu baston yapımında kullanılır.'),
  ('Ekvatoral yağmur ormanlarında 30-40 metrelik kesintisiz tepe çatısının (kanopi) dahi üzerine çıkarak 60-70 metre yüksekliğe tekil şemsiyeler halinde ulaşan en üst ağaç katmanına ne ad verilir?', 'Baskın (emergent) ağaç katmanı', ['Gölgeye uyumlu çalı ve otsu taban katmanı', 'Sarmaşıklarla örülü orta gövde geçiş katmanı', 'Çürükçül mantar ve yaprak döküntüsü katmanı'], 'Tropikal yağmur ormanlarının dikey tabakalaşmasında kapok (Ceiba pentandra) ve Brezilya cevizi gibi dev ağaçlar ana kanopiyi delip geçerek emergent (üst/baskın) katmanı oluşturur.'),
  ('Tropikal yağmur ormanlarının en alt zemininde güneş ışığının yalnızca %1-2 kadarı toprağa ulaşabildiği için bu katmanda yaşayan otsu bitkilerde hangi yaprak uyumu tipiktir?', 'Az ışığı yakalamak için çok geniş ayalı ve alt yüzü morumsu antosiyaninli yapraklar', ['Su kaybını önlemek için taşlaşmış küçük gri pullar ve batıcı dikenli yapraklar', 'Kış soğuğuna dayanmak üzere kalın reçine kanallarıyla sarılı dar iğne yapraklar', 'Tuz fazlasını terlemeyle dışarı atan kristal bezeli etli silindirik yapraklar'], 'Orman tabanındaki bitkiler (örneğin Calathea, Begonia, eğreltiler) dağınık fotonları maksimum tutmak için dev koyu yeşil yaprak ayaları ve ışığı geri yansıtan alt yüz pigmentleri geliştirmiştir.'),
  ('Tropikal yağmur ormanlarında toprağın üzerinde yüzlerce metre yüksekte biyolojik çeşitlilik oldukça zengin iken orman toprağının tarımsal açıdan mineralce fakir (laterit) olmasının nedeni nedir?', 'Yüksek sıcaklık ve yağışla organik maddenin anında ayrışıp köklerce geri emilmesi ve yıkanmanın şiddetli olması', ['Yağmur ormanı ağaçlarının hiç yaprak dökmeyip yüz yıl boyunca aynı yaprakları koruması', 'Toprakta ayrıştırıcı bakteri ve mantarların aşırı nem yüzünden hiç yaşayamaması', 'Kök sistemlerinin toprağa hiç girmeyip tamamen havada asılı biçimde kalması'], 'Tropikal ormanlarda besin döngüsü toprakta değil canlı biyokütlede depolanır; dökülen organik madde hızla mineralize olup yüzeysel köklerce hemen alınır, fazlası aşırı yağışla yıkanır.'),
  ('Ekvatoral ormanlardaki dev ağaçların kök boğazından 3-5 metre yukarıya kadar üçgen kanatlar halinde uzanan \'payanda (levha) köklerin\' birincil işlevi nedir?', 'Sığ ve ıslak laterit toprakta çok boylu ağır gövdeye mekanik devrilme direnci sağlamak', ['Yer altındaki yirmi metre derinlikte bulunan tuzlu artezyen sularını yüzeye çekmek', 'Kış uykusu döneminde nişasta ve yağ depolayarak ilkbahar çiçeklenmesini beslemek', 'Çevredeki çalıların köklerini keserek toprağın oksijen oranını sıfıra indirmek'], 'Yağmur ormanlarında besinler ilk birkaç santimetrede olduğundan kökler derine inmez; dev ağaçlar fırtınada devrilmemek için gövde tabanında geniş payanda kökler (buttress roots) geliştirir.'),
  ('Muson Asyası\'nda yoğun topluluklar kuran ve günde 80-90 santimetreye varan uzama hızıyla dünyanın en hızlı boylanan odunsu bitkisi kabul edilen \'bambu\' botanik sınıflandırmada hangi gruba girer?', 'Buğdaygiller (Poaceae) familyasına ait çok yıllık dev otsu-odunsu tek çenekli bitki', ['Çamgiller familyasına ait kozalaklı ve reçine kanallı açık tohumlu ağaç', 'Kayıngiller familyasına ait sekonder kambiyumlu iki çenekli geniş yapraklı ağaç', 'At kuyrukları şubesine ait tohumsuz ve spor keseli damarlı kriptogam bitki'], 'Bambular ağaç görünümünde olsalar da gerçek bir çim (Poaceae) üyesidir; gövdelerinde kambiyum halkası yoktur, uzamaları her boğum arasındaki interkalar meristemin aynı anda büyümesiyle olur.'),
  ('Güney Yarımküre\'de 55°-60° enlemlerinde Kuzey Yarımküre\'deki gibi geniş bir tayga (boreal orman) kuşağının bulunmamasının temel coğrafi nedeni nedir?', 'Bu enlem aralığında Güney Yarımküre\'nin neredeyse tamamen açık okyanus sularıyla kaplı olması', ['Güney Yarımküre\'de açık tohumlu ağaçların evrimsel olarak hiçbir zaman ortaya çıkmamış olması', 'Antarktika\'dan esen sıcak çöl rüzgârlarının tüm kıyı şeritlerini kumula dönüştürmesi', 'Güney Yarımküre topraklarında demir ve magnezyum minerallerinin hiç bulunmaması'], '50°-65° güney enlemlerinde Güney Amerika\'nın en uç noktası (Ateş Toprakları - Nothofagus ormanları) dışında geniş kıta kütlesi bulunmadığından boreal kuşak oluşamaz.'),
  ('Sonbaharda hem beyaz çan biçimli çiçek salkımlarını hem de bir önceki yıldan olgunlaşan kırmızı pütürlü çileksi meyvelerini aynı anda dallarında taşıyan tipik maki elemanı hangisidir?', 'Kocayemiş (Arbutus unedo)', ['Zakkum (Nerium oleander)', 'Keçiboynuzu (Ceratonia siliqua)', 'Katırtırnağı (Spartium junceum)'], 'Fundagiller (Ericaceae) üyesi kocayemişin meyveleri tam 12 ayda olgunlaştığından sonbahar aylarında yeni açan çiçeklerle kızarmış küremsi meyveler aynı dalda bir arada görülür.'),
  ('Kocayemiş ile aynı cinste yer alan ve Akdeniz maki kuşağında soyulan dış kabuğunun altından çıkan parlak mercan kırmızısı pürüzsüz gövdesiyle hemen tanınan ağaççık hangisidir?', 'Sandal ağacı (Arbutus andrachne)', ['Menengiç (Pistacia terebinthus)', 'Akçakesme (Phillyrea latifolia)', 'Mersin (Myrtus communis)'], 'Anadolu\'da \'kızılcık bacak\' da denilen sandal ağacı (Arbutus andrachne), tam kenarlı yaprakları ve kağıt gibi soyulan kabuğunun altındaki pürüzsüz kızıl gövdesiyle kocayemişten ayrılır.'),
  ('Garig ve maki topluluklarındaki kekik, biberiye, adaçayı ve laden (Cistus) gibi bitkilerin sıcak yaz öğlelerinde yoğun uçucu yağ (eterik yağ) salgılamasının bitki fizyolojisindeki işlevi nedir?', 'Yaprak çevresinde yoğun buhar zarfı oluşturarak terlemeyi düşürmek ve otçul hayvanlara karşı caydırıcı olmak', ['Kış aylarında kar suyunu dondurarak yaprak dokusunun patlamasını engellemek', 'Geceleri ateşböceklerini çekerek karanlıkta rüzgârsız tozlaşma yaptırmak', 'Topraktaki kireçtaşını eriterek bitkiye doğrudan kalsiyum karbonat gazı sağlamak'], 'Aromatik terpenler hem otçullara karşı kimyasal savunma sağlar hem de sıcak havada buharlaşarak yaprak sınır tabakasındaki su buharı difüzyonunu yavaşlatır.'),
  ('Doğu Karadeniz\'in nemli kayın ve ladin ormanlarının altında geçilmez sıklıkta çalı tabakası oluşturan, mor veya sarı çiçeklerinden arıların ürettiği \'deli bal\' (tutma balı) tansiyon düşürücü toksin içeren bitki cinsi hangisidir?', 'Ormangülü / Komar (Rhododendron ponticum ve Rhododendron luteum)', ['Yaban mersini / Likapa (Vaccinium arctostaphylos)', 'Adi fındık (Corylus avellana)', 'Çobanpüskülü (Ilex colchica)'], 'Mor çiçekli Rhododendron ponticum ve sarı çiçekli R. luteum nektarında bulunan \'grayanotoksin\' maddesi deli bala geçer; aşırı tüketildiğinde bradikardi ve baş dönmesine yol açar.'),
  ('Türkiye\'nin bitki coğrafyası (fitocoğrafya) haritası incelendiğinde endemik bitki türü sayısının ve oranının en yüksek olduğu bölge ile bunun temel jeomorfolojik nedeni aşağıdakilerden hangisinde doğru eşleştirilmiştir?', 'Akdeniz Bölgesi (Toros Dağları) — derin vadilerle parçalanmış yüksek karstik dağların coğrafi yalıtım sağlaması', ['Marmara Bölgesi (Ergene Havzası) — düz alüvyal ovaların rüzgârla tüm tohumları birbirine karıştırması', 'Güneydoğu Anadolu Bölgesi — tekdüze bazalt platolarının yıl boyu aynı sıcaklığı koruması', 'Karadeniz Kıyı Şeridi — deniz seviyesindeki kumsalların tuzlu suya tam uyum sağlaması'], 'Toros Dağları\'nın dikey yükselti farkları, kireçtaşı/serpantin anakaya çeşitliliği ve buzul çağlarında sığınak olan izole kanyonları Türkiye endemizminin (~%31) ana merkezini oluşturmuştur.'),
  ('Anadolu\'nun yüksek dağ ve bozkır yamaçlarında rüzgâra ve kuraklığa karşı dikenli sık yarım küreler (\'kirpi yastığı\' formu) oluşturan, toprak erozyonunu önleyici baklagil cinsi hangisidir?', 'Geven (Astragalus)', ['Gelincik (Papaver)', 'Sığırkuyruğu (Verbascum)', 'Üzerlik (Peganum)'], 'Türkiye\'de 400\'den fazla türü (yarısı endemik) bulunan geven (Astragalus) türleri, yaprak eksenlerinin dikene dönüşmesi ve yastık formuyla rüzgâr hızını kesip nemi içinde tutar.'),
  ('İç Anadolu bozkırlarında ilkbahar yağışlarıyla hızla yeşerip çiçek açan, yaz kuraklığı başladığında ise tohum bırakarak veya toprak altı soğan/yumru halinde uyku evresine çekilen kısa ömürlü bitkilere ne ad verilir?', 'Efemer (kuraklıktan kaçan kısa ömürlü) bitkiler', ['Sklerofil (yaz kış sert yapraklı) çalılar', 'Halofit (aşırı tuz biriktiren) otlar', 'Hidrofit (su içinde yüzen) bitkiler'], 'Çiğdem, gelincik ve bazı tek yıllık buğdaygiller gibi efemerler fizyolojik kuraklığa direnmek yerine yaşam döngüsünü nemli 4-6 haftaya sıkıştırarak kuraklıktan kaçar.'),
  ('Bir dağın kuzey ve güney yamaçlarındaki bitki kuşakları karşılaştırıldığında Türkiye gibi Kuzey Yarımküre\'nin orta kuşağındaki dağlarda \'bakı etkisi\' nasıl bir fark yaratır?', 'Güney yamaçta kalıcı kar ve orman üst sınırı daha yüksekten geçerken kuzey yamaçta nemcil türler daha yaygındır', ['Kuzey yamaç güneş ışınlarını dik aldığı için maki bitkileri yalnızca kuzey yamaçta yetişir', 'Her iki yamaçta da sıcaklık ve buharlaşma eşit olduğundan bitki kuşakları simetrik uzanır', 'Güney yamaç yıl boyu gölgede kaldığı için yalnız liken ve kara yosunlarıyla kaplıdır'], 'Kuzey Yarımküre\'de güneye bakan yamaçlar (dönence dışında) güneşi daha büyük açıyla alır; ısınma fazla olduğundan orman ve kar sınırı güneyde yükselir, kuzey yamaç ise serin ve nemli kalır.'),
  ('Bozkır veya savan gibi kurak ve ağaçsız biyomların ortasından geçen nehirlerin hemen iki kıyısı boyunca taban suyuna bağlı olarak kesintisiz yeşil bir şerit halinde uzanan ormanlara ne ad verilir?', 'Galeri ormanı (riparyan koridor)', ['Bulut ormanı (sis kuşağı)', 'Krummholz çalılığı', 'Halofitik tuzcul çayır'], 'Çevredeki yağış ormana yetmese bile akarsu yatağının sağladığı alüvyal taban suyu sayesinde söğüt, kavak, çınar veya tropiklerde nehir boyu ağaçları şerit şeklinde galeri ormanları kurar.'),
  ('Ilıman yaprak döken kayın-meşe ormanlarının tabanında kardelen, çuhaçiçeği, dağ lalesi ve siklamen gibi otsu bitkilerin tam ağaçlar yapraklanmadan önceki mart-nisan aylarında hızla çiçek açıp tohum bağlamasının nedeni nedir?', 'Üst tepe tacı kapanıp orman tabanını koyu gölgeye boğmadan önceki kısa ilkbahar ışık penceresini değerlendirmek', ['Yaz aylarında orman toprağının sıcaklığının eksi on beş dereceye düşmesinden kaçınmak', 'Yalnızca kış uykusundan uyanan boz ayıların kürküne yapışarak tozlaşabilmek', 'Ağaç köklerinin ilkbaharda toprağa saldığı fazla sükrozu parazit olarak emmek'], 'İlkbahar geofitleri (vernal efemeroidler) soğan ve rizomlarındaki yedek besinle kar kalkar kalkmaz yapraklanır; kayın ve meşe tacı mayısta ışığı kesmeden önce fotosentez ve üremelerini tamamlar.'),
  ('Ormanda fırtınayla devrilen yaşlı bir ağacın açtığı güneşli boşluğa ilk yerleşen huş, titrek kavak veya kızılçam gibi \'öncü (pionir) ağaç türlerinin\' ortak ekolojik karakteri nedir?', 'Bol ve uzaklara yayılan küçük tohumlar üretmeleri, tam güneş ışığı istemeleri ve gençlikte çok hızlı büyümeleri', ['Koyu gölge altında yüz yıl bekleyip yalnızca yılda bir milimetre boy uzatmaları', 'Çok ağır ve kanatsız tekil tohumlar üretip hiç rüzgâr görmeyen kuytuları seçmeleri', 'Toprakta yalnız yüz yıllık kalın humus birikmeden çimlenme yeteneği göstermemeleri'], 'Öncü türler yüksek ışık talebi (heliotit), hızlı büyüme ve rüzgârla kolay taşınan bol tohumla açık alanları hızla kaplar; zamanla kendi gölgelerinde göknar/kayın gibi gölgeye dayanıklı klimaks türler yerleşir.'),
  ('Kanada\'nın Pasifik kıyılarında (Britanya Kolumbiyası), Güney Şili\'de ve Karadeniz\'in doğu yamaçlarında denizden gelen nemli rüzgârların dağlara çarpmasıyla yüksek yağış alan serin kuşağın orman tipi hangisidir?', 'Ilıman kuşak yağmur ormanı', ['Subtropikal dikenli çöl ormanı', 'Ekvatoral alçak ova selvası', 'Karasal soğuk bozkır koruluğu'], 'Yağmur ormanları yalnızca ekvatorda bulunmaz; yıllık yağışın 1500-3000 mm\'yi aştığı ılıman okyanusal kıyılarda yosun ve eğrelti kaplı dev ağaçlı \'ılıman yağmur ormanları\' gelişir.'),
  ('Tropikal dağların 1500-3000 metre yükseltileri arasında bulut tabanının sürekli ağaç dallarına temas ettiği, gövdelerin sünger gibi briyofit (kara yosunu) ve epifitlerle sarıldığı ekosistem nasıl adlandırılır?', 'Bulut ormanı', ['Galeri ormanı', 'Muson tik ormanı', 'Kuru savan korusu'], 'Montan bulut ormanlarında (cloud forest) ağaçlar yağışın yanı sıra yaprak ve yosun örtüleriyle bulut damlacıklarını doğrudan yakalayıp (\'yatay yağış\') havza akarsularını besler.'),
  ('Ağaç sınırındaki rüzgârlı dağ sırtlarında ibreli ağaçların rüzgârın estiği yönde hiç dal geliştiremeyip yalnızca rüzgâr altı (kuytu) tarafa doğru tek yönlü dallanarak \'bayrak ağaç\' şeklini almasının nedeni nedir?', 'Rüzgârın taşıdığı buz kristallerinin aşındırması ve kış kuraklığının rüzgâra bakan tomurcukları sürekli öldürmesi', ['Ağacın köklerinin yalnızca rüzgârın estiği yöndeki toprağa tutunup diğer tarafı bırakması', 'Güneşin yıl boyunca yalnızca rüzgâr altı taraftan doğup aynı yönden batması', 'Böceklerin rüzgârlı taraftaki kabuğu yiyerek tüm iletim demetlerini soyması'], 'Şiddetli hakim rüzgâr ve savrulan kar-buz tanecikleri rüzgâr üstü (luv) taraftaki taze sürgünleri kurutup kırar; yalnız gövdenin koruduğu rüzgâr altı (lee) yöndeki dallar büyüyerek bayrak formu verir.'),
  ('Akdeniz maki topluluğunda baharda sapsarı kelebeksi çiçeklerle donanan, yaz kuraklığında su kaybını en aza indirmek için küçük yapraklarını döküp yeşil silindirik sürgünleriyle fotosentez yapan çalı hangisidir?', 'Katırtırnağı (Spartium junceum)', ['Kocayemiş (Arbutus unedo)', 'Akçakesme (Phillyrea latifolia)', 'Defne (Laurus nobilis)'], 'Baklagillerden katırtırnağı sıcak yaz aylarında yapraklarını erken dökerek terleme yüzeyini daraltır ve klorofilli yeşil gövde dallarıyla (asimilasyon sürgünleri) fotosentezi sürdürür.'),
  ('Orta Asya, Kuzey Amerika (Preri) ve Arjantin (Pampa) gibi kıta içlerindeki ılıman çayırlarda yağışın çöllere göre daha yüksek (300-600 mm) olmasına rağmen geniş ormanlar oluşamamasının başlıca etkenleri nelerdir?', 'Yaz sonu kuraklığı, sert kış donları, periyodik çayır yangınları ve büyük otçul sürülerinin fide baskısı', ['Toprağın tamamen organik maddeden yoksun beyaz kuvars kumundan ibaret olması', 'Bölgede yıl boyunca hiç güneş çıkmaması ve sürekli yoğun sis tabakası bulunması', 'Çayır otlarının köklerinden saldığı sülfürik asidin tüm ağaç tohumlarını eritmesi'], 'Ilıman çayırlar (step, preri, pampa) en verimli kara topraklara (çernozyom) sahiptir; ancak mevsimsel kuraklık, doğal yangınlar ve bizon/yaban atı gibi otçullar odunsu fideleri baskılar, dipten büyüyen buğdaygiller üstün gelir.'),
  ('Toros Dağları\'nın Akdeniz\'e bakan güney yamaçlarında kıyıdan 2200 metre yükseltiye doğru tırmanan bir doğa gözlemcisinin sırasıyla geçeceği karakteristik bitki kuşakları hangisidir?', 'Maki ve kızılçam kuşağı — Karaçam, Toros sediri ve göknar kuşağı — Alpin taşlık ve yastık bitkileri', ['Psödomaki ve kayın kuşağı — Doğu ladini ve huş kuşağı — Tundra bataklık yosunları', 'Antropojen bozkır — Sığla ve dişbudak longozu — Mangrov kıyı ormanları', 'Garig çalılığı — Tropikal muson tik ormanı — Her dem yeşil geniş yapraklı selva'], 'Akdeniz\'de 0-800 m maki, 0-1200 m kızılçam, 1200-2000 m karaçam, Toros sediri, Toros göknarı ve boylu ardıçlardan oluşan yüksek dağ ibreli ormanı, 2000-2200 m üzerinde ise dikenli yastık ve alpin çayır kuşağı uzanır.'),
  ('Muğla\'nın Datça ve Teke yarımadalarındaki sarp kayalık koylarda doğal yayılış gösteren \'Datça hurması\' (Phoenix theophrasti) Türkiye florası açısından hangi özelliğiyle dikkat çeker?', 'Avrupa ve Anadolu anakarasında doğal olarak yetişen iki yerli palmiye türünden biri olmasıyla', ['Kış aylarında tüm yapraklarını döküp gövdesinde odunsu kozalaklar oluşturmasıyla', 'Tatlı su göllerinin dibinde tamamen suya gömülü yaşayan tek otsu bitki olmasıyla', 'Yalnızca iki bin beş yüz metre üzerindeki karlı zirvelerde yayılış göstermesiyle'], 'Girit ve Güneybatı Anadolu kıyı kanyonlarına özgü Datça hurması (Phoenix theophrasti), Doğu Akdeniz\'in nadir doğal ve relikt palmiye türüdür.'),
  ('Orman yangınlarından sonra Akdeniz maki ve garig alanlarında ilk bir-iki yıl içinde pembe veya beyaz buruşuk taç yapraklı \'laden\' (Cistus creticus / Cistus salviifolius) çalılarının hızla alanı kaplamasının nedeni nedir?', 'Toprakta yıllarca uyuyan sert kabuklu tohumlarının yangın ısısı şokuyla çatlayıp su geçirgenliği kazanması', ['Laden çalılarının köklerinin yüz metre derinden yanmaz su fışkırtarak gövdeyi koruması', 'Yangın külünün havadaki polenleri döllenme olmadan doğrudan tohuma dönüştürmesi', 'Kuşların yangın devam ederken yanan dalların arasına taze laden çelikleri dikmesi'], 'Laden (Cistus) türleri tipik pirofit öncülerdir; fiziksel dormansiye sahip taş gibi sert tohum kabukları 80-120 °C\'lik kısa yangın ısısıyla çatlar ve ilk sonbahar yağmurunda topluca çimlenir.'),
  ('Avrupa\'nın Atlantik kıyılarında ve Kuzeybatı Anadolu\'nun asidik, yıkanmış fakir topraklarında morumsu pembe küçük çiçekleriyle geniş çalılıklar (\'heathland\') oluşturan bitki cinsi hangisidir?', 'Süpürge çalısı / Funda (Calluna vulgaris ve Erica arborea)', ['Keçiboynuzu (Ceratonia siliqua)', 'Üzerlik otu (Peganum harmala)', 'Yavşan otu (Artemisia santonicum)'], 'Funda (Erica arborea - ağaç fundası, lületaşı pipo kökü olarak da kullanılır) ve Calluna türleri kireçsiz, asidik topraklarda erikoid mikorizaları sayesinde beslenerek sık fundalıklar kurar.'),
  ('Orman ekolojisinde geniş ve bütünlüklü bir ormanın yollar, maden sahaları veya tarlalarla küçük adacıklara bölünmesi sonucunda orman iç kısmından farklı olarak rüzgâr, kuraklık ve istilacı türlere açık hale gelen sınır kuşağı etkisine ne denir?', 'Kenar etkisi (edge effect)', ['Sera etkisi (greenhouse effect)', 'Fön rüzgârı etkisi', 'Fotoperiyodik etki'], 'Habitat parçalanmasıyla orman parçalarının kenar/alan oranı büyür; kenar etkisi orman içi nemini düşürür, rüzgâr devriklerini artırır ve gölge-nem seven iç orman türlerini tehdit eder.'),
  ('Anadolu bozkırlarında hayvanların yemediği acı alkaloitli yapraklara sahip \'sığırkuyruğu\' (Verbascum) ve \'üzerlik\' (Peganum harmala) bitkilerinin köy meralarında aşırı çoğalması bir ekolog için neyin göstergesidir?', 'Merada aşırı ve kontrolsüz otlatma nedeniyle lezzetli yem otlarının tükenip meranın bozulduğunun', ['Toprağın organik madde ve azot bakımından en verimli çayır evresine ulaştığının', 'Bölgede yıllık yağış miktarının iki katına çıkarak ormanlaşmanın başladığının', 'Mera toprağının tamamen tatlı su bataklığına dönüşmek üzere olduğunun'], 'Koyun ve sığırlar besleyici buğdaygil ve baklagilleri seçerek tükettiğinde, hayvanların ağzına almadığı zehirli/acı veya dikenli bitkiler (üzerlik, sütleğen, sığırkuyruğu, boğa dikeni) rekabetsiz kalarak baskınlaşır.'),
  ('Tropikal yağmur ormanlarında tabanda yaşayan dev yapraklı \'deve tabanı\' (Monstera deliciosa) bitkisinin yaprak ayalarında doğal olarak pencereler ve derin yarıklar (fenestrasyon) bulunmasının ekolojik işlevi nedir?', 'Üstten düşen şiddetli yağmur sağanaklarının yaprağı yırtmasını önlemek ve alt yapraklara ışık sızdırmak', ['Yaprak ağırlığını artırarak bitkinin konak ağacı aşağı doğru çekip devirmesini sağlamak', 'Deliklerin içine küçük kuşları hapsederek böcekçil sindirim enzimleriyle eritmek', 'Kurak çöl rüzgârlarında yaprağın tuz kristallerini delik kenarlarında biriktirmek'], 'Monstera yapraklarındaki programlanmış hücre ölümüyle açılan delikler hem benekli güneş ışınlarını daha geniş bir alanda yakalamaya hem de fırtına ve sağanakta rüzgâr/su basıncını geçirmeye yarar.'),
  ('Ilıman ormanlarda ağaçların hem kendi türdaşlarıyla hem de komşu türlerle toprak altındaki ortak mikoriza mantarı hifleri üzerinden karbon, su ve savunma sinyalleri alışverişi yapmasına ekologlar hangi metaforik adı vermiştir?', 'Orman çapında ağ', ['Kök boğazı allelopati bariyeri', 'Ksilem kavitasyon zinciri', 'Atmosferik feromon köprüsü'], 'Suzanne Simard ve diğer araştırmacıların izotop deneyleriyle gösterdiği ortak mikorizal ağlar sayesinde yaşlı \'anaç ağaçlar\' gölgedeki fidelere karbon bileşikleri ve stres uyarıları aktarabilmektedir.'),
  ('Afrika\'daki Akasya savanlarında zürafaların otlamasına karşı ağaçların yalnız uzun dikenler üretmekle kalmayıp içi boş şişkin diken diplerinde (domatia) şekerli nektar sunarak agresif \'Crematogaster\' karıncalarını barındırması hangi ilişki türüdür?', 'Karşılıklı yarar sağlayan savunma mutualizmi', ['Ağacın iletim dokusunu tüketen tek taraflı parazitizm', 'Karıncalara zarar verirken ağacı etkilemeyen amensalizm', 'Aynı mineral kaynağı için yürütülen türler arası rekabet'], 'Islık çalan akasya (Vachellia drepanolobium) karıncalara yuva ve ekstrafloral nektar sağlar; karıncalar da zürafa veya fil dala dokunduğu anda yüzlercesi birden hayvanın burnunu ısırarak ağacı korur.'),
  ('Ilıman kuşakta yetişen bir ağacın tek bir yıllık yaş halkası içinde ilkbaharda üretilen \'erken odun\' ile yaz sonunda üretilen \'geç odun\' hücreleri neden farklı görünür?', 'İlkbahar odunu geniş lümenli ve ince çeperli, yaz odunu dar lümenli ve kalın çeperlidir', ['İlkbahar odunu tamamen koyu renkli reçine kanallarından, yaz odunu ise renksiz mantar hücrelerinden oluşur', 'Yaz odunu yaprak dökümünü hızlandırmak için çok geniş borular üretirken ilkbahar odunu dar lifler üretir', 'İlkbahar odununda hücre duvarları yalnız selüloz içerirken yaz odununda yalnızca süberin birikimi gerçekleşir'], 'İlkbaharda yeni açan yaprakların yüksek su ihtiyacı için geniş çaplı iletim elemanları yapılır; yaz sonunda büyüme yavaşladığında mekanik dayanımı artıran kalın duvarlı koyu yaz odunu üretilir.'),
  ('Ağaç gövdesinin enine kesitinde merkezden kabuğa doğru tekerlek parmakları gibi ışınsal uzanan canlı parankima şeritlerinin (öz ışınları) temel fizyolojik görevi nedir?', 'Su ve besin maddelerini odun ile kabuk arasında yatay yönde taşımak ve kışlık yedek besin depolamak', ['Köklerden alınan mineralleri yapraklara dikey olarak saniyede birkaç metre hızla pompalamak', 'Gövde kabuğu yaralandığında atmosfere oksijen vererek mantar sporlarını kurutmak', 'Yalnızca ilkbahar aylarında bölünerek ağacın boyca uzamasını doğrudan gerçekleştirmek'], 'Öz ışınları (ksilem ve floem ışınları), gövdedeki radyal (yatay) madde iletimini sağlar, nişasta/yağ depolar ve öz odun oluşurken koruyucu fenolik bileşikleri merkeze aktarır.'),
  ('Bir ağacın gövde çevresi boyunca dış ve iç kabuğun (sekonder floem dahil) tam bir halka şeklinde soyulup çıkarılması (\'kuşaklama / halkalama\') ağacın ölümüne neden olurken ilk olarak hangi organ zarar görür?', 'Yapraklardan organik besin alamayan kök sistemi açlıktan ölür', ['Köklerden gelen su anında kesildiği için tepe yaprakları bir saat içinde kurur', 'Gövde merkezindeki öz odun hava ile temas ettiği anda çürüyerek ikiye kırılır', 'Çiçek tomurcukları aşırı sükroz birikimi yüzünden patlayarak tüm dalları zehirler'], 'Halkalama işleminde odun (ksilem) sağlam kaldığı için yapraklara su gitmeye bir süre devam eder; ancak floem kesildiği için fotosentez ürünleri köklere inemez ve kökler tükenince ağaç tamamen kurur.'),
  ('Mutfaklarda çubuk halinde kullandığımız gerçek Seylan tarçını (Cinnamomum verum), ağacın hangi anatomik bölümünün soyulup kurutulurken kendi içine kıvrılmasıyla elde edilir?', 'Dış mantarı kazınmış sürgünlerin aromatik iç kabuk (floem) tabakasının', ['Yaşlı gövdenin tam merkezinden kesilip ince yongalara ayrılan koyu renkli öz odun dokusunun', 'Toprak altındaki yan köklerin uç kısımlarında gelişen nişastaca zengin yumru kılıflarının', 'Tozlaşma sonrasında dökülen çiçek çanak yapraklarının preslenerek rulo haline getirilmesinin'], 'Tarçın çubukları, 2-3 yaşındaki sürgünlerin dış mantar tabakası sıyrıldıktan sonra alttaki sinnamaldehitçe zengin ince floem (iç kabuk) şeritlerinin soyulup kurutulmasıyla üretilir.'),
  ('Tarih boyunca sıtma hastalığının tek etkili tedavisi olarak kullanılan \'kinin\' alkaloidi, Güney Amerika And Dağları\'nın bulut ormanlarına özgü hangi ağacın kabuğundan elde edilmiştir?', 'Kınakına ağacı (Cinchona officinalis)', ['Brezilya kauçuk ağacı (Hevea brasiliensis)', 'Güney Amerika maun ağacı (Swietenia macrophylla)', 'Şili sabun kabuğu ağacı (Quillaja saponaria)'], 'Kökboyasıgiller (Rubiaceae) üyesi Cinchona türlerinin acı kabuğu kinin içerir ve Plasmodium parazitine karşı yüzyıllarca sıtma ilacı olarak kullanılmıştır.'),
  ('Doğal kauçuk üretiminde temel kaynak olan Brezilya kauçuk ağacının (Hevea brasiliensis) gövdesine eğimli oluklar açılırken bıçağın vasküler kambiyuma değmeyecek derinlikte tutulmasının nedeni nedir?', 'İç kabuktaki lateks borularını açarken kambiyumu koruyup kabuğu yeniletmek', ['Lateksin yalnızca en dıştaki ölü mantar hücrelerinden akması ve iç kabukta hiç sıvı bulunmaması', 'Kambiyuma dokunulduğunda lateksin anında kristalleşerek tatlı akçaağaç şurubuna dönüşmesi', 'Odun boruları kesildiğinde ağacın köklerinden toprağa zehirli kauçuk asidi boşaltması'], 'Kauçuk lateksi sekonder floem içindeki laktifer (süt) borularından gelir; kambiyum korunursa ağaç kesilen kabuğu onarır ve onlarca yıl boyunca lateks vermeyi sürdürür.'),
  ('Budanan bir dalın kesim yüzeyi veya gövdedeki bir sıyrık çevresinde kambiyum ve canlı parankima hücrelerinin hızla bölünerek yarayı kenarlardan merkeze doğru simit gibi kapatan dokuya ne ad verilir?', 'Yara kallusu dokusu', ['Apikal sürgün meristemi kubbesi', 'Primer kök kaliptra koruma yüksüğü', 'Sklerankimatik taş hücresi kümesi'], 'Yara çevresinde önce farklılaşmamış parankimatik kallus dokusu gelişir, ardından içinde yeni vasküler kambiyum ve periderm farklılaşarak \'yara odunu\' yarayı dış ortamdan mühürler.'),
  ('Ormancılıkta canlı bir ağacı kesip devirmeden yaşını ve son yıllardaki büyüme hızını belirlemek amacıyla gövdeden kalem inceliğinde silindirik bir odun örneği çıkaran el aletine ne ad verilir?', 'Pressler artım burgusu', ['Göğüs yüksekliği çap ölçer kompas aleti', 'Ağaç boyu ölçen optik klinometre dürbünü', 'Yaprak alanı indeksli dijital ışık sensörü'], 'İçi boş çelik boru şeklindeki artım burgusu göğüs yüksekliğinden (1,30 m) gövde merkezine kadar vidalanır ve çıkarılan ince odun kalemi üzerindeki yaş halkaları sayılır.'),
  ('Dendrokronolojide (ağaç halkaları biliminde) canlı ağaçlar ile tarihi binalardaki ahşap kirişlerin halka genişliği dizilerini üst üste çakıştırarak binlerce yıl geriye giden kesin takvimler kurma yöntemine ne denir?', 'Çapraz tarihleme yöntemi', ['Radyokarbon yarı ömür bozunma analizi', 'Fosil polen stratigrafisi korelasyonu', 'Termolüminesans kuvars kristal ölçümü'], '20. yüzyıl başında A. E. Douglass tarafından geliştirilen çapraz tarihleme, aynı iklim bölgesindeki ağaçların kurak ve yağışlı yıllarda oluşturduğu barkod benzeri dar-geniş halka örüntülerini eşleştirir.'),
  ('Ceviz, meşe veya sekoya ağaçlarının gövdesinde bazen uyur tomurcukların kontrolsüzce çoğalmasıyla oluşan yumrulu şişkinlikler (\'ur / burl\') lüks mobilya kaplamacılığında neden çok yüksek değer görür?', 'Kıvrımlı ve kuşgözü lif yapısının eşsiz desenler sunup kolay yarılmaması', ['Normal gövde odununa göre on kat daha hafif olması ve suda batmadan sünger gibi esneyebilmesi', 'İçinde hiç lignin bulunmadığı için ısıtılmadan soğuk halde kağıt gibi katlanıp şekil alabilmesi', 'Kesildikten sonra bile yıllarca parlak fosforlu renk değiştirerek karanlıkta ışık yansıtması'], 'Böcek, bakteri, mantar veya yaralanma uyarısıyla oluşan gövde urlarında (örneğin ceviz kökü/uru kaplama) yüzlerce uyur tomurcuk izi ve kıvrımlı lif yapısı otomobil konsolları ve oymacılıkta aranan desenler yaratır.'),
  ('Meşe, kestane, gürgen ve kızılağaç gibi geniş yapraklı ağaçların dipten kesildikten sonra kütük üzerindeki uyur ve adventif tomurcuklardan çok sayıda güçlü sürgün vererek yenilenmesine dayanan geleneksel orman işletme biçimi hangisidir?', 'Baltalık orman işletmeciliği', ['Tohumdan doğal saf koru gençleştirmesi', 'Aşılı klonal tohum bahçesi ıslah yöntemi', 'Tarımsal rüzgâr perdesi koruyucu şerit dikimi'], 'Geniş yapraklıların kütük sürgünü verme yeteneğinden yararlanılarak 20-40 yıllık idare süreleriyle yakacak veya sırık odunu üretilen ormanlara baltalık denir; çamların çoğunda bu yetenek yoktur.'),
  ('Kent caddelerindeki çınar, ıhlamur ve söğüt ağaçlarının veya kırsaldaki yemlik ağaçların her birkaç yılda bir insan ve hayvan boyunun üzerindeki sabit bir yükseklikten (2-3 m) budanarak topuz başlı sürgün tacı oluşturulmasına ne ad verilir?', 'Tepelik budama işletmesi', ['Toprak hizasından tıraşlama kesim yöntemi', 'Kök boğazı bilezikleme kurutma uygulaması', 'Piramidal lider sürgün şekil terbiyesi'], 'Avrupa ve Anadolu\'da yüzyıllardır uygulanan tepelik işletmesinde (pollarding) otlayan hayvanların yetişemeyeceği yükseklikte kesim yapılır; böylece hem yapraklı yem/yakacak dal alınır hem de ağacın ömrü uzar.'),
  ('Kuzey Amerika yerlilerinin nehirlerde kullandığı hafif ama son derece su geçirmez kanoların dış kaplamasını tek parça halinde soyarak ürettikleri ağaç türü hangisidir?', 'Amerikan kağıt huşu', ['Kanada doğu şeker akçaağacı türü', 'Kuzey Amerika ova karaağacı türü', 'Büyük Göller doğu beyaz çamı türü'], 'Kağıt huşunun (Betula papyrifera) kabuğu yüksek oranda hidrofobik betulin ve süberin yağı içerdiği için çürümez, suyu kesinlikle geçirmez ve yatay lentisel yapısı sayesinde geniş tabakalar halinde soyulabilir.'),
  ('Kışın yaprağını dökmüş bir ceviz veya at kestanesi sürgünü incelendiğinde dal üzerinde at nalı veya kalkan biçiminde görülen iz ile onun içindeki küçük noktacıklar sırasıyla neyi temsil eder?', 'Yaprak sapı izini ve kapanmış iletim demeti uçlarını', ['Böcek yumurtlama kesesini ve nektar salgılayan gözenekleri', 'Gelecek yıl açacak çiçek tomurcuğunu ve polen deliklerini', 'Mantar kambiyumu çatlağını ve reçine sızıntı kanallarını'], 'Kış dendrolojisinde tür teşhisi yapılırken sürgün üzerindeki \'yaprak izi\' (leaf scar) şekli ve içindeki mühürlenmiş ksilem-floem \'iletim demeti izlerinin\' sayısı en güvenilir anahtarlardandır.'),
  ('Bal arılarının kovandaki çatlakları kapatmak ve mikroplara karşı dezenfeksiyon sağlamak amacıyla ürettikleri \'propolis\' maddesinin ana bitkisel hammaddesi ağaçların hangi kısmından toplanır?', 'Kavak, huş ve çam gibi ağaçların reçineli kış tomurcuklarından', ['İlkbaharda açan meyve çiçeklerinin çanak yaprak diplerindeki sulu şekerli nektar damlalarından', 'Rüzgârla tozlaşan fındık ve kızılağaç kediciklerinin ürettiği proteinli sarı polen tozlarından', 'Yaşlı meşe ağaçlarının toprak altındaki kök tüylerinin salgıladığı müsilaj tabakasından'], 'Birçok ağaç kış tomurcuklarını soğuk, su kaybı ve mantarlardan korumak için flavonoid ve fenolik reçinelerle kaplar; arılar özellikle kavak (Populus) tomurcuklarından bu reçineyi kazıyıp propolise dönüştürür.'),
  ('Hurma ve Hindistan cevizi gibi palmiye ağaçları 25-30 metre boya ulaşmalarına rağmen gövde yapıları gerçek odunlu ağaçlardan (çam, meşe) hangi yönüyle tamamen ayrılır?', 'Kambiyum ve yaş halkası yoktur; dağınık iletim demetleri ve liflerden oluşur', ['Gövdelerinin merkezi yalnızca koyu renkli reçineli öz odundan, çevresi ise yumuşak mantar kabuktan oluşur', 'Her mevsim yeni bir kambiyum halkası ürettikleri için tabanları her yıl iki kat genişleyerek konikleşir', 'Su iletimini yalnızca dış kabuk yüzeyindeki ölü tüylerle yapıp gövde içinde hiç trake bulundurmazlar'], 'Palmiyeler tek çenekli (monokotil) bitkilerdir; sekonder kalınlaşma kambiyumu bulunmadığı için gövdeleri tepe meristemi genişledikten sonra boya kalkar ve yaşlandıkça enine halka yapmaz.'),
  ('Sarı pigmentlerin aksine, sonbaharda akçaağaç, sığla ve sumak yapraklarında görülen parlak kızıl-mor renkleri veren \'antosiyanin\' pigmentlerinin oluşumu için hangi hava koşulu en elverişlidir?', 'Gündüzlerin açık güneşli, gecelerin donma üstünde serin geçmesi', ['Haftalarca süren kapalı, ılık ve sürekli sağanak yağışlı bulutlu sonbahar günleri', 'Ağustos ortasında yaşanan kırk derecelik kavurucu kuraklık ve sıcak gece rüzgârları', 'Eylül başında aniden bastıran eksi on derecelik sert donun yaprakları bir gecede dondurması'], 'Antosiyaninler yaprakta önceden bulunmaz; sonbaharda floem taşınması yavaşladığında güneşli gündüzlerde üretilen şekerler serin gecelerde yaprakta kalarak kofulda kırmızı antosiyanin sentezini artırır.'),
  ('Sokak aydınlatma direklerinin hemen altında büyüyen çınar ve akçaağaç bireylerinde lambaya yakın dalların kasım-aralık aylarında bile yeşil kalıp yaprak dökmemesinin nedeni nedir?', 'Yapay gece ışığının fitokromları yanıltarak kış uykusunu geciktirmesi', ['Sokak lambasından yayılan ısının ağacın kök çevresindeki toprağı yaz sıcaklığında tutarak su emilimini hızlandırması', 'Elektrik kablolarındaki manyetik alanın klorofil moleküllerini yaprak hücre duvarlarına kalıcı olarak bağlaması', 'Gece lambası çevresinde toplanan böceklerin solunumla saldığı karbondioksidin fotosentezi gece boyu sürdürmesi'], 'Özellikle kırmızı dalga boyu içeren sokak lambaları gece karanlığını böldüğü için o daldaki fotoperiyodik kış uykusu (dormansi) ve absisyon gecikir; ilk sert donda bu dallar zarar görür.'),
  ('Kuzey yarımkürede şubat-mart aylarında henüz yapraklar açmadan önce huş (Betula) veya ceviz (Juglans) ağacının dalı budandığında kesik yüzeyden günlerce damla damla sıvı akmasının (\'ağlama\') temel itici gücü nedir?', 'Köklerin osmotik su çekmesiyle oluşan pozitif kök basıncı', ['Geniş yaprak ayalarından gerçekleşen hızlı terlemenin yarattığı negatif kohezyon çekimi', 'Atmosfer basıncının ilkbahar fırtınalarında gövde kabuğunu dışarıdan sıkıştırması', 'Floem kalburlu borularının kış boyunca biriktirdiği yağmur suyunu yukarı fışkırtması'], 'Yaprak yokken terleme çekimi çalışmaz; ilkbaharda ısınan toprakta köklerin ksileme iyon ve organik asit/şeker pompalaması pozitif kök basıncı yaratarak öz suyunu kesik daldan dışarı iter.'),
  ('Yüzeysel örtü yangınlarının sık geçtiği karaçam veya sekoya ormanlarında kesilen yaşlı bir kütüğün yaş halkalarında \'kedi yüzü\' (catface) şeklinde kama biçimli yara izleri bulunması araştırmacıya hangi bilgiyi verir?', 'Ağacın geçmişte hangi yıllarda yangın atlattığının tarihsel kaydını', ['Ağacın tohumdan çimlendiği ilk yılda toprağın pH değerinin ve kireç oranının tam sayısal ölçüsünü', 'Ormanda yaşayan otçul memeli türlerinin son beş yüz yıldaki genetik mutasyon hızlarını', 'Bölgede gelecek on yıl içinde meydana gelecek fırtına ve kuraklıkların önceden tahminini'], 'Örtü yangını gövdenin rüzgâr altı kuytu yüzündeki kambiyumu kısmen öldürdüğünde ağaç yarayı kallusla sarmaya çalışır; her yeni yangın halkalarda tarihlenebilir bir \'yangın yara izi\' (fire scar) bırakır.'),
  ('Kış ortasında güneşli ama dondurucu soğuk günlerde genç meyve ağaçlarının ve ince kabuklu süs ağaçlarının gövdelerinin güneybatıya bakan yüzünde dikey \'güneş-don çatlakları\' oluşmasını önlemek için gövdelerin kireçle beyaza boyanmasının nedeni nedir?', 'Gündüz kabuk ısınmasını önleyip akşam ani don çatlamasını engellemek', ['Kirecin içindeki kalsiyum iyonlarının doğrudan dış mantar tabakasından geçerek kış ortasında çiçek açtırmasını sağlamak', 'Gövdeyi beyaza boyayarak kar yağışında tavşan ve tarla farelerinin ağacı karla karıştırıp görmemesini sağlamak', 'Topraktan yükselen nemin gövde yüzeyinde tutunmasını sağlayarak mantar sporlarının kış boyu çoğalmasını desteklemek'], 'Koyu renkli gövde kış öğleden sonrasında güneşle 15-20 °C ısındığında kabuk altı hücreler soğuk dayanımını kaybeder; güneş batar batmaz sıcaklık eksiye düşünce hücre içi buzlanma kabuğu boydan boya yarar.'),
  ('Karahindiba (Taraxacum) ve tekesakalı (Tragopogon) gibi Papatyagiller familyası bitkilerinde tohumlu meyvenin (aken) ucunda açılan ve en hafif esintide kilometrelerce süzülmesini sağlayan paraşüt benzeri tüy demeti çiçekteki hangi yapının başkalaşımıdır?', 'Çanak yaprakların pappus tüy demetine dönüşmesinin', ['Erkek organ başçıklarının kuruyarak pamuksu polen kanatları oluşturmasının', 'Taç yaprakların döllenme sonrasında parçalanıp ipeksi ipliklere ayrılmasının', 'Kök emici tüylerinin rüzgârla koparak meyve kabuğuna sonradan yapışmasının'], 'Asteraceae (Papatyagiller) çiçeklerinde çanak yapraklar (sepal) pappus adı verilen tüysü paraşütlere dönüşür; paraşütün üzerinde oluşan kararlı hava girdabı düşüş hızını düşürerek anemokoriyi (rüzgârla yayılmayı) sağlar.'),
  ('Akçaağaç (Acer), dişbudak (Fraxinus) ve karaağaç (Ulmus) ağaçlarının olgunlaşan kuru ve açılmayan tek tohumlu meyvelerinin zarsı bir kanat taşımasına botanikte hangi özel meyve adı verilir?', 'Samara tipi kanatlı meyve', ['İki dikiş hattından yarılan kuru bakla meyve', 'Sert çekirdekli sulu etli drupa tipi meyve', 'Çok tohumlu yumuşak kabuklu üzümsü meyve'], 'Samara tipi kuru meyvelerde perikarp (meyve duvarı) yassı ve hafif bir kanat şeklinde uzamıştır; akçaağaçta ikili (şizokarpik çift samara), dişbudakta dil biçimli tekli, karaağaçta ise tohumu çepeçevre saran daire biçimlidir.'),
  ('Gelincik (Papaver) ve çörekotu gibi bitkilerde dik duran kuru kapsül meyvenin tepesinde küçük gözenekler açılması ve kapsülün sert rüzgârda veya hayvan çarptığında yay gibi sallanarak tohumları çevreye serpmesi mekanizmasına ne ad verilir?', 'Tuzluk tipi serpme mekanizması', ['Hidrostatik sıvı basıncıyla fışkırtma mekanizması', 'Karınca besin cisimciğiyle yer altına taşıma sistemi', 'Hava dolu dokularla su üstünde yüzdürme uyumu'], 'Gelincik kapsülü olgunlaşınca üst tablasının altında delikler açılır; hafif bir esintide değil, yalnız tohumları uzağa savurabilecek şiddetli rüzgârda esnek sap sallanarak tuzluk gibi tohumları fırlatır.'),
  ('Durgun tatlı su göllerinde yetişen \'hint lotusu\' (Nelumbo nucifera) bitkisinin çiçek tablası olgunlaştığında neden ters dönmüş bir duş başlığını andıran süngerimsi koni şeklini alır?', 'Suda yüzen tablanın sert tohumları farklı noktalarda dibe bırakması için', ['Su altındaki balıkların solungaçlarından çıkan oksijeni toplayıp kök rizomlarına pompalamak için', 'Yağmur suyunu huni gibi biriktirerek su yüzeyindeki kurbağalara üreme havuzu oluşturmak için', 'Kış aylarında göl donduğunda buz tabakasını kırarak çiçeklerin su üstünde kalmasını sağlamak için'], 'Lotus meyve tablası kopup su üstünde tekne gibi yüzer (hidrokori) ve çürüdükçe içindeki bin yıldan uzun süre canlı kalabilen sert kabuklu fındıksı meyveler göl tabanına dağılır.'),
  ('Bahçelerde yetiştirilen \'kına çiçeği\' veya orman kenarlarındaki \'dokunmabana\' (Impatiens noli-tangere) bitkisinin olgun kapsüllerine parmakla değildiğinde meyve kapaklarının saniyenin binde biri sürede kıvrılarak tohumları fırlatmasının nedeni nedir?', 'Canlı meyve duvarındaki elastik gerilim enerjisinin temasla boşalması', ['Meyvenin ortasında bulunan basınçlı su kesesinin iğne ucu gibi delinerek tohumları su jetiyle püskürtmesi', 'Kapsülün dış yüzeyindeki tüylerin rüzgâr elektriğiyle yüklenip aynı yüklü tohumları birbirinden itmesi', 'Dokunan hayvanın vücut ısısının kapsül içindeki uçucu eter yağlarını anında buharlaştırması'], 'Impatiens cinsinin Latince adı (\'sabırsız\') bu balistokorik tepkiden gelir; etli perikarp kapaklarının iç ve dış hücre tabakalarındaki farklı turgor gerilimi temasla şerit yay gibi içe kıvrılarak tohumları fırlatır.'),
  ('Fiğ, katırtırnağı ve acıbakla (Lupinus) gibi birçok baklagil (Fabaceae) bitkisinde sıcak bir yaz öğleden sonrasında çalılıktan çıtırtı sesleri gelmesi ve tohumların etrafa saçılması hangi doku mekanizmasıyla gerçekleşir?', 'Çapraz dizili lif tabakalarının kururken kapağı burgu gibi bükmesiyle', ['Bakla içinde yaşayan simbiyotik bakterilerin öğle sıcağında azot gazı salarak kabuğu şişirip patlatmasıyla', 'Tohumların güneş altında aniden çimlenip kökçükleriyle meyve dikişini içeriden iterek kırmasıyla', 'Çalı üzerine konan çekirgelerin meyve saplarını eşzamanlı kemirerek yere düşürmesiyle'], 'Kuru bakla kapaklarında selüloz mikrofibrilleri iki ayrı tabakada birbirine çapraz açıyla dizilmiştir; nem azaldığında oluşan burulma gerilimi dikişleri ansızın ayırır ve kapaklar burgu şeklini alırken tohumları savurur.'),
  ('Hayvanların postuna veya kuş tüylerine dıştan tutunarak yayılan (epizookori) meyve ve tohumların çiçeklenme dönemindeki bitkisel görünümü, hayvanlarca yenerek yayılan (endozookori) etli meyvelerden nasıl farklıdır?', 'Soluk kahverengi-yeşil olup kanca, diken veya yapışkan tüyler taşırlar', ['Epizookor meyveler hayvanları uzaktan çekmek için parlak kırmızı-mor renkli, şekerli ve yoğun hoş kokuludur', 'Endozookor etli meyveler hayvanların ağzını yaralamak için sert çeliksi kancalar ve kuru paraşüt tüyleri taşır', 'Her iki gruptaki meyveler de olgunlaştığında tamamen saydamlaşarak yalnızca rüzgârla uçacak kadar hafifler'], 'Pıtrak (Xanthium), dulavratotu ve demirdikeni (Tribulus) hayvanın kendisini fark etmesini istemez; tesadüfi temasta post veya ayak tabanına kenetlenir, bu yüzden renk ve şeker yatırımı yapmaz.'),
  ('Kuşlar tarafından tüketilerek içindeki tohumları dışkıyla yayılan (ornitokori) böğürtlen, alıç, çobanpüskülü ve defne gibi meyvelerin hamken yeşil ve buruk, tohum olgunlaşınca ise parlak kırmızı veya siyah ve kokusuz olmasının evrimsel mantığı nedir?', 'Erken yenmeyi önleyip olgunlaşınca renk görüşü güçlü kuşlara sinyal vermek', ['Kırmızı ve siyah pigmentlerin güneş ışığını emerek tohumları kuş yemeden önce dal üzerinde kavurup sterilize etmesini sağlamak', 'Gece beslenen kör köstebekleri ve toprak solucanlarını parlak renkle ağaç tepesine çekerek tozlaşmayı hızlandırmak', 'Meyve kabuğundaki klorofilin sonbaharda tesadüfen bozulmasıyla hiçbir ekolojik işlevi olmayan rastgele renklerin ortaya çıkması'], 'Olgunlaşmamış meyve yeşil kalarak yapraklar arasında gizlenir ve tanen/ekşilikle korunur; tohum kabuğu sindirime hazır olduğunda kuşların tetrakromatik renk görüşüne hitap eden kırmızı/siyah antosiyanin sinyali açılır.'),
  ('Kardelen (Galanthus), siklamen, menekşe ve kırlangıçotu gibi yüzlerce orman altı bitkisinin tohumları üzerinde bulunan yağ ve proteince zengin beyaz etli uzantıya (\'elaiosom\') ne amaçla ihtiyaç duyulur?', 'Karıncaların etli kısmı yiyip sağlam tohumu yuvalarına taşıması için', ['Tohumun ilkbahar kar sularında batmadan yüzerek dere yatakları boyunca ovalara inmesini sağlamak için', 'Rüzgârlı havalarda paraşüt görevi üstlenerek tohumu orman kanopisinin üstüne çıkarmak için', 'Topraktaki zararlı nematod solucanlarını zehirleyerek tohum çevresini kimyasal olarak temizlemek için'], 'Karıncalarla tohum yayılmasına \'mirmokokori\' denir; elaiosom karınca larvaları için değerli yağ asitleri içerir, karıncalar bu ödülü koparıp yedikten sonra sağlam tohumu yangın ve tohum avcılarından korunaklı yer altı galerilerine bırakır.'),
  ('Yarı parazit ökseotu (Viscum album) bitkisinin beyaz inci benzeri meyvelerini yiyen ökse ardıcı kuşunun, tohumu toprağa düşürmek yerine yeni bir konak ağacın yüksek dalına bulaştırmasını sağlayan özel mekanizma nedir?', 'Yapışkan viscin özünün tohumu kuş gagası veya dışkıyla dala yapıştırması', ['Ökseotu tohumunun kuşun midesinde kanat çıkararak dışkılandığı anda en yakın çam dalına doğru uçması', 'Kuşların ökseotu tohumlarını kışlık yuva inşasında çamur yerine harç olarak dal çatallarına örmesi', 'Toprağa düşen ökseotu tohumlarının kırk metre uzunluğunda sarmaşık sürgünü çıkarıp ağaca tırmanması'], 'Ökseotu tohumu toprağa düşerse çimlenip yaşayamaz; meyve içindeki sümüksü \'viscin\' maddesi sindirimden bozulmadan çıkar ve tohumun doğrudan konak ağacın ince dal kabuğuna yapışıp emeç salmasını garantiler.'),
  ('Tropikal Asya ve Afrika\'da mango, muz (yabani), incir ve baobab gibi bazı ağaçların meyvelerinin yeşilimsi-soluk renkli olması, ana dal veya gövdeden açıkta sarkması ve geceleri keskin mayalanmış/misk kokusu yayması hangi tohum yayıcı gruba uyumdur?', 'Gece aktif olan meyve yarasalarına (chiropterokori)', ['Gündüz renklerle yön bulan sinekkuşlarına (ornitokori)', 'Toprak yüzeyinde yaşayan kara kaplumbağalarına (saurokori)', 'Açık savanda otlayan antilop sürülerine (epizookori)'], 'Meyve yarasaları (Uçan tilkiler vb.) gece beslenir, renk görmekten çok güçlü koku alma ve ekolokasyon kullanırlar; bu nedenle yarasa meyveleri yaprak kalabalığından uzakta açıkta sarkar ve keskin fermente koku yayar.'),
  ('Tarımını yaptığımız \'yerfıstığı\' (Arachis hypogaea) bitkisinde sarı çiçekler toprak üstünde açıp döllendikten sonra meyvenin toprağın altında olgunlaşması (\'jeokarpi\') hangi ilginç gelişim hareketiyle gerçekleşir?', 'Döllenme sonrası yumurtalık tabanındaki sapçığın (jinofor) pozitif geotropizmayla uzayarak gelişmekte olan meyveyi toprağın içine itmesiyle', ['Kök yumrularının toprak üstündeki çiçek polenlerini vakumla emerek kök uçlarında sahte meyveler üretmesiyle', 'Yağmur sularının yerfıstığı yapraklarını çamurla örterek tüm bitkiyi her yaz tamamen toprağa gömmesiyle', 'Tarla farelerinin çiçekleri koparıp kışlık yuvalarına çekmesi sonucunda meyvelerin yalnız orada büyümesiyle'], 'Yerfıstığı yumru değil gerçek bir baklagil meyvesidir; döllenmeden sonra \'ginofor\' (peg) adı verilen sapçık aşağı doğru uzayıp yumurtalığı 5-8 cm toprağa sokar ve fıstık kabuğu karanlıkta gelişir.'),
  ('Kurak iklim bitkilerinde keten tohumu, sinirliot (Plantago) ve fesleğen/çiya gibi birçok tohumun suyla temas ettiğinde çevresinde şeffaf, jelatinimsi bir müsilaj kılıfı oluşturmasının (\'miksokarpi\') birincil yararı nedir?', 'Toprak taneciklerine yapışarak rüzgârla savrulmayı önlemek ve çimlenen embriyo için mikro su deposu oluşturmak', ['Tohumun özgül ağırlığını düşürerek çöl fırtınalarında kum bulutlarıyla havalanmasını kolaylaştırmak', 'Güneş ışığını mercek gibi odaklayarak tohum kabuğunu yüz dereceye kadar ısıtıp çatlatmak', 'Topraktaki tüm bakterileri yapışkan jel içinde boğarak mikoriza oluşumunu kesin biçimde engellemek'], 'Tohum kabuğunun dış epidermisinde depolanan pektinli müsilaj ilk yağmurla şişer; hem tohumu uygun nemli toprağa demirler (ateleokori/tutunma) hem de su tutarak çimlenme kuraklığını tamponlar.'),
  ('Birçok orman ağacı ve yabani meyve türünün (örneğin alıç, ardıç, kiraz, gül/kuşburnu) tohumlarının bahçıvan tarafından doğrudan ekildiğinde çimlenmemesi, ancak bir kuşun sindirim kanalından geçtikten sonra hızla çimlenmesi neyle açıklanır?', 'Mide asidi ve taşlıktaki mekanik aşınmanın su geçirmez tohum kabuğunu inceltmesi ve meyve etindeki çimlenme önleyici kimyasalların yıkanmasıyla', ['Kuşun kan dolaşımındaki büyüme hormonlarının tohum kabuğundan geçerek embriyo DNA\'sını değiştirmesiyle', 'Tohumların yalnızca kırk iki derecelik kuş vücut sıcaklığında karanlıkta fotosentez başlatabilmesiyle', 'Sindirim kanalındaki bakterilerin tohumun içindeki nişastayı tamamen tüketerek embriyoyu hafifletmesiyle'], 'Hem etli meyve posasındaki absisik asit/fenolik inhibitörlerin uzaklaştırılması hem de sert endokarp/testa kabuğunun taşlıkta ve HCl asidinde aşındırılması (skarifikasyon) fizyolojik-fiziksel dormansiyi kırar.'),
  ('Amerika kıtasına özgü \'kaktüsler\' (Cactaceae) ile Afrika\'nın kurak bölgelerinde yaşayan \'ağaçsı sütleğenler\' (Euphorbiaceae) genetik olarak akraba olmamalarına karşın her ikisinin de yapraksız, oluklu yeşil gövdeli ve dikenli olması hangi evrimsel sürecin kanıtıdır?', 'Benzer çöl baskılarına bağımlı olmayan soyların benzer uyumlarla yanıt verdiği yakınsak (konvergent) evrimin', ['İki familyanın da son bin yılda insanlar tarafından melezlenerek tek bir ortak türden üretildiğinin', 'Kaktüs tohumlarının Afrika rüzgârlarıyla taşınıp orada sütleğen çiçeklerine dönüşerek mutasyon geçirdiğinin', 'Çöl ikliminde fotosentez yapan tüm bitkilerin DNA dizilimlerinin zamanla birebir özdeş hale geldiğinin'], 'Yakınsak evrimin ders kitabı örneğidir: Kaktüsler berrak öz sulu ve dikenleri areol tomurcuklarından çıkan Amerika bitkileridir; Afrika sütleğenleri ise zehirli beyaz süt (lateks) akıtan bambaşka bir familyadır ama aynı formu geliştirmiştir.'),
  ('Kaktüslerin ve ananas, agav, orkide (bazı epifitler) gibi kurakçıl bitkilerin gündüz yakıcı sıcakta stomalarını sımsıkı kapalı tutup yalnızca gece serinliğinde açarak CO₂ bağlamasını sağlayan fotosentez yolu hangisidir?', 'CAM (Krulassean Asit Metabolizması) fotosentezi', ['Standart C3 (Calvin-Benson döngüsü) fotosentezi', 'Demet kını hücreli C4 (mısır-şekerkamışı tipi) fotosentezi', 'Klorofilsiz kemosentetik karbon özümlemesi'], 'CAM bitkileri gece açtıkları stomalardan aldıkları CO₂\'yi malik aside dönüştürüp kofulda depolar (gece pH düşer); gündüz stomaları kapatıp su kaybetmeden malik asitten salınan CO₂ ile ışıkta şeker üretirler.'),
  ('Sütun kaktüslerinin (örneğin Saguaro - Carnegiea gigantea) gövdelerinin akordeon körüğü gibi dikey kaburga ve oluklara sahip olmasının biyomekanik işlevi nedir?', 'Nadir çöl sağanaklarında tonlarca su emildiğinde gövdenin çatlamadan genişlemesini, kuraklıkta ise büzülmesini sağlamak', ['Çöl kum fırtınalarında rüzgârı olukların içinde döndürerek kaktüsün kökleriyle yer değiştirmesini sağlamak', 'Gündüz güneşin tüm dik ışınlarını tek bir olukta toplayıp bitki öz suyunu kaynatmadan ısıtmak', 'Yalnızca geceleri olukların içini açarak içeride saklanan yeşil yaprakların nefes almasını sağlamak'], 'Oluklu (pliat) gövde geometrisi sayesinde dev bir Saguaro kaktüsü tek bir yağmurdan sonra yüzlerce litre su depoladığında epidermisi yırtılmadan körük gibi açılır ve aynı zamanda oluklar birbirine gölge yapar.'),
  ('Ömrünün tamamını suyun altında batık geçiren \'eleodea\' (Elodea) veya \'tilkikuyruğu\' (Ceratophyllum) gibi gerçek su içi bitkileri kara bitkileriyle karşılaştırıldığında hangi anatomik körelme görülür?', 'Kütikula çok ince veya yoktur, stomalar işlevsizdir ve suyun kaldırma kuvveti sayesinde odunsu destek dokusu ile ksilem çok indirgenmiştir', ['Su basıncına dayanmak için yaprakları beş milimetre kalınlığında mumlu kütikula ve yoğun lignin lifleriyle kaplanmıştır', 'Suyun içindeki oksijeni çekmek için yaprak yüzeylerinde kara bitkilerinden on kat fazla gömülü stoma bulunur', 'Kök sistemleri göl tabanından elli metre derine inen kalın odunlaşmış kazık köklerden meydana gelir'], 'Batık hidrofitler suyu ve çözünmüş CO₂/bikarbonatı doğrudan tek-iki hücre kalınlığındaki ince yaprak yüzeylerinden difüzyonla alır; su bitkiyi taşıdığı için sert mekanik dokuya (sklerankima) ihtiyaç duymaz ve akıntıda kırılmadan salınır.'),
  ('Amazon Nehri\'nin durgun kollarında yaşayan ve çapı 2,5-3 metreye ulaşan tepsi biçimli yüzen yaprakları küçük bir çocuğu bile batmadan taşıyabilen \'dev Amazon su zambağı\' (Victoria amazonica) bu taşıma gücünü neye borçludur?', 'Yaprağın alt yüzündeki içi hava dolu kalın damar kirişlerinden oluşan ızgara mimarisine ve kenarlarının tepsi gibi dik kıvrılmasına', ['Yaprak ayasının alt kısmında on santimetre kalınlığında katı mantar ve odun plakası bulunmasına', 'Göl tabanından yüzeye kadar yükselen yüzlerce odunsu sütun kökün yaprağı alttan desteklemesine', 'Yaprak üst yüzeyinin suyu iten demir ve silisyum kristallerinden sert bir kabuk örmesine'], 'Victoria amazonica yaprağının altındaki ışınsal ve halkasal hava kanallı damar ağı (1851 Londra Kristal Saray\'ın mimarı Joseph Paxton\'a ilham vermiştir) minimum biyokütleyle maksimum kaldırma ve yük dağıtımı sağlar.'),
  ('Su düğünçiçeği (Ranunculus aquatilis) veya su oku (Sagittaria) gibi amfibik su bitkilerinde aynı bireyin su altında kalan yapraklarının ince ipliksi-parçalı, su üstüne çıkan yapraklarının ise geniş ve düz ayalı olmasının nedeni nedir?', 'Su altında akıntı direncini azaltıp çözünmüş gaz alım yüzeyini büyütmek, su üstünde ise tam güneş ışığını yakalamak', ['Su altındaki yaprakların balıklar tarafından yenmiş olması, su üstündekilerin ise sağlam kalması', 'Bitkinin su altında kalan kısmının farklı bir genetik türe ait parazit kök olması', 'Su üstündeki yaprakların yalnız üreme sporu üretip hiç fotosentez yapmaması'], 'Çevresel heterofilinin en güzel örneğidir: Su altında gaz difüzyonu yavaş ve akıntı yırtıcı olduğu için solungaç gibi ince dilimli yapraklar gelişir; su yüzüne ulaşıldığında ise ışık ve hava ortamına uygun normal yaprak yapılır.'),
  ('Tuz Gölü kıyılarında ve Ege-Akdeniz tuzlu bataklıklarında geniş kızılımsı-yeşil halılar kuran, yaprakları körelmiş eklemli etli gövdeli \'deniz börülcesi\' (Salicornia europaea) yüksek toprak tuzluluğuna nasıl dayanır?', 'Tuz iyonlarını hücre kofullarına hapsedip osmotik basıncı yükselterek tuzlu topraktan su çeker ve etli dokusunda suyla seyreltir', ['Kökleriyle topraktaki tüm sodyum klorürü şekere dönüştürerek tatlı öz suyu üretir', 'Tuzlu suya hiç dokunmadan yalnızca sabah sisindeki saf su buharını gövdesinden emer', 'Topraktaki tuzu kök uçlarından elektrik akımıyla iterek çevresinde tatlı su havuzu kurar'], 'Gerçek bir öhalofit (tuzcul bitki) olan deniz börülcesi, Na⁺ ve Cl⁻ iyonlarını sitoplazmadaki enzimlerden uzak tutmak için merkezi kofulda biriktirir; sitoplazmada prolin/betain sentezler ve gövde sukulensiyle tuzu dengeler.'),
  ('Tuzlu dere boylarında ve deniz kıyılarında yetişen \'ılgın ağacı\' (Tamarix) ile \'deniz lavantası\' (Limonium) bitkilerinin kurak yaz günlerinde yaprak ve sürgünlerinin üzerinin ince beyaz tuz kristalleriyle kaplanmasının nedeni nedir?', 'Köklerle emilen fazla tuzu epidermisteki özel \'tuz salgı bezlerinden\' aktif taşımayla dışarı atmaları', ['Denizden esen rüzgârların yalnızca bu iki bitkinin üzerine seçici olarak tuz serpintisi bırakması', 'Yapraklardaki stomaların gündüz sodyum gazı soluyup gece klor kristali biriktirmesi', 'Bitkinin otçul hayvanları kendine çekmek için yaprak yüzeyinde yapay kaya tuzu üretmesi'], 'Krino-halofit (tuz salgılayan) bitkiler ksilemle yaprağa gelen fazla tuzu çok hücreli tuz bezlerinden dışarı pompalar; ılgın ağaçlarının altına damlayan bu tuzlu çiy rakip bitkilerin çimlenmesini de baskılar.'),
  ('Tropikal ve subtropikal deniz kıyılarının gelgit kuşaklarında yaşayan \'kırmızı mangrov\' (Rhizophora mangle) ağaçlarının gövdeden kemerler çizerek çamura saplanan \'destek (sırık) kökleri\' ile \'siyah mangrov\'un (Avicennia) çamurdan yukarı fışkıran binlerce \'pnömatofor\' kökünün işlevleri nedir?', 'Destek kökler dalga ve yumuşak çamurda tutunmayı sağlarken lentiselli pnömatoforlar oksijensiz çamurdaki köklere havadan oksijen taşır', ['Destek kökler deniz balıklarından besin emerken pnömatoforlar diken görevi görerek deniz kaplumbağalarını uzaklaştırır', 'Her iki kök tipi de yalnızca tatlı yağmur suyunu biriktiren kapalı su keseleri olarak görev yapar', 'Pnömatoforlar polen üreterek su altında tozlaşmayı sağlarken destek kökler fotosentez şekerlerini denize boşaltır'], 'Mangrov çamuru sülfürlü ve tamamen anoksiktir (oksijensiz); su üstüne çıkan süngerimsi ve kovucuklu (lentiselli) pnömatoforlar (solunum kökleri) cezir sırasında havayı alıp yer altı köklerine iletir.'),
  ('Amerika kıtası yağmur ormanlarında ağaç dallarında epifit yaşayan birçok \'bromeliad\' (ananasgiller) bitkisinin sert yaprak tabanlarının üst üste binerek ortada su dolu bir huni (\'fitotelma / tank\') oluşturması ekosisteme nasıl yansır?', 'Bitki su ve besini yaprak pullarıyla bu havuzdan emerken, ağaç tepesindeki bu küçük göletler zehirli ok kurbağası iribaşlarına ve böcek larvalarına yuva olur', ['Havuzda biriken asidik su konak ağacın dalını birkaç ayda çürüterek bromeliadın toprağa inmesini sağlar', 'Bu su deposu yalnızca yangın anında devrilerek orman tabanındaki alevleri söndürmek üzere evrimleşmiştir', 'Tank içindeki su yüksek oranda tuz içerdiği için içine düşen tüm canlıları anında mumyalayarak saklar'], 'Tank bromeliadlarında kökler yalnız dala tutunma teli işlevi görür; yaprak rozetinde biriken yağmur suyu ve çürüyen organik döküntü-kurbağa dışkıları emici peltat trikomlarla doğrudan yapraktan alınır.'),
  ('Venüs sinekkapanı (Dionaea muscipula) yaprağının iç yüzeyindeki duyu tüylerine bir yağmur damlası veya kuru yaprak kırıntısı değdiğinde tuzağın boş yere kapanıp enerji harcamaması hangi akıllı sayma mekanizmasıyla önlenir?', 'Kapanın tetiklenmesi için yaklaşık yirmi saniye içinde duyu tüylerine art arda en az iki kez dokunulması (iki aksiyon potansiyeli) gerekir', ['Tuzak yalnızca böceğin kanat çırpma ses frekansını duyduğunda hidrolik kapaklarını kapatır', 'Yaprak yüzeyi nesnenin ağırlığını tartarak yalnız bir gramdan ağır böceklerde tepki verir', 'Duyu tüyleri yalnızca gece karanlığında aktifleşip yağmurlu gündüz saatlerinde tamamen uyuşur'], 'İlk dokunuş kalsiyum sinyaliyle bir \'biyoelektrik bellek\' başlatır ama tuzağı kapatmaz; canlı av yürümeye devam edip 20-30 saniye içinde ikinci kez dokunduğunda eşik aşılır ve turgor-elastik burkulmayla kapan 0,1 saniyede kilitlenir.'),
  ('Türkiye\'nin Doğu Karadeniz ve bazı sulak bataklıklarında da doğal olarak yetişen \'güneşgülü\' (Drosera rotundifolia) ile \'yağotu\' (Pinguicula) bitkileri böcekleri hangi tip tuzakla yakalar?', 'Yaprak yüzeyindeki çiy damlası görünümlü yapışkan müsilaj bezleriyle (\'yapışkan kağıt tuzağı\')', ['İçi sindirim sıvısı dolu derin kaygan sürahi biçimli yapraklarla (\'çukur tuzağı\')', 'Vakum basıncıyla su pirelerini milisaniyede içeri çeken kapaklı keselerle (\'emme tuzağı\')', 'İki menteşeli dikenli yaprak lobunun hızla birbirine çarpmasıyla (\'kapan tuzağı\')'], 'Güneşgülünde (Drosera) yaprak üzerindeki kırmızımsı dokunaçların ucunda güneşte parlayan yapışkan damlacıklar bulunur; konan sinek yapıştığında komşu dokunaçlar ve yaprak ayası avın üzerine yavaşça kıvrılıp enzim salgılar.'),
  ('Tarlalarda domates, bakla ve ayçiçeği köklerine tutunan \'canavar otu\' (Orobanche) ile yonca gövdelerini sarı-turuncu iplikler gibi saran \'cinsaçı / küsküt\' (Cuscuta) bitkileri ökseotundan hangi kritik özellikle ayrılır?', 'Klorofilleri neredeyse hiç olmadığı için fotosentez yapamazlar; konak bitkinin hem ksileminden hem floeminden su ve organik besin çeken tam parazittirler', ['Kendi yeşil yapraklarıyla yüksek hızda fotosentez yapıp konak bitkiden yalnız azot gazı alan yarı parazittirler', 'Canlı bitkilere hiç zarar vermeyip yalnızca topraktaki ölü yaprak döküntüsünü çürüten saprofit mantarlardır', 'Konak bitkinin köklerine fosfat ve su sağlayarak karşılığında yalnız mekanik destek alan epifitlerdir'], 'Yarı parazit ökseotu yeşil olup yalnız ksileme bağlanırken, tam parazit (holoparazit) canavar otu ve cinsaçı fotosentez yeteneğini kaybetmiştir; emeçlerini (haustoryum) konağın floem borularına da sokarak hazır sükroz ve amino asit çekerler.'),
  ('Yüksek Alplerde ve Doğu Karadeniz\'in Kaçkar zirvelerinde yetişen \'edelweiss / aslanpençesi çiçeği\' (Leontopodium) ve dağ sığırkuyruğu gibi alpin bitkilerin kadife gibi yoğun beyaz keçe tüylerle kaplı olmasının temel işlevi nedir?', 'Yüksek irtifadaki şiddetli morötesi (UV) ışınları geri yansıtmak, rüzgârla su kaybını kesmek ve gece ayazına karşı ısı yalıtımı sağlamak', ['Dağ keçilerinin ve yaban koyunlarının tüylerine yapışarak tüm bitkinin kökleriyle başka zirvelere taşınmasını sağlamak', 'Yaz aylarında yağan kar tanelerini eritip doğrudan çiçek taç yapraklarından içeriye su emmek', 'Beyaz renkle kar örtüsü içinde gizlenerek bal arılarının çiçeğe konmasını tamamen engellemek'], 'Alpin bitkilerdeki yoğun ölü hava dolu yünsü tüyler (tomentoz örtü), hem 3000 metredeki yakıcı UV-B radyasyonunu optik lif gibi dağıtır hem de yün kazak etkisiyle gündüz ısısını hapsedip terlemeyi düşürür.'),
  ('İlkbahar başında nemli ve serin bir sabahta bahçedeki çilek, asma veya buğday yapraklarının uç ve diş kenarlarında dizilmiş berrak sıvı damlacıklarının çiy değil \'gutasyon (yaşarma)\' damlası olduğu nasıl anlaşılır?', 'Toprak nemli ve terleme durgunken kök basıncıyla yaprak kenarındaki \'hidatot\' gözeneklerinden itilen mineral-organik madde içeren ksilem öz suyu olmasıyla', ['Havadaki su buharının soğuk yaprak yüzeyinin tamamında rastgele yoğuşmasıyla oluşan tamamen saf damıtık su olmasıyla', 'Yaprak bitlerinin floemden emdikleri fazla şekerli öz suyunu üst yapraklardan aşağıya doğru damlatmasıyla', 'Bitkinin çiçek nektar bezlerinin tozlayıcı böcekleri çekmek için sabah erken saatte yaprak kenarına şurup salgılamasıyla'], 'Gece stomalar kapandığında terleme durur ancak ılık-nemli toprakta kök basıncı sürer; fazla su yaprak damar uçlarındaki sürekli açık \'su stomalarından\' (hidatotlardan) mineral yüklü damlalar halinde dışarı itilir.'),
  ('Utangaç \'küstüm otu\' (Mimosa pudica) bitkisinin tüysü bileşik yapraklarına dokunulduğunda yaprakçıkların bir-iki saniye içinde üst üste kapanıp sapın aşağı sarkması (\'sismonasti\') hangi hücresel olayla gerçekleşir?', 'Elektriksel uyarı sonucu yaprakçık tabanındaki \'pulvinus\' yastıkçıklarından potasyum ve suyun hızla dışarı çıkıp turgorun düşmesiyle', ['Oksin hormonunun yaprağın üst yüzünde hücre bölünmesini hızlandırarak kalıcı büyüme eğrilmesi yaratmasıyla', 'Yaprak damarlarındaki aktin-miyozin kas tellerinin ATP harcayarak yaprakçıkları mekanik olarak büzmesiyle', 'Dokunma sırasında açığa çıkan etilen gazının yaprak sapındaki ayrılma tabakasını geçici olarak koparmasıyla'], 'Tropizma büyüme hareketlerinden farklı olarak sismonasti yönü uyaranın yönüne bağlı olmayan hızlı ve tersinir bir turgor hareketidir; pulvinustaki motor hücrelerden K⁺ ve Cl⁻ çıkınca su akuaporinlerle boşalır ve yaprak katlanarak otçullara cılız/dikenli görünür.'),
  ('Güneydoğu Anadolu ve Akdeniz\'de meyveleri yenilen \'dikenli incir / kaynanadili\' (Opuntia ficus-indica) kaktüsünün birbirine eklemlenen yassı yeşil kürek biçimli parçaları botanikte hangi organdır?', 'Yaprak işlevi üstlenerek yassılaşmış fotosentetik gövde eklemleridir', ['Su depolamak için aşırı kalınlaşmış ve üst üste dizilmiş gerçek basit yaprak ayalarıdır', 'Toprak üstüne çıkarak klorofil kazanmış yassı solunum ve destek kökleridir', 'Döllenme öncesinde etli hale gelmiş dev yeşil çanak yaprak halkalarıdır'], 'Opuntia kaktüslerinde gerçek yapraklar çok genç sürgünlerde minik etli pullar halinde çıkıp hemen dökülür ve diken kümeleri kalır; kürek şeklindeki yeşil dilimler ise yassılaşmış gövdelerdir (kladod).'),
  ('Bezelye ve burçak gibi tırmanıcı bitkilerde yaprak ucunun ipliksi sülüklere (tendril) dönüşerek değdiği ince dala sarmal biçimde dolanması, buna karşılık \'duvar sarmaşığı\'nın (Hedera helix) düz taş duvara tırmanması karşılaştırıldığında hangi fark görülür?', 'Sülükler temas uyarısıyla (tigmotropizma) ince desteğe dolanırken duvar sarmaşığı gölge yüzündeki gövdeden çıkan yapışkan tutunma kökleriyle düz yüzeye kenetlenir', ['Duvar sarmaşığı taşları eriten nitrik asit salgılayıp oyuk açarken bezelye sülükleri yalnız rüzgâr gücüyle düğümlenir', 'Her iki bitki de yalnızca konak bitkinin floem borularına emeç salarak mekanik destek ve şeker alır', 'Bezelye sülükleri yalnız toprak altındaki taşlara tutunurken duvar sarmaşığı yalnız su yüzeyinde yüzer'], 'Tırmanıcı bitkiler farklı mekanizmalar kullanır: Asma gövde sülüğü, bezelye yaprak sülüğü, şerbetçiotu gövde sarılması (nutasyon), duvar sarmaşığı (Hedera) adventif tutunma kökleri ve Amerikan sarmaşığı (Parthenocissus) vantuzlu sülük diskleri geliştirir.'),
  ('Kızgın öğle güneşinden kaçınmak amacıyla Avustralya okaliptüslerinin (Eucalyptus) ve bazı kurakçıl çalıların olgun yaprak ayalarını yere paralel yatay yerine aşağıya doğru dikey (sarkık) konumda tutmasının fizyolojik yararı nedir?', 'Sabah ve akşam serinliğinde yatay ışığı yakalayıp en kavurucu öğle saatlerinde güneş yükünü ve aşırı ısınmayı en aza indirmek', ['Yağmur sularının yaprağa hiç değmeden doğrudan komşu ağaçların köklerine akmasını sağlamak', 'Yaprağın alt yüzünü tamamen köreltip stomaların yalnızca yaprak kenarında açılmasını zorlamak', 'Kış aylarında kar kütlesini yaprak üzerinde tutarak tomurcukları donmaktan korumak'], 'İzobilateral (iki yüzü benzer ve dikey) yaprak duruşu sayesinde okaliptüs ormanları altında koyu gölge oluşmaz (\'gölgesiz orman\'); bitki su stresinin zirve yaptığı öğle saatlerinde radyasyon emilimini düşürerek fotosentez verimini korur.'),
  ('Akdeniz kıyılarında, Tuz Gölü çevresinde ve yarı kurak bozkırlarda yetişen \'kapari / gebere otu\' (Capparis spinosa) bitkisinin kavurucu temmuz-ağustos aylarında etrafındaki tüm otlar sapsarı kurumuşken yemyeşil kalıp iri beyaz-mor çiçekler açabilmesi neye bağlıdır?', 'Kaya çatlaklarından onlarca metre derine inen kök sistemine, mumlu etli yapraklarına ve çiçeklerini yalnız serin akşam-sabah saatlerinde açmasına', ['Toprak yüzeyindeki kuru otların küllerini yapraklarıyla emerek içinden su sentezlemesine', 'Yalnızca yaz ortasında yağan muson yağmurlarıyla köklenip kışın tamamen ölmesine', 'Çiçeklerindeki mor erkek organ iplikleriyle havadaki azot gazını sıvı suya çevirmesine'], 'Kapari olağanüstü derin kök sistemi (20-30 m), kulakçık kökenli kıvrık dikenleri ve akşam açıp ertesi öğle sıcağında solan kısa ömürlü çiçekleriyle yaz kuraklığına tam uyum sağlamış değerli bir erozyon ve gıda bitkisidir.'),
  ('Gül (Rosa) ve böğürtlen (Rubus) gövdelerindeki batıcı sivri yapılar (\'diken/prickle\') ile alıç (Crataegus), yabani erik ve limon ağaçlarındaki sert batıcı yapılar (\'gerçek diken/thorn\') anatomik köken açısından nasıl ayırt edilir?', 'Gül dikeni yalnız epidermis ve korteks çıkıntısı olup parmakla kolayca koparılırken alıç dikeni iletim demetli başkalaşmış yan daldır', ['Gül dikeni başkalaşmış kök ucu olup odun borusu içerirken alıç dikeni yalnızca kurumuş reçine damlasıdır', 'Alıç ve limon dikenleri her sonbaharda yapraklarla birlikte dökülürken gül dikenleri çiçek taç yapraklarından gelişir', 'Her iki yapı da yalnızca yaprak kenarındaki dişlerin kıvrılmasıyla oluşur ve gövde kabuğuna hiç bağlanmaz'], 'Botanikte üç farklı batıcı yapı ayrılır: Gövde/dal kökenli iletim demetli \'diken\' (thorn - alıç, gladiçya), yaprak/kulakçık kökenli \'yaprak dikeni\' (spine - kaktüs, kadıntuzluğu, yalancı akasya) ve kabuk/epidermis çıkıntısı \'emergens/gül dikeni\' (prickle - gül, böğürtlen).'),
  ('Kuzey Amerika kökenli olup kent parklarında sıkça görülen \'gladiçya / üç dikenli akasya\' (Gleditsia triacanthos) ağacının doğrudan yaşlı gövdesi üzerinde bile 10-20 santimetrelik çatallı hançer gibi diken kümeleri bulunması geçmişte hangi savunma işlevine bağlanır?', 'Soyu tükenen mamut ve dev yer tembel hayvanları gibi iri otçulların ağaç kabuğunu soymasını ve tatlı baklaları erken koparmasını önlemeye', ['Ağaçkakan kuşlarının gövde kabuğunda yuva oyuğu açmasını engelleyerek böcekleri korumaya', 'Kış fırtınalarında savrulan yaprakları dikenlere takıp gövde çevresinde sıcak bir örtü örmeye', 'Yağmur bulutlarındaki yıldırım enerjisini paratoner gibi toplayıp köklerden toprağa aktarmaya'], 'Gladiçyanın yaşlı gövdeden çıkan dev dallanmış dikenleri bugünkü geyiklerin boyunu aşan bir bölgede yoğunlaşır; bu durum mamut/mastodongillerin gövdeye sürtünüp kabuk ve tatlı baklaları talan etmesine karşı evrimleşmiş bir megafauna savunmasıdır.'),
  ('Denizlerin sığ ve güneşli kumlu-çamurlu tabanlarında (örneğin Akdeniz\'de \'deniz çayırı / Posidonia oceanica\') geniş su altı çayırları kuran bitkiler, deniz yosunlarından (alglerden) hangi temel özellikleriyle ayrılır?', 'Karadan denize geri dönmüş gerçek kök, rizom, iletim demeti, çiçek ve su altında yayılan meyvelere sahip kapalı tohumlu bitkiler olmalarıyla', ['Hücre duvarlarında hiç selüloz bulundurmayıp yalnızca kırmızı fikoeritrin pigmentiyle spor üretmeleriyle', 'Deniz tabanına yalnız vantuzlu tutunma diskleriyle bağlanıp hiçbir damar dokusu taşımamalarıyla', 'Açık tohumlu kozalaklı ağaçların deniz suyu altında yaşayan cüce çalı formları olmalarıyla'], 'Posidonia oceanica ve Zostera marina alg (yosun) değil, evrimsel olarak karasal atalardan denize dönmüş çiçekli monokotil bitkilerdir; su altında ipliksi polenlerle (hidrofili) tozlaşırlar ve Akdeniz\'in oksijen deposudurlar.'),
  ('Akdeniz kumsallarında kıyıya vuran kahverengi keçe benzeri yumurta veya tenis topu büyüklüğündeki lifli küreler (\'Neptün topları / egagropili\') gerçekte hangi bitkinin hangi parçasının dalgalarla yuvarlanmasıyla oluşur?', 'Posidonia oceanica deniz çayırının rizom ve yaprak kını liflerinin deniz tabanında dalga hareketiyle keçeleşmesinin', ['Kıyıdaki fıstıkçamı ağaçlarından denize düşen ibrelerin tuzlu suda reçineyle birbirine yapışmasının', 'Hindistan cevizi meyvelerinin dış kabuk liflerinin Akdeniz akıntılarıyla Cebelitarık\'tan sürüklenmesinin', 'Deniz süngerlerinin iskelet ipliklerinin fırtınalı havalarda kum tanelerini sararak kıyıya atılmasının'], 'Posidonia oceanica\'nın çürümeye dirençli lignoselülozik yaprak kını lifleri sığ deniz tabanında salınım hareketiyle sarılarak sıkı \'Neptün toplarını\' oluşturur ve kıyı kumullarını dalga erozyonuna karşı koruyan doğal setler kurar.'),
  ('Trakya ve Anadolu\'nun kurak yamaçlarında tarla sınırı çiti olarak da bırakılan, biri düz diğeri geriye kıvrık kulakçık dikenleri taşıyan ve meyvesi ortası şişkin uçan daire (şapka) biçiminde kanatlı olan çalı hangisidir?', 'Karaçalı (Paliurus spina-christi)', ['Adi kadıntuzluğu çalısı (Berberis vulgaris)', 'Yabani çakal eriği ağacı (Prunus spinosa)', 'Dikenli kermes meşesi (Quercus coccifera)'], 'Cehrigillerden karaçalı, batıcı diken çiftleri ve 2-3 cm çapında dalgalı disk/şapka kanatla çevrili kuru odunsu meyveleriyle (rüzgârla yerde tekerlek gibi yuvarlanarak yayılır) hemen ayırt edilir.'),
  ('Karadeniz ve Marmara\'da yaygın yetişen \'muşmula / döngel\' (Mespilus germanica) meyvelerinin dalından ilk koparıldığında taş gibi sert ve buruk iken kasım-aralıkta yenilebilir tatlı-yumuşak kıvama gelmesi nasıl gerçekleşir?', 'Kırağı veya bekletmeyle pektinlerin çözünüp tanenlerin bağlanmasıyla', ['Meyve kabuğundaki klorofilin kış güneşinde nişastayı sıvı yağa dönüştürmesiyle', 'Topraktan meyve sapına kış boyunca pompalanan sakkarozun çekirdekleri eritmesiyle', 'Yalnızca küf mantarlarının meyveyi dıştan sarıp alkolik fermantasyon başlatmasıyla'], 'Bletting (olgunlaştırarak yumuşatma) sürecinde hücre duvarlarındaki pektin ve hemiselüloz enzimlerle parçalanır, nişasta şekere döner ve ağız buran çözünür tanenler polimerleşerek burukluğunu yitirir.'),
  ('Akdeniz ve Güneydoğu Anadolu\'da taşlık yamaçlarda yetişen, sonbaharda yaprakları alev kırmızısına dönen ve tüylü kızıl meyve salkımları ekşi baharat olarak kullanılan \'derici sumağı\' (Rhus coriaria) adını hangi özelliğinden alır?', 'Yapraklarındaki yüksek tanenin derileri yumuşak ve açık renkli tabaklamasından', ['Gövde sütünden ayakkabı tabanlarını yapıştıran doğal kauçuk zamkı üretilmesinden', 'Meyvelerindeki kırmızı boyanın yalnızca keçi derilerini ateşe dayanıklı kılmasından', 'Kök kabuklarındaki silis kristallerinin ham deriyi zımparalamada kullanılmasından'], 'Antepfıstığıgiller (Anacardiaceae) üyesi derici sumağının yaprakları kuru ağırlığının %25-35\'i oranında hidrolize olabilir tanen içerir ve ince eldiven/cilt derilerinin açık renkli tabaklanmasında yüzyıllarca kullanılmıştır.'),
  ('Kayseri ve İç Anadolu\'da sulak bahçelerde yetiştirilip kırmızı ekşi salkım meyvelerinden geleneksel içecek yapılan \'gilaburu\' (Viburnum opulus) çalısının düz şemsiye çiçek kurulunda en dış halkadaki çiçeklerin iri beyaz ama kısır (erkek ve dişi organsız) olmasının işlevi nedir?', 'Uzaktan böcekleri çekip ortadaki küçük verimli çiçeklere yönlendirmek', ['Rüzgârı yelken gibi tutarak ağır polenlerin yan çalılara savrulmasını sağlamak', 'Yağmur başladığında içe kapanarak ortadaki çiçeklerin ıslanmasını engellemek', 'Kısır taç yapraklarla fotosentez yaparak meyvelerin şeker oranını ikiye katlamak'], 'Gilaburuda çiçek kurulunun çevresindeki iri kar beyazı çiçekler üreme organlarını feda ederek \'reklam panosu\' (gösteriş çiçeği) görevini üstlenir; nektar ve tohum üretimi merkezdeki küçük erselik çiçeklerce yapılır.'),
  ('Park ve bulvarlarda yaz başında iri beyaz çiçek salkımları açan ve sonbahar-kış boyunca dallarından 30-40 santimetre uzunluğunda ince kalem veya fasulye kabuğu gibi kapsüller sarkan ağaç hangisidir?', 'Katalpa / Sigara ağacı (Catalpa bignonioides)', ['Tespih ağacı / Melia (Melia azedarach)', 'Kral pavlonya ağacı (Paulownia tomentosa)', 'Japon sofara ağacı (Styphnolobium japonicum)'], 'Bignoniaceae familyasından katalpa; çok geniş kalp biçimli yaprakları (genellikle üçlü halkalı dizilişli), orkideyi andıran benekli beyaz çiçekleri ve uçları püsküllü tohumlar içeren uzun silindirik kapsülleriyle tanınır.'),
  ('Tropikal Amerika ve Batı Afrika yağmur ormanlarının dev \'kapok / ipek pamuk ağacı\' (Ceiba pentandra), meyve kapsüllerinin içini dolduran sarımsı-beyaz liflerin hangi fiziksel özelliği nedeniyle uzun yıllar can yeleklerinde kullanılmıştır?', 'İçi hava dolu ve dış yüzü doğal mum kaplı liflerin suyu itip ağırlığının otuz katını yüzdürmesi', ['Liflerin tuzlu deniz suyuyla temas ettiğinde şişip sertleşerek tahta gibi katılaşması', 'Pamuk liflerinden on kat daha ağır olduğu için dalgıç kemerlerinde denge sağlaması', 'Ateşle karşılaştığında eriyerek su geçirmez kauçuk tabakasına dönüşmesi'], 'Gerçek pamuk (Gossypium) su çekip batar; kapok ağacının kapsül iç duvarından çıkan lignoselülozik-mumlu lifler ise son derece hafif, hidrofobik ve batmaz olup tohumların rüzgâr ve nehirlerle yayılmasını sağlar.'),
  ('Kuruyemiş olarak tüketilen \'kaju fıstığı\'nın (Anacardium occidentale) ağaç üzerindeki ilginç duruşunda üstteki kırmızı-sarı sulu armut benzeri yapı (\'kaju elması\') ile ucundan sarkan böbrek biçimli sert kabuklu kısım botanikte gerçekte nedir?', 'Renkli etli kısım şişkinleşmiş çiçek sapı (yalancı meyve), ucundaki böbrek biçimli sert yapı ise gerçek meyvedir', ['Üstteki sulu kısım gerçek yumurtalık meyvesi, alttaki sert böbrek ise dışarı fırlamış çıplak tohum taslağıdır', 'Üstteki kısım böcek sokmasıyla oluşan tatlı bir mazı, alttaki kısım ise başkalaşmış yan yaprak tomurcuğudur', 'Her iki kısım da ayrı çiçeklerden gelişip sonradan dal üzerinde birbirine aşılanmış ikiz meyvelerdir'], 'Antepfıstığı ve zehirli sarmaşıkla aynı aileden (Anacardiaceae) olan kajuda \'kaju elması\' hayvanları çeken etli çiçek sapıdır (hipokarp); gerçek sert meyvenin kabuğu yakıcı uruşiol/kardol reçinesi içerdiği için kaju fıstığı çiğ kabuklu satılmaz, ısıl işlemden geçirilir.'),
  ('Güneydoğu Asya\'da \'meyvelerin kralı\' denilen fakat soğan-sarımsak-terebentin karışımı keskin kükürtlü kokusu yüzünden otel ve uçaklara sokulması yasaklanan dikenli kabuklu \'durian\' (Durio zibethinus) ağacını doğada hangi canlılar tozlaştırır?', 'Gece uçan nektarcıl meyve yarasaları ve dev güveler', ['Gündüz yalnız mavi renkli çiçeklere konan bal arıları', 'Kokusuz kırmızı boru çiçekleri seçen sinekkuşları', 'Yalnızca rüzgâr akımlarıyla taşınan kuru polen bulutları'], 'Durian çiçekleri akşamüstü açılır, bol nektar ve ekşimsi koku yayarak Eonycteris spelaea gibi mağara meyve yarasalarını çeker; sabaha karşı taç yapraklarını döker, olgun meyvesini ise fil, orangutan ve misk kedileri yayar.'),
  ('Güney ve Güneydoğu Asya\'da yetişen \'jackfruit / jak meyvesi\' (Artocarpus heterophyllus), ağırlığı 35-45 kilograma ve boyu 80 santimetreye varabilen dünyanın en büyük ağaç meyvesini dallarını kırmadan nasıl taşır?', 'Çiçek ve bileşik meyvelerini ince uç sürgünlerde değil doğrudan kalın ana gövde ve yaşlı dallar üzerinde geliştirerek', ['Meyvelerini toprağın bir metre altında büyüterek olgunlaşınca kök basıncıyla yüzeye iterek', 'Meyvenin içini tamamen hidrojen ve metan gazıyla şişirip ağırlığını yarım kilogramda tutarak', 'Her meyvenin altından toprağa dikey destek kökleri indirip meyveyi yerden kolonla besleyerek'], 'Dutgiller (Moraceae) familyasından Artocarpus heterophyllus\'ta kauliflori (gövdede çiçeklenme/meyvelenme) hem 40 kiloluk dev bileşik meyvenin mekanik olarak taşınmasını hem de büyük memelilerin meyveye erişimini sağlar.'),
  ('Hint Okyanusu\'ndaki Seyşeller takımadalarından yalnız iki adada doğal yetişen \'deniz hindistancevizi / coco de mer\' (Lodoicea maldivica) palmiyesi, bitkiler âleminde hangi şaşırtıcı rekoru elinde tutar?', 'Tek bir tohumunun ağırlığı on beş ila yirmi beş kilograma ulaşarak dünyadaki en ağır ve en büyük tohum olması', ['Tohumlarının rüzgârla yüz kilometre uçabilen mikroskobik toz taneciklerinden oluşması', 'Okyanus akıntılarında batmadan beş yıl yüzerek dünyadaki tüm kıtalara yayılmış olması', 'Tohumunun dikildikten yalnızca yirmi dört saat sonra çimlenip bir ayda meyve vermesi'], 'Adının aksine Lodoicea maldivica\'nın dev çift loblu taze tohumu sudan ağır olduğu için denizde batar (kıyıya vuranlar yalnızca içi çürümüş boş kabuklardır); olgunlaşması 6-7 yıl, çimlenmesi ise 2 yıl sürer.'),
  ('Güney Asya\'da yetişen \'talipot palmiyesi\' (Corypha umbraculifera) ve bazı agav türleri 40 ila 80 yıl boyunca yalnız vejetatif büyüyüp ömrünün sonunda 6-8 metrelik dev bir çiçek salkımıyla milyonlarca tohum verdikten sonra tamamen ölür. Bu yaşam öyküsü stratejisine ne ad verilir?', 'Monokarpik (semelpar) yaşam döngüsü', ['Polikarpik (iteropar) yıllık meyvelenme döngüsü', 'Kleystogamik kapalı tomurcukta dölleme stratejisi', 'Fakültatif efemer tek mevsimlik kaçış stratejisi'], 'Çok yıllık ağaçların neredeyse tamamı ömrü boyunca defalarca meyve verirken (polikarpik), talipot palmiyesi, sago palmiyesi ve yüzyıl bitkisi (Agave americana) tüm gövde nişastasını tek bir dev üreme patlamasına harcayıp kurur (monokarpi).'),
  ('Yaşlı bir ceviz, meşe veya çam gövdesi enine kesildiğinde merkezdeki koyu renkli \'öz odun\' (heartwood) ile çevresindeki açık renkli \'diri odun\' (sapwood) karşılaştırıldığında fizyolojik görevleri hakkında hangisi doğrudur?', 'Su iletimi ve canlı parankima yalnız diri odunda sürerken öz odun tümüyle ölü hücrelerden oluşup mekanik destek ve çürüme direnci sağlar', ['Kökten yapraklara su iletimini yalnız koyu öz odun yaparken açık renkli diri odun yalnız fotosentez şekerlerini taşır', 'Öz odun her ilkbaharda bölünerek yeni halkalar üretirken diri odun kabuktan soyularak dökülür', 'Diri odun reçine ve tanenlerle tamamen tıkanmış ölü doku iken öz odun nişasta depolayan canlı dokudur'], 'Diri odun yaşlandıkça canlı parankima hücreleri ölmeden önce trake/trakeidleri tanen, fenol, yağ ve reçinelerle (ekstraktiflerle) doldurup öz oduna dönüştürür; böylece iç kısım su iletmez ama mantar ve böceklere dirençli bir sütun olur.'),
  ('Kızılçam, fıstıkçamı, okaliptüs ve kafur ağaçlarından oluşan bazı eş yaşlı ormanlara aşağıdan yukarıya bakıldığında komşu ağaçların tepe taçlarının birbirine değmeyip aralarında ışıltılı dar boşluk kanalları bıraktığı (\'taç utangaçlığı / crown shyness\') görülür. Bunun başlıca nedeni nedir?', 'Rüzgârda sallanan uç sürgünlerin birbirini mekanik olarak aşındırması ve uzak-kırmızı ışık algısıyla gölgeden kaçınması', ['Ağaç tepelerinde biriken zıt elektrik yüklerinin dalları mıknatıs gibi birbirinden bir metre uzağa itmesi', 'Köklerin toprakta birbirine değdiği anda tepe tomurcuklarına tüm büyümeyi durduran etilen gazı göndermesi', 'Sincap ve maymunların ağaçtan ağaca atlarken özellikle yalnız birbirine değen ince dalları kırıp temizlemesi'], 'Taç utangaçlığı hem rüzgârlı havalarda komşu uç tomurcukların çarpışarak kırılması hem de fitokrom reseptörlerinin komşu yapraklardan yansıyan uzak-kırmızı ışığı algılayıp yanal büyümeyi frenlemesiyle oluşur; ayrıca yaprak yiyen böceklerin geçişini zorlaştırır.'),
  ('Sık ve gölgeli bir meşe veya kayın meşceresinde kesim yapılarak yaşlı bir ağacın gövdesi aniden tam güneş ışığına açıldığında, daha önce dalsız olan alt gövde kabuğundan bir anda onlarca ince yeşil dal (\'su sürgünü / epikormik sürgün\') fışkırmasının kereste kalitesine etkisi nedir?', 'Kabuk altındaki uyur tomurcuklar uyanarak düzgün gövdede küçük budaklar oluşturur ve kaplamalık kereste değerini düşürür', ['Gövde çapı bir yılda üç katına çıkarak budaksız ve çok daha sert öz odun oluşmasını hızlandırır', 'Su sürgünleri fazla suyu terleterek ağacın öz odununda hiç çatlak oluşmamasını garantiler', 'Alt gövdeden çıkan bu dallar toprağa eğilip köklenerek ana gövdenin yaşlanmasını tamamen durdurur'], 'Epikormik (uyur) tomurcuklar yıllarca kambiyumla birlikte kabuk altında gizli uzar; ani ışık ve ısınma oksin baskısını kırıp bu tomurcukları patlatır, bu nedenle kaliteli meşe ormancılığında gövdeleri gölgeleyen bir alt tabaka (kayın/gürgen) korunur.'),
  ('Doğu Karadeniz\'in yaşlı ladin ormanlarında veya Kuzey Amerika\'nın ılıman yağmur ormanlarında genç ladin ve tsuga fidanlarının orman tabanında rastgele değil de düz bir çizgi halinde sıra sıra dizilmiş olması hangi \'hemşire kütük\' (nurse log) olayının sonucudur?', 'Devrilip çürüyen yaşlı bir ağaç gövdesinin sünger gibi nem tutup fideleri yerdeki kalın yosun-ot rekabetinden yukarıda büyütmesinin', ['Ormancıların fidanları eski devrik ağaçların altına paralel ip çekerek eşit aralıklarla dikmesinin', 'Sincapların kışlık kozalakları yalnızca düz bir çizgi boyunca yer altına gömme alışkanlığının', 'Devrilen ağacın kabuğundaki tomurcukların çürümeden kök salıp klonal kardeş gövdeler çıkarmasının'], 'Nemli yaşlı ormanlarda çürüyen devrik gövdeler (\'hemşire kütükler\') su tutan yumuşak odunu, mikoriza zenginliği ve taban otlarının gölgesinden yüksek konumuyla küçük tohumlu ladin fideleri için birincil çimlenme yatağıdır; kütük tamamen çürüyüp yok olunca ağaçlar payanda kökler üzerinde sıra halinde kalır!'),
  ('Ilıman bir orman ağacının (örneğin kayın veya meşe) tepe tacının en güneşli üst kısmından alınan bir \'ışık yaprağı\' ile aynı ağacın en alt iç kısmından alınan bir \'gölge yaprağı\' karşılaştırıldığında hangisi gözlemlenir?', 'Işık yaprağı daha küçük ayalı, daha kalın ve çok katlı palizat parankimalı iken gölge yaprağı daha geniş, ince ve koyu yeşildir', ['Gölge yaprağı su kaybını önlemek için çok kalın kütikulalı ve dar iğnemsi iken ışık yaprağı tek hücre kalınlığındadır', 'Işık yaprağında hiç stoma ve kloroplast bulunmazken gölge yaprağında üç sıra palizat dokusu yer alır', 'Her iki yaprak da aynı ağacın genetik ürünü olduğu için kalınlık, yüzey alanı ve anatomileri birebir aynıdır'], 'Aynı ağaç üzerinde bile ışığa göre anatomik uyum gelişir: Güneş yaprakları dik gelen yüksek foton akısını işlemek için kalın çift sıra palizat dokusu ve küçük yüzey alanı yaparken, gölge yaprakları azıcık dağınık ışığı yakalamak için ince ve geniş bir panel gibi yayılır.'),
  ('Kuzey kutup sınırındaki Sibirya ve Kanada taygasında \'kara ladin\' (Picea mariana) ve \'Doğu Sibirya melezi\' (Larix gmelinii) ağaçlarının yalnız 30-50 santimetre çözülen permafrost (donmuş toprak) üzerinde devrilmeden yaşayabilmesi nasıl bir kök mimarisiyle sağlanır?', 'Kazık kökten vazgeçip çözülen ince aktif tabaka içinde geniş bir tabak gibi yatay yayılan sığ saçak kök sistemiyle', ['Permafrost buzunu eriten sıcak asitler salgılayıp yirmi metre derindeki ana kayaya çapa salan kazık kökle', 'Toprak altına hiç kök indirmeden yalnızca komşu kayalara vantuzlu sülüklerle tutunan gövde tabanıyla', 'Yalnızca yaz aylarında kök çıkarıp kışın tüm kök sistemini çürüterek gövde içinde saklamasıyla'], 'Özellikle Doğu Sibirya\'da -60 °C kışlara dayanan Larix gmelinii, alttaki sürekli donmuş toprak engelini aşamadığından gövde boyunun birkaç katı genişlikte yüzeye paralel yayılan sığ kök ağlarıyla tutunur; permafrost düzensiz eridiğinde ise ağaçlar yana yatarak \'sarhoş orman\' görüntüsü verir.'),
  ('Anadolu\'nun İç ve Güneydoğu kesimlerinde step ile yüksek dağ ormanları arasındaki geçiş kuşağında (1000-1800 m) seyrek meşe, ardıç, ahlat, alıç ve yabani badem ağaçlarının otsu bozkır elemanlarıyla iç içe oluşturduğu topluluğa ne ad verilir?', 'Bozkır ormanı', ['Subasar alüvyal longoz ormanı', 'Herdemyeşil Kolşik yağmur ormanı', 'Tuzcul halofitik çorak bataklık'], 'İran-Turan bölgesinin yarı kurak dağ eteklerinde yağışın kapalı ormana tam yetmediği ama derin köklü kurakçıl ağaçların (tüylü meşe, boylu ardıç, yabani badem, çitlembik) seyrek koruluklar kurduğu kuşağa \'step ormanı\' (kserofitik açık orman) denir.'),
  ('Konya-Karaman\'dan Doğu Anadolu\'ya ve İran\'a uzanan kurak taşlı yamaçlarda çalımsı ağaççıklar kuran \'yabani badem\' (Prunus webbii, P. argentea, P. orientalis) türlerinin dikenli ve ince yeşil sürgünlü olması hangi uyumu yansıtır?', 'Yaz ortasında küçük yapraklar dökülse bile yeşil kalan sürgün kabuğuyla fotosentez yapmayı ve keçi otlatmasına direnmeyi', ['Kış ortasında kar suyunu diken uçlarından emerek kök sistemine ihtiyaç duymadan büyümeyi', 'Sürgünlerdeki klorofille havadaki serbest azotu doğrudan amonyağa indirgemeyi', 'Rüzgârla kırılan dikenli dalların kumullarda yuvarlanarak tohumsuz yayılmasını sağlamayı'], 'Anadolu yabani badem gen merkezidir; kurakçıl yabani badem türleri gümüşi tüylü küçük yaprakları, kseromorfik dikenli dalları ve yeşil asimilasyon sürgünleriyle 250-350 mm yağışta dahi tutunarak erozyonu önler.'),
  ('Karadeniz, Marmara ve Batı Anadolu\'nun ılıman meşe ormanlarında geniş yayılış gösteren \'Macar meşesi\' (Quercus frainetto), diğer yerli meşe türlerimizden yaprak şekliyle nasıl kolayca tanınır?', 'Çok kısa saplı iri yapraklarının derin ve düzenli loblu olup kulakçıklı tabana doğru yelpaze gibi genişlemesiyle', ['Yapraklarının zeytin yaprağı gibi küçük, dikensiz, tam kenarlı ve dört mevsim yeşil kalmasıyla', 'İğne biçimli sert yapraklarının sürgün üzerinde üçlü halkalar halinde dizilmesiyle', 'Yapraklarının yedi ayrı yaprakçıktan oluşan tüysü bileşik bir yapı göstermesiyle'], 'Balkanlar ve Kuzeybatı-Batı Anadolu\'da görkemli ormanlar kuran Macar meşesi, 15-25 cm boyundaki çok derin oyuklu ve loblarının kenarı tekrar küçük lobcuklu karakteristik büyük yapraklarıyla hemen seçilir.'),
  ('Doğu Karadeniz\'in kıyıdan 1500 metreye kadar olan sarp ve yağışlı vadilerinde yaygın olan \'sakallı kızılağaç\' (Alnus glutinosa subsp. barbata), heyelanlı yamaçların onarımında ormancılar tarafından neden öncelikli tercih edilir?', 'Işık seven hızlı öncü doğası, güçlü saçak kökleri ve Frankia bakterileriyle çıplak mineral toprağı azotça zenginleştirmesi nedeniyle', ['Koyu gölge altında yüz yıl bekleyip hiç su tüketmeden kayaları eritebilmesi nedeniyle', 'Tohumlarının yalnız kar tabakası altında çimlenip üç bin metre zirvelerde orman kurması nedeniyle', 'Reçineli iğne yapraklarının kış aylarında yağmur damlalarını tamamen buharlaştırması nedeniyle'], 'Heyelanla üst verimli toprağı sıyrılmış çıplak yamaçlarda azot çok kıttır; kızılağaç rüzgâr ve suyla gelen küçük tohumlarıyla bu alanlara hızla yerleşir, simbiyotik azot fiksasyonuyla toprağı diğer orman ağaçlarına hazırlar.'),
  ('Avrupa ve Karadeniz ormanlarının alt tabakasında yetişen \'adi fındık\' (Corylus avellana) çalımsı ve çok gövdeli ocaklar yaparken, Batı Karadeniz (Bolu-Kastamonu) dağ ormanlarında 20-25 metre boyunda tek ve kalın gövdeli kereste ağacı formuna ulaşan yerli fındık türü hangisidir?', 'Türk fındığı / Ağaç fındığı (Corylus colurna)', ['Doğu Karadeniz tombul fındığı (Corylus maxima)', 'Yabani ayıfındığı çalısı (Styrax officinalis)', 'Kafkas kanatlı cevizi (Pterocarya fraxinifolia)'], 'Bolu-Mengen, Kastamonu ve Kuzeybatı Anadolu karışık ormanlarında doğal yetişen Türk ağaç fındığı (Corylus colurna), mantarımsı çatlaklı tek dik gövdesi, derin saçaklı meyve kılıfları ve kurak-kireçli kent caddelerine dayanıklılığıyla Avrupa peyzajında da çok aranan bir ağaçtır.'),
  ('Karadeniz\'in kayın ve göknar ormanları altında siyah üzümsü meyveler veren ve yapraklarından Karadeniz\'de geleneksel siyah çay benzeri içecek de hazırlanmış olan yerli yaban mersini (likapa) türü hangisidir?', 'Doğu Karadeniz ayıüzümü / Likapa (Vaccinium arctostaphylos)', ['Kırmızı meyveli adi kızılcık ağacı (Cornus mas)', 'Zehirli güzelavratotu çalısı (Atropa belladonna)', 'Dikenli yabani kuşburnu çalısı (Rosa canina)'], 'Fundagiller (Ericaceae) üyesi Vaccinium arctostaphylos (Trabzon çayı / likapa), asidik orman topraklarında 1-3 metre boylanan çalı formundadır; antosiyanince çok zengin mor-siyah meyveleri hem yaban hayatı hem insan beslenmesinde değerlidir.'),
  ('Orman açıklıklarında ve yeni kesim alanlarında pembe çiçek salkımları açan \'yakıotu\' (Chamaenerion angustifolium) veya \'söğüt\' türlerinin ürettiği binlerce ipeksi tüylü tohumun rüzgârla taşınma mesafesini belirleyen en kritik atmosferik olay nedir?', 'Güneşli öğleden sonralarında ısınan yer yüzeyinden yükselen dikey termal hava akımları ve türbülans', ['Yalnızca gece yarısı orman tabanına çöken soğuk ve hareketsiz çiy tabakasının yoğunluğu', 'Yağmurlu havalarda su damlalarının tüyleri ağırlaştırarak tohumu sapan gibi fırlatması', 'Dünya\'nın manyetik alan çizgilerinin selüloz tüylerini kuzey-güney doğrultusunda çekmesi'], 'Yatay esen hafif bir rüzgâr tüylü tohumu yalnız birkaç on metre taşırken, güneşli kuru günlerde oluşan konvektif yükselim (updraft) tohumları kanopi üstündeki atmosfer sınır tabakasına çıkararak kilometrelerce ötedeki yeni yangın/kesim boşluklarına ulaştırır.'),
  ('Kuzey Amerika\'da \'Osage portakalı / ayı elması\' (Maclura pomifera) ağacının greyfurt büyüklüğünde, pütürlü sarı-yeşil, sütlü ve bugünkü sığır-geyiklerin yemediği ağır meyvelerinin tarla kenarlarında yalnız ağaç altına yığılıp kalması neyin sonucudur?', 'Pleistosen sonunda mamut ve dev tembel hayvanlar gibi iri meyve yayıcı megafaunanın soyunun tükenmiş olmasının', ['Meyvelerin rüzgârla uçmak için evrimleştiği halde son yüzyılda rüzgâr hızlarının yarıya düşmesinin', 'Ağacın gerçekte deniz kıyısı bitkisi olup meyvelerinin yalnızca gelgit dalgalarıyla taşınabilmesinin', 'Meyve içindeki tohumların tamamen kısır olup doğada yalnızca kök yumrularıyla çoğalabilmesinin'], 'Dutgillerden Maclura pomifera, dikenli dalları nedeniyle çit ağacı ve esnek turuncu odunu nedeniyle Kızılderili yayı (\'bois d\'arc\') yapımında ünlüdür; dev meyveleri ise mamut/at/gomfoter yayılımına uyumlu tipik bir megafauna sendromu örneğidir.'),
  ('Avustralya ve Yeni Gine\'nin yağmur ormanlarında yaşayan, uçamayan dev kuş \'tepeli devekuşu / kasovari\' (Casuarius), insan yumruğu büyüklüğünde etli meyveler veren yüzlerce yağmur ormanı ağacı için neden \'kilit taşı tohum yayıcı\' sayılır?', 'Çok iri meyveleri çekirdeğini kırmadan bütünüyle yutup kilometrelerce uzağa taşıyabilen ormandaki tek omurgalı olması nedeniyle', ['Gagasıyla ağaç kabuklarını soyarak tohumların doğrudan gövde üzerinde çimlenmesini sağlaması nedeniyle', 'Kanat çırpışıyla orman tabanında fırtına yaratarak kanatlı tohumları kanopiye uçurması nedeniyle', 'Yalnızca zehirli yabancı ot tohumlarını öğütüp yerli ağaç tohumlarına hiç dokunmaması nedeniyle'], 'Güvercinler ve küçük meyve kuşları çapı 2-3 santimetreyi aşan meyveleri yutamaz; kasovariler ise 70-100\'den fazla büyük tohumlu yağmur ormanı ağacının (Ryparosa, Endiandra vb.) uzun mesafeli tek etkin yayıcısıdır.'),
  ('Yol kenarlarında, kaldırım aralarında ve çiğnenen çimenliklerde yetişen \'büyük sinirliot\' (Plantago major) bitkisinin tohumlarının tarih boyunca Avrupalı yerleşimcilerin ayak bastığı her kıtaya hızla yayılıp yerlilerce \'beyaz adamın ayak izi\' olarak adlandırılmasının mekanizması nedir?', 'Yağmurda şişip yapışkan müsilajla kaplanan küçük tohumların çamurlu çizme, tekerlek ve hayvan toynaklarına yapışarak taşınması', ['Sinirliot yapraklarının rüzgârda kopup balon gibi okyanuslar üzerinden kıtalara uçması', 'Yerleşimcilerin bu bitkiyi buğdaydan daha verimli olduğu için ekmeklik tahıl olarak ekmesi', 'Tohumların gemi ahşaplarını delerek kereste içinde gizlice yeni kıtalara geçmesi'], 'Antropokori (insan aracılığıyla yayılma) ve epizookorinin kesiştiği bu olayda basılmaya çok dayanıklı rozet yapraklı Plantago major\'un ıslanınca tutkal gibi yapışan tohumları ayakkabı tabanlarındaki çamurla tüm dünyaya taşınmıştır.'),
  ('Antalya\'daki Köprülü Kanyon Milli Parkı, genellikle mezarlık ve yol kenarı ağacı olarak tanıdığımız hangi Akdeniz ibreli türünün dünyadaki en geniş saf doğal ormanlarından birini barındırmasıyla ünlüdür?', 'Dallı servi (Cupressus sempervirens var. horizontalis)', ['Sütun formlu doğu mazısı (Platycladus orientalis)', 'Yüksek dağ boylu ardıcı (Juniperus excelsa)', 'Gümüşi mavi Atlas sediri (Cedrus atlantica)'], 'Mezarlıklardaki piramidal servi kültürel bir form iken, yatay dallı doğal varyete (var. horizontalis) Köprülü Kanyon\'un sarp kalker kayalıklarında 400 hektarı aşan eşsiz bir saf doğal orman kurar.'),
  ('Osmanlı mutfağından geleneksel şerbet kültürümüze giren ekşi-tatlı koyu kahverengi meyve özü, Afrika savan kökenli hangi baklagil ağacının kırılgan kabuklu baklalarının içinden çıkarılır?', 'Demirhindi ağacı (Tamarindus indica)', ['Akdeniz keçiboynuzu ağacı (Ceratonia siliqua)', 'Orta Amerika kakao ağacı (Theobroma cacao)', 'Karayip yenibahar ağacı (Pimenta dioica)'], 'Arapça \'temr-i hindi\' (Hint hurması) adından dilimize geçen demirhindi ağacının bakla meyveleri tartarik asit ve şekerce zengin yapışkan bir meyve eti barındırır.'),
  ('Zeytinyağlı dolma ve köfte harçlarında sıkça kullanılan \'yenibahar\' baharatının İngilizcede \'allspice\' (tüm baharatlar) olarak adlandırılmasının nedeni ve elde edildiği ağaç hangisidir?', 'Karayipler kökenli Pimenta dioica ağacının kurutulmuş ham meyvelerinin tarçın, karanfil ve muskat kokularını tek başına birleştirmesi', ['Dört farklı tropikal ağacın kabuk, kök, yaprak ve tohumlarının fabrikada öğütülerek tek bir toz karışımda birleştirilmesi', 'Akdeniz defnesi ile yabani mersin meyvelerinin deniz suyunda bekletilip güneşte kavrulmasıyla üretilmesi', 'Doğu Asya yıldız anason meyvesinin olgunlaştıktan sonra toprağa gömülerek fermente edilmesi'], 'Mersingiller (Myrtaceae) ailesinden Pimenta dioica iki evcikli bir Orta Amerika/Jamaika ağacıdır; tam olgunlaşmadan toplanıp kurutulan bezelye iriliğindeki meyveleri öjenol başta olmak üzere çok zengin uçucu yağlar içerir.'),
  ('Akdeniz ve Karadeniz\'in bakir kumsallarında ağustos-eylül aylarında kızgın kumdan çıkıp bembeyaz kokulu çiçekler açan koruma altındaki \'kum zambağı\' (Pancratium maritimum), tohumlarını yeni kumsallara nasıl ulaştırır?', 'Kömür siyahı ve içi hava dolu mantarımsı dokulu köşeli tohumlarının hem deniz suyunda haftalarca yüzmesi hem kumda rüzgârla sürüklenmesiyle', ['Dikenli kapsüllerinin plajda yürüyen deniz kaplumbağalarının kabuklarına kancalarla yapışmasıyla', 'Tohumlarının tatlı jelatinle kaplı olup yalnızca martılar tarafından yutularak dışkılanmasıyla', 'Kapsülün öğle sıcağında patlayarak ağır tohumları yüz metre içerideki ormana fırlatmasıyla'], 'Kum zambağının siyah tohumları olağanüstü hafiftir; süngerimsi hava parankiması sayesinde tuzlu deniz suyunda batmadan akıntılarla başka koylara taşınır (talassokori), siyah rengi ise ısı ve UV koruması sağlar.'),
  ('Hiçbir akarsu bağlantısı olmayan yeni oluşmuş volkanik krater göllerinde veya yapay göletlerde birkaç yıl içinde su kamışı (Potamogeton) ve su mercimeği gibi sucul bitkilerin kendiliğinden belirmesi Charles Darwin\'in deneyleriyle nasıl açıklanmıştır?', 'Göçmen su kuşlarının ayaklarına yapışan çamurda ve sindirim kanallarında canlı kalan tohumların gölden göle taşınmasıyla', ['Balık yumurtalarıyla birlikte bulutlara karışan su bitkilerinin yağmur damlaları içinde göle düşmesiyle', 'Toprak altındaki kireçtaşı çatlaklarından göller arasında yüz kilometre uzunluğunda kök uzamasıyla', 'Göl tabanındaki yeşil alglerin birkaç yıl içinde evrimleşerek çiçekli su bitkilerine dönüşmesiyle'], 'Darwin tek bir su kuşunun ayağından kazıdığı bir kaşık kurumuş göl çamurunu ıslattığında içinden 537 adet canlı bitki fidesi çıktığını göstermiş; ayrıca sert tohumların ördek sindiriminden canlı geçtiğini kanıtlamıştır.'),
  ('Kokulu menekşe (Viola odorata) bitkisinin erken ilkbaharda böcekleri çeken mor kokulu açık çiçekler (\'kazmogamik\') üretirken, yaz aylarında yaprak altında hiç açılmayan küçük tomurcuk benzeri kapalı çiçeklerde (\'kleystogamik\') kendi kendini döllemesinin nedeni nedir?', 'İlkbaharda genetik çeşitlilik için çapraz tozlaşmayı denerken yazın düşük maliyetle kesin tohum üretimini garantilemek', ['Yaz aylarında gün ışığının mor taç yaprakları yakarak tüm kloroplastları öldürmesini engellemek', 'Kış yaklaşırken yalnızca toprak altındaki köstebekler aracılığıyla tozlaşmaya geçiş yapmak', 'Kapalı çiçeklerde ürettiği tohumların rüzgârla yüz kilometre uzağa uçmasını sağlamak'], 'Tozlayıcı böcekler soğuk/yağışlı baharda yetersiz kalabilir; menekşe ve oksalis gibi bitkiler taç yaprak ve nektar harcaması gerektirmeyen kapalı (kleystogamik) çiçeklerle düşük enerjili \'sigorta tohumları\' bağlar.'),
  ('Yıllardır hiç el değmemiş bir çayır veya orman toprağı sabanla sürüldüğünde ya da kepçeyle kazıldığında birkaç hafta içinde binlerce gelincik, sığırkuyruğu, labada ve sirken fidesinin fışkırması hangi ışık algılama mekanizmasıyla tetiklenir?', 'Toprak yüzüne çıkan küçük tohumlardaki fitokrom pigmentinin güneşin kırmızı ışığını (660 nm) algılayıp Pfr aktif formuna geçmesiyle', ['Saban demirinin sürtünme ısısının topraktaki tüm tohum kabuklarını yüz derecede eritmesiyle', 'Toprağın alt katmanındaki karanlıkta biriken mavi ışığın kök tüylerini doğrudan uyarmasıyla', 'Kazılan toprağa giren azot gazının tohumlardaki nişastayı anında glikoza dönüştürmesiyle'], 'Küçük tohumların besin deposu azdır; derinde çimlenirlerse yüzeye ulaşamadan ölürler. Bu nedenle pozitif fotoblastik tohumlar yıllarca toprak tohum bankasında uyur ve yalnız toprak karışıp gün ışığı (kırmızı ışık) gördükleri anda çimlenirler.'),
  ('Fasulye, kabak ve kayın tohumları çimlenirken hipokotil ekseni kıvrılıp uzayarak çenekleri toprak üstüne çıkarırken (\'epigeik çimlenme\'), bezelye, meşe palamudu ve kestane çimlenirken çeneklerin toprak altında kalmasının (\'hipogeik çimlenme\') ekolojik avantajı nedir?', 'Büyük besin deposu toprağın altında kalarak geç ilkbahar donlarından ve fideyi kemiren otçullardan korunur; üst sürgün koptuğunda yeniden sürebilir', ['Toprak altında kalan çenekler karanlıkta çok daha hızlı fotosentez yaparak köklere oksijen üretir', 'Hipogeik çimlenen tohumlar hiç suya ihtiyaç duymadan yalnız kuru kayalar üzerinde kök salabilir', 'Çeneklerin yer altında kalması tohumun rüzgârla yeniden havalanıp başka vadiye taşınmasını sağlar'], 'Küçük tohumlu bitkiler (epigeik) çeneklerini hızla güneşe çıkarıp ilk güneş panelleri olarak kullanmak zorundadır; meşe ve kestane gibi iri tohumlular (hipogeik) ise zengin çenek kasasını yer altında güvende tutup otçul ısırığında koltuk tomurcuklarından yedek sürgün çıkarır.'),
  ('Doğu Afrika savanlarında yetişen \'ıslık çalan akasya\' (Vachellia drepanolobium) ağaçlarının tabanı ceviz gibi şişkin içi boş dikenler (\'domatya\') üretmesi ve rüzgâr estiğinde bu dikenlerdeki deliklerden ıslık sesi çıkması hangi üçlü ekolojik ilişkiyle bağlantılıdır?', 'Ağaç şişkin dikenlerde Crematogaster karıncalarına yuva ve nektar sunar; karıncalar ise zürafa ve filleri yüzlerinden ısırıp ağacı savunur', ['Islık sesi yırtıcı aslanları ağacın altına çekerek otçul antilopların akasyaya yaklaşmasını tamamen engeller', 'İçi boş dikenler yağmur suyunu biriktirerek kurak mevsimde ağacın yapraklarına su pompalar', 'Kuşlar bu dikenlerin içinde kuluçkaya yatarak ağacın çiçeklerini gagalarıyla tozlaştırır'], 'Mirmekofit (karınca bitkisi) akasyada karıncalar içi boş şişkin dikenlere giriş deliği açar (rüzgârda flüt gibi öten delikler bunlardır); bir fil veya zürafa dala dokunduğunda binlerce karınca öfkeyle çıkıp filin hassas hortum içini ısırarak dev otçulu bile kaçırır!'),
  ('Ev ve ofislerde sıkça yetiştirilen geniş alacalı yapraklı \'difenbahya / ağlayan çiçek\' (Dieffenbachia) veya filkulağı bitkisinin yaprağı bir evcil hayvan ya da çocuk tarafından ısırıldığında dil ve boğazda şiddetli yanma ile şişmeye (\'dilsiz kamışı\' etkisine) ne yol açar?', 'Özel idiyoblast hücrelerinin fırlattığı binlerce mikroskobik çift uçlu kalsiyum oksalat iğne kristalinin (\'rafid\') mukozayı delip tahriş edici proteaz sokması', ['Yaprak damarlarındaki koyu kırmızı reçinenin ağız içinde anında donarak dişleri birbirine yapıştırması', 'Bitkinin yüksek oranda kafein ve nikotin salgılayarak dil kaslarını soğutması', 'Yaprak yüzeyindeki kancalı yıldız tüylerin boğaz duvarına mekanik olarak kenetlenmesi'], 'Yılanyastığıgiller (Araceae) ailesindeki pek çok bitkide mekanik-kimyasal savunma olarak demetler halinde \'rafid\' (kalsiyum oksalat monohidrat iğneleri) bulunur; hücre ısırıldığında müsilaj şişer ve iğneleri ok yağmuru gibi ağız dokusuna saplar.'),
  ('Türkiye ve Akdeniz\'de \'arı orkidesi / sinek orkidesi\' olarak bilinen \'Ophrys\' cinsi yer orkideleri, çiçeklerinde bir damla bile tatlı nektar üretmedikleri halde erkek yaban arılarını kendilerine çekip tozlaşmayı nasıl başarırlar?', 'Alt dudak yaprağının tüylü dokusu, rengi ve salgıladığı dişi arı eşey feromonu taklidiyle erkek arıyı çiftleşme girişimine (\'psödokopülasyon\') ikna ederek', ['Çiçeğin içini arı kovanı sıcaklığına ısıtıp yağmurlu günlerde erkek arılara barınak sağlayarak', 'Erkek arıları kaygan bir keseye düşürüp polen yüklemeden dışarı çıkmalarını saatlerce engelleyerek', 'Yalnızca bal arılarının polen sepetlerine yapışan kancalı tohum kapsülleri fırlatarak'], 'Eşeysel aldatmaca (sexual deception) tozlaşmasında Ophrys çiçeği ilgili tekil arı türünün dişisinden daha çekici hidrokarbon/feromon karışımı yayar; dişi arılardan birkaç hafta önce çıkan sabırsız erkek arılar çiçekle çiftleşmeye çalışırken başlarına poliniyum yapışır.'),
  ('Madagaskar\'da yetişen ve çiçek mahmuzu (nektar borusu) 28-32 santimetre uzunluğa ulaşan \'Darwin yıldız orkidesi\'ni (Angraecum sesquipedale) 1862\'de inceleyen Charles Darwin, meslektaşlarının alay etmesine karşın henüz kimsenin görmediği hangi canlıyı doğru öngörmüştür?', 'Bu derin mahmuzun dibindeki nektara ulaşabilecek otuz santimetre uzunluğunda hortuma sahip dev bir atmaca güvesinin (Xanthopan morganii) adada yaşadığını', ['Madagaskar lemurlarının ince parmaklarıyla mahmuzu yarıp polenleri gece karanlığında taşıdığını', 'Uzun gagalı dev bir nektar kuşunun bu adada yakın zamanda soyunun tükenmiş olduğunu', 'Orkidenin mahmuzunu yalnızca yağmur suyunu biriktirmek için uzattığını ve kendi kendine döllendiğini'], 'Birlikte evrim (koevolüsyon) kuramının en ünlü öngörüsüdür: Darwin\'in ölümünden 21 yıl sonra 1903\'te Madagaskar\'da tam da öngördüğü uzunlukta hortuma sahip dev güve (Xanthopan morganii praedicta - \'öngörülen\') keşfedilmiştir.'),
  ('Amerika kıtasındaki \'sinekkuşları\' veya Eski Dünya\'daki \'nektar kuşları\' tarafından tozlaştırılan (ornitofil) çiçeklerin (örneğin küpe çiçeği, ateş çiçeği, ebegümeci akrabaları) arılarla tozlaşan çiçeklerden ayrılan karakteristik ortak özellikleri nelerdir?', 'Genellikle parlak kırmızı-turuncu renkli, sarkık boru biçimli, konma tablasız, kokusuz ve bol sulu seyreltik nektarlı olmaları', ['Gece yarısı açılan soluk beyaz renkli, ağır misk kokulu ve çok az miktarda katı polen içeren düz çiçekler olmaları', 'Yalnızca morötesi kılavuz çizgili mavi-sarı dudaklı olup böceğin ağırlığıyla açılan kapaklı çiçekler olmaları', 'Taç yaprakları tamamen körelmiş, yeşilimsi kahverengi ve rüzgârda sallanan tüysü tepecikli olmaları'], 'Arılar kırmızı dalga boyunu zayıf görürken kuşlar kırmızıyı çok net seçer ve çoğu nektar kuşunun koku duyusu zayıftır; bu yüzden kırmızı ve kokusuz boru çiçekler nektarı arılardan gizleyip havada asılı duran yüksek enerjili kuşlara sunar.'),
  ('Domates, patlıcan, patates ve yaban mersini (Vaccinium) çiçeklerinde nektar bulunmaz ve polenler erkek organ başçığının ucundaki minik deliklerden dışarı dökülmez; bu çiçeklerde yüksek meyve tutumu için seralara neden bal arısı yerine \'bombus arısı\' (Bombus terrestris) kovanları konulur?', 'Bombus arısının çiçeğe tutunup uçuş kaslarını saniyede yüzlerce kez titreterek (\'vızıltılı tozlaşma / buzz pollination\') polenleri tuzluk gibi sarsıp çıkarması nedeniyle', ['Bal arılarının domates yapraklarındaki solanin maddesinden zehirlenip serada hiç uçamaması nedeniyle', 'Bombus arılarının güçlü çeneleriyle erkek organ keselerini kemirip yırtarak polen yemesi nedeniyle', 'Domates çiçeklerinin yalnız on derecenin altındaki soğuk sera ortamında açılabilmesi nedeniyle'], 'Porisidal (uçtan delikli) anterlere sahip ~20.000 çiçekli bitki türünde kuru polenler elektrostatik ve mekanik sarsıntıyla dışarı fırlar; bal arıları (Apis mellifera) bu sonik titreşim (orta Do notası civarı) davranışını yapamazken bombus arıları ustalıkla yapar.'),
  ('Tohum çimlendiğinde taşların arasında karanlıkta kalan bir kök ucunun şaşmaz biçimde yerçekimi yönüne (aşağıya) doğru kıvrılmasında (\'pozitif gravitropizma\') yerçekimi vektörünü ilk algılayan hücresel yapı hangisidir?', 'Kök şapkası (kaliptra) merkez hücrelerinde tabana çöken yoğun nişasta dolu plastitler', ['Kök emici tüylerinin uç zarında suyun akış yönünü ölçen akuaporin protein kanalları', 'Ksilem borularının içinde yerçekimiyle aşağı düşen demir ve kalsiyum iyon kümeleri', 'Epidermis yüzeyinde toprak basıncını algılayan mekanik silisyum kristalleri'], 'Kaliptradaki kolumella hücrelerinde ağır nişasta tanecikleriyle dolu amiloplastlar (statolitler) her zaman hücrenin alt zarına çöker; kök yatay çevrildiğinde statolitlerin yeni alt duvara çökmesi PIN taşıyıcılarıyla oksini alt yüze yönlendirir ve kökte yüksek oksin alt yüzün uzamasını baskılayıp kökü aşağı büker.'),
  ('Kuzey Amerika\'dan dünyaya yayılan \'zehirli sarmaşık\' (Toxicodendron radicans) ve Doğu Asya \'vernik ağacı\' (Toxicodendron vernicifluum) bitkilerine sürtünen insanlarda günler süren şiddetli alerjik deri döküntüsüne (\'kontakt dermatit\') hangi yağlı savunma bileşiği yol açar?', 'Deri proteinlerine kovalent bağlanarak bağışıklık sistemini aşırı tetikleyen \'uruşiol\' fenolik reçinesi', ['Yalnızca güneş ışığı altında aktifleşip deride yanık oluşturan \'furanokumarin\' öz suyu', 'Sinir kavşaklarını saniyeler içinde uyuşturan uçucu \'koniin\' baldıran alkaloidi', 'Deri gözeneklerine mekanik olarak batan mikroskobik \'silisyum\' tüy kırıkları'], 'Antepfıstığı, mango ve kaju ile aynı familyadan (Anacardiaceae) olan bu bitkilerin reçine kanallarındaki yağsı \'uruşiol\' (Japonca vernik ağacı \'urushi\'den gelir) suyla yıkanınca kolay çıkmaz ve gecikmeli T-hücresi aşırı duyarlılığı yaratır.'),
  ('Karadeniz\'in sarp kayalıklarında ve kireçsiz yamaçlarında yetişen \'ayıüzümü / unutmabeni değil koca yemiş akrabası doğu çilek ağacı\' dışında, yüksek alpin kayalıklarda toprağa yapışık halı gibi büyüyen \'dağ sivricesi / cüce söğüt\' (Salix herbacea ve Salix reticulata) neden \'dünyanın en küçük ağacı\' olarak anılır?', 'Yalnızca bir ila altı santimetre boylanıp otsu görünmesine rağmen toprak altında odunsu çok yıllık gövde ve gerçek söğüt kedicikleri taşıması nedeniyle', ['Normal bir salkım söğüt tohumunun saksıda budanarak yapay olarak küçültülmüş olması nedeniyle', 'Tek bir yaprağının içinde hem kök hem kozalak barındıran tek hücreli bir bitki olması nedeniyle', 'Yalnızca bir hafta yaşayıp ölen ve hiç odun dokusu üretmeyen bir tundra otu olması nedeniyle'], 'Arktik tundra ve yüksek alpin zirvelerde (Kaçkarlar ve Alpler dahil) yaşayan cüce söğütler, dondurucu rüzgârdan korunmak için odunsu dallarını toprak ve yosun içinde yatay süründürür, yüzeye yalnız iki minik yaprak ve bir kedicik çıkarır.'),
  ('Akdeniz kızılçam ormanlarında yangınların yıkıcı \'tepe yangınına\' dönüşmesini engellemek amacıyla ormancıların yol kenarlarında alt dalları budaması ve boylu maki çalılarını seyreltmesi (\'yanıcı madde yönetimi\') hangi ilkeye dayanır?', 'Yerdeki örtü yangınını yüksek ağaç tacına tırmandıran dikey \'merdiven yanıcıları\' (ladder fuels) keserek alevi zeminde tutmaya', ['Ormandaki tüm ağaçları kesip araziyi tamamen çıplak kayalık haline getirmeye', 'Kızılçam ağaçlarının reçine üretimini durdurarak odunlarını yanmaz hale getirmeye', 'Toprağın nemini buharlaştırarak rüzgâr hızını orman içinde iki katına çıkarmaya'], 'Kalın kabuklu yaşlı çam ağaçları yerden hızla geçen düşük şiddetli örtü yangınından çoğu kez sağ çıkar; ancak alt dallar ve sık çalılar \'alev merdiveni\' oluşturursa yangın kanopiye sıçrayıp tüm meşcereyi öldüren tepe yangınına dönüşür.'),
  ('Güneydoğu Anadolu\'da Şanlıurfa, Mardin ve Gaziantep\'ten Orta Doğu\'ya uzanan sıcak ve kurak platolarda kendiliğinden yetişen, menengiçten daha iri yapraklı ve yağlı meyvelerinden Siirt-Mardin yöresinde ünlü \'bıttım sabunu\' yapılan yabani fıstık ağacı hangisidir?', 'Buttum / Bıttım ağacı (Pistacia khinjuk)', ['Ege kıyı sakız ağacı (Pistacia lentiscus)', 'Akdeniz derici sumağı (Rhus coriaria)', 'Bozkır kuş iğdesi ağacı (Elaeagnus angustifolia)'], 'Pistacia khinjuk (bıttım/buttum), Güneydoğu ve Doğu Anadolu\'nun sıcak kayalık vadilerinde doğal yetişir; hem Siirt fıstığı için mükemmel bir kuraklık anacıdır hem de mavimsi-yeşil yağlı meyvelerinden geleneksel bıttım sabunu ve kahvesi yapılır.'),
  ('İç ve Doğu Anadolu\'nun nehir vadilerinde, çakıllı dere yataklarında ve yüksek dağ eteklerinde (1000-2500 m) dikenli gümüşi çalılar kurarak toprağı tutan, turuncu renkli ekşi meyveleri C vitamini ile omega-7 yağ asitlerince son derece zengin olan bitki hangisidir?', 'Çıçırgan / Yabani iğde (Hippophae rhamnoides)', ['Yabani çakal eriği çalısı (Prunus spinosa)', 'Kırmızı meyveli adi kızılcık (Cornus mas)', 'Dere boyu pembe zakkumu (Nerium oleander)'], 'İğdegillerden (Elaeagnaceae) Hippophae rhamnoides (\'deniz iğdesi / çıçırgan / vitamin ağacı\'), iğde ve kızılağaç gibi köklerinde Frankia bakterileriyle azot bağlar; dalları sımsıkı saran parlak turuncu meyveleri kış boyu kuşları besler ve gıda-kozmetikte kullanılır.'),
  ('İlkbaharda henüz yaprakları yokken bile ezilmiş mürver yaprağının kokusundan ve genç dallarının kırıldığında ortasından çıkan çok geniş, bembeyaz ve strafor gibi yumuşak \'öz (pith)\' dokusundan hemen tanınan orman kenarı ağaççığı hangisidir?', 'Kara mürver (Sambucus nigra)', ['Adi şimşir çalısı (Buxus sempervirens)', 'Tüylü kartopu çalısı (Viburnum lantana)', 'Kırmızı kızılcık ağacı (Cornus mas)'], 'Adoxaceae familyasından kara mürverin bir yıllık dallarında odun halkası ince, merkezdeki süngerimsi beyaz öz dokusu ise çok geniştir (botanik laboratuvarlarında ince jilet kesiti alırken bitki dokusunu sıkıştırmak için \'mürver özü\' kullanılır).'),
  ('Bahçe ve parklarda altın sarısı sarkık çiçek salkımları nedeniyle çok beğenilerek dikilen \'sarı salkım / altın yağmuru\' (Laburnum anagyroides) ağacının bakla meyveleri ve tohumları hakkında çocuk parkları açısından hangi kritik uyarı yapılır?', 'Bezelyeye benzeyen tohumları nikotin benzeri etkili \'sitizin\' alkaloidi içerdiğinden ağacın tüm kısımları insanlar için yüksek derecede zehirlidir', ['Baklaları olgunlaştığında acı kavun gibi patlayarak sert taşları gözlere fırlatma riski taşır', 'Yapraklarındaki yakıcı tüyler temas anında ısırgan otundan on kat şiddetli deri su toplamasına yol açar', 'Çiçek polenleri havadaki oksijenle birleşerek bahçe toprağını aşırı asidik hale getirir'], 'Baklagillerden Laburnum anagyroides görsel olarak beyaz çiçekli yalancı akasyanın sarı ikizi gibidir; ancak yalancı akasya çiçekleri yenilebilirken sarı salkımın özellikle bezelye görünümlü bakla tohumları tehlikeli sitizin zehri taşır.'),
  ('Avustralya\'nın doğu yağmur ormanlarına özgü olan ve lezzetli yuvarlak iç tohumları dünyanın en pahalı kuruyemişlerinden sayılan \'makadamya cevizi\' (Macadamia integrifolia), meyve kabuğu açısından hangi mekanik özellikle tanınır?', 'Küresel tohum kabuğunun yaklaşık iki bin Newton kırılma direnciyle yeryüzündeki en sert fındıksı tohum kabuklarından biri olmasıyla', ['Meyve kabuğunun kağıt kadar ince olup parmakla hafifçe sıkıldığında kendiliğinden ikiye ayrılmasıyla', 'Tohumlarının dış kabuğunun suda şişen yumuşak sünger dokusundan meydana gelmesiyle', 'Kabuğun üzerinde hayvan kürküne yapışan yüzlerce esnek kanca dikeni bulunmasıyla'], 'Proteaceae familyasından Macadamia\'nın kahverengi tohum kabuğu (testa) iç içe kenetlenmiş taş hücrelerinden (sklereid) oluşur ve alüminyum ya da betona yakın kırılma tokluğu göstererek tohumu avcılardan korur; özel çelik kırıcılarla açılır.'),
  ('Güney Amerika\'nın sıcak-nemli nehir taşkın ovalarında (örneğin Pantanal) ve kurak Chaco ormanlarında yetişen, gövdesi gül dikeni gibi iri konik dikenlerle zırhlı ve karın kısmı şişe gibi şişkin (\'sarhoş ağaç / şişe ağacı\') pamuklu tür hangisidir?', 'İpek ağacı / Palo borracho (Ceiba speciosa)', ['And bulut ormanı kınakına ağacı (Cinchona officinalis)', 'Patagonya güney kayını ağacı (Nothofagus pumilio)', 'Amazon Brezilya cevizi ağacı (Bertholletia excelsa)'], 'Kapok ağacının yakın akrabası olan Ceiba speciosa (Akdeniz sahil parklarında da dikilir), gençken klorofilli yeşil ve dev dikenli şişkin gövdesinde hem su depolar hem yapraksız kurak mevsimde gövde fotosentezi yapar.'),
  ('Ağaç gövdesinin dış kabuğu ve hemen altındaki ince iç kabuk (sekonder floem) çepeçevre tam bir halka halinde soyulup çıkarıldığında (\'bilezikleme / girdling\') ağaç neden hemen ertesi gün solmaz da aylar sonra köklerinden başlayarak ölür?', 'İçteki odun boruları (ksilem) sağlam kaldığı için yapraklara su çıkışı sürer; ancak floem kesildiği için köklere şeker inemez ve kökler açlıktan ölünce ağaç kurur', ['Ağacın yaprakları kök olmadan da havadan su alabildiği için yalnız kış donları geldiğinde üşüyerek ölür', 'Kabuk soyulduğu anda ksilem boruları reçineyle tıkanır fakat yapraktaki yedek su ağacı altı ay idare eder', 'Floem kesildiğinde topraktaki mineraller yapraklarda aşırı birikerek sonbaharda zehirlenmeye yol açar'], 'Marcello Malpighi\'nin 17. yüzyıldaki ünlü bilezikleme deneyiyle kanıtlandığı üzere, halkanın üst kısmında aşağı inemeyen şekerler birikip kabuğu şişirir; kökler ise depoladığı nişasta tükenene kadar su göndermeye devam eder, kökler ölünce tepe aniden kurur.'),
  ('Kanada ve Kuzey Avrasya ormanlarında Suzanne Simard ve meslektaşlarının karbon izotoplarıyla yürüttüğü araştırmalarda \'ormanın yer altı interneti (Wood Wide Web)\' olarak popülerleşen ortak mikorizal ağların fidan gençleşmesindeki rolü nedir?', 'Aynı veya farklı türden ağaç köklerini mantar hifleriyle birbirine bağlayarak gölgedeki genç fidanlara karbon, azot ve savunma sinyalleri aktarılmasına aracılık etmesi', ['Ormandaki tüm ağaçların kök hücrelerini tek bir dev çekirdekli hücrede birleştirerek tür farkını yok etmesi', 'Mantar ipliklerinin yer altındaki kayaları parçalayarak ağaçlara doğrudan elektrik akımı üretmesi', 'Yalnızca zehirli mantarların sağlıklı ağaç köklerini boğarak ormanı bozkıra dönüştürmesi'], 'Ortak mikorizal ağlar (CMN), yaşlı \'merkez/anaç ağaçların\' (hub trees) çevresindeki yüzlerce fidanı mantar ağlarına bağlamasını sağlar; örneğin yaprak döken kağıt huşu ile gölgedeki Douglas göknarı arasında mevsimsel karbon alışverişi ve böcek saldırısı uyarıları gözlenmiştir.'),
  ('Kuzey Amerika\'nın batısından dünyaya kereste ağacı olarak yayılan \'Douglas göknarı\' (Pseudotsuga menziesii), Türkçe adında göknar geçmesine rağmen kozalağı elimize alındığında hangi benzersiz ayrıntıyla tüm gerçek göknar ve ladinlerden tek saniyede ayrılır?', 'Sarkık kozalak pullarının arasından dışarıya doğru üç çatallı \'fare kuyruğu ve arka ayakları\' gibi uzun zarsı braktelerin çıkmasıyla', ['Kozalaklarının dal üzerinde dik durup dokunulduğu anda toz halinde dağılmasıyla', 'Kozalak pullarının etli mavi-siyah bir üzüm gibi kaynaşıp hiç açılmamasıyla', 'Her bir kozalağın ucundan yeni bir yeşil yapraklı sürgünün büyümeye devam etmesiyle'], 'Bilimsel adı Pseudotsuga (\'yalancı tsuga\') olan bu dev ağaç ne gerçek göknar ne de çamdır; sarkık kozalaklarının her pulunun dışından sarkan üç dişli uzun \'brakte\' (Kızılderili efsanesinde yangından kozalağın içine saklanan farelerin kuyruğu ve iki ayağı!) kesin tanı özelliğidir.'),
  ('Karadeniz\'in kireçsiz nemli yamaçlarında ve İstanbul Belgrad Ormanı\'nda doğal yayılış gösteren \'muşmula\' ve \'kestane\'nin yanı sıra, sonbaharda dört köşeli pembe bir rahip şapkasını andıran kapsülü açıldığında içinden turuncu arilluslu tohumlar sarkan çalı/ağaççık hangisidir?', 'Papazkülahı / İğ ağacı (Euonymus europaeus ve Euonymus latifolius)', ['Siyah meyveli adi kurtbağrı çalısı (Ligustrum vulgare)', 'Mavi meyveli yabani çakal eriği (Prunus spinosa)', 'Kırmızı salkımlı adi gilaburu (Viburnum opulus)'], 'Celastraceae familyasından papazkülahı, pembe kapsül duvarı ile parlak turuncu tohum örtüsünün (arillus) yarattığı keskin iki renkli kontrastla sonbaharda kızılgerdan ve ardıç kuşlarını uzaktan çeker; sert sarı odunundan geçmişte yün eğirme iği yapılmıştır.'),
  ('Doğu Akdeniz ve Güney Anadolu\'nun maki ve kızılçam ormanlarında çok yaygın olan, derimsi bileşik yapraklarının ekseni kanatlı ve reçineli küçük kırmızı meyveleri sonradan siyaha dönen her dem yeşil çalı hangisidir?', 'Sakız çalısı / Menengiç akrabası mastik (Pistacia lentiscus)', ['Kışın yaprak döken tüylü meşe (Quercus pubescens)', 'Üç yaprakçıklı zehirli sarı salkım (Laburnum anagyroides)', 'Beyaz çiçekli yabani mürver çalısı (Sambucus ebulus)'], 'Menengiçten (Pistacia terebinthus) farklı olarak kışın yaprak dökmeyen ve yaprak ucunda tekil tepe yaprakçığı bulunmayan (çift tüysü - paripinnat) Pistacia lentiscus, kanatlı yaprak ekseniyle Akdeniz makisinin en karakteristik temel taşlarındandır.'),
  ('Maki kuşağının mis kokulu her dem yeşil üyesi \'mersin / murt\' (Myrtus communis) çalısının yaprakları ışığa doğru kaldırılıp bakıldığında yaprak ayasının iğneyle delinmiş gibi yüzlerce şeffaf küçük noktayla kaplı olduğu görülür. Bu noktaların gerçek yapısı nedir?', 'Yaprak mezofil dokusu içine gömülü mirtol ve sineol uçucu yağı dolu iç salgı cepleri', ['Yaprak pirelerinin öz suyu emerken açtığı ve iyileşmiş küçük mantarlı yara izleri', 'Fazla kalsiyum tuzunu dışarı atmak için her iki yüzde açılmış dev su gözenekleri', 'Kloroplastların öğle güneşinden kaçarak kenarlara çekilmesiyle boş kalan ölü hücreler'], 'Mersingiller (Myrtaceae - mersin, okaliptüs), Sedefotugiller (turunçgil yaprakları) ve Sarıkantarongillerde (Hypericum perforatum - \'delikli ot\') ışığa tutulduğunda parlayan bu şeffaf noktalar gerçek delik değil, aromatik uçucu yağ dolu küresel salgı cepleridir.'),
  ('Toroslar\'dan Doğu Anadolu\'ya uzanan taşlı yamaçlarda yetişen \'boylu ardıç\' (Juniperus excelsa) ormanlarının geçmişte kesildikten sonra kendi kendine çok zor gençleşip seyrelmesinin ve ormancıların ardıç tohumlarını çimlendirmek için uyguladığı biyolojik bilginin özü nedir?', 'Tohumların çok kalın reçineli kabuk ve embriyo dormansisi taşıması; doğada ardıç kuşlarının (Turdus) kursak-taşlığından geçerek çimlenebilmesi', ['Ardıç ağaçlarının yalnızca yüz yılda bir kozalak üretmesi ve polenlerinin suyla taşınması', 'Ardıç tohumlarının çimlenmek için mutlaka şiddetli tepe yangını aleviyle kavrulması gerekmesi', 'Yalnızca kütük sürgünüyle çoğalabilen ardıcın doğada hiç canlı tohum bağlayamaması'], 'Ardıç ile ardıç kuşları (ökse ardıcı, tarla ardıcı, karatavuk) adını bile birbirinden alan sıkı bir ortaklığa sahiptir; fidanlıklarda ardıç üretimi için de kuş sindirimini taklit eden mekanik/asitli aşındırma ve sıcak-soğuk katlama protokolleri geliştirilmiştir.'),
  ('Karabük sınırları içindeki \'Yenice Ormanları\'nın Dünya Doğal Hayatı Koruma Vakfı (WWF) tarafından Avrupa\'nın acil korunması gereken sıcak noktaları arasına alınmasını sağlayan en belirgin dendrolojik özelliği nedir?', 'Anıtsal çap ve boya ulaşan çok sayıda yapraklı-ibreli ağaç türünün (ıhlamur, porsuk, akçaağaç, kayın, göknar, üvez, karaağaç) olağanüstü zengin karışım yapması', ['Türkiye\'de yalnızca kaktüs ve ağaçsı sütleğenlerin doğal yayılış gösterdiği tek kurak vadi olması', 'Ormanın tamamının yüz yıl önce Avustralya\'dan getirilen okaliptüs fidanlarıyla kurulmuş olması', 'Deniz seviyesinin altında yer alan tuzlu mangrov bataklığı ağaçlarına ev sahipliği yapması'], 'Yenice Ormanları derin nemli kanyonları ve ılıman mikroiklimi sayesinde 30\'dan fazla odunsu ağaç türünü tek bir vadide bir araya getirir; Türkiye\'nin en boylu ve en kalın gövdeli porsuk, fındık (Türk fındığı), ıhlamur ve istiridye/dağ karaağacı anıt bireylerini barındırır.'),
  ('Bitki yapraklarında gözenek açıklığını ayarlayan iki böbrek biçimli \'bekçi (kapatma) hücresinin\' dış ortamla bakan duvarının ince ve esnek, gözenek açıklığına (stoma yarığına) bakan iç duvarının ise kalın ve ışınsal selüloz mikrofibrilli olmasının biyomekanik sonucu nedir?', 'Hücre su alıp şiştiğinde (turgor arttığında) kalın iç duvar uzayamayıp dış duvar balon gibi dışa esneyerek ortadaki stoma deliğini yay gibi açar', ['Su girdiğinde hücreler merkeze doğru şişerek gözenek deliğini sımsıkı kapatır, kuruduğunda ise büzülerek açar', 'Kalın iç duvar yağmur suyunu doğrudan emerek mezofil dokusuna pompalayan bir su hunisi oluşturur', 'Işınsal selüloz lifleri kas telleri gibi ATP yakarak su basıncından bağımsız biçimde daralıp genişler'], 'Eğer bekçi hücrelerinin duvar kalınlığı her yerde eşit olsaydı, hücre şiştiğinde küre gibi büyüyüp ortadaki deliği tıkardı! İç çeperin kalın olması ve ışınsal mikrofibril kuşakları (radial micellation), turgor artışını kavisli bükülmeye çevirip gözenek ağzını açar.'),
  ('Deniz kıyısındaki hareketli kumulların rüzgârla iç kesimdeki tarım arazilerini ve köyleri yutmasını önlemek (kumul tespiti) amacıyla ilk aşamada dikilen \'kumul otu / kumsazı\' (Ammophila arenaria) rüzgârın üzerine kum yığmasına nasıl yanıt verir?', 'Üzeri kumla örtüldükçe boğulmak yerine uyur boğumlarından yukarı doğru hızlı dikey rizomlar ve yeni adventif kökler çıkararak kumulu içeriden ağ gibi örer', ['Kum taneciklerini eriten yapışkan reçine salgılayarak kumsalı bir ayda sert kayaya dönüştürür', 'Üzerine kum geldiği anda yapraklarını döküp yirmi yıl boyunca tohum halinde bekler', 'Yalnızca tatlı su bataklıklarında yaşayabildiği için kum örtüldüğünde bir haftada çürür'], 'Karadeniz (Terkos, Kilyos, Sinop, Kızılırmak Deltası) ve Avrupa kıyı kumullarında öncü sabitleyici olan kumsazı (Ammophila arenaria), \'kum gömülmesiyle büyümesi hızlanan\' nadir bir bitkidir; kum hareketi tamamen durduğunda ise yaşlanıp yerini çalı ve sahil çamlarına bırakır.'),
  ('Çiçekli bitkilerin tozlaşmasında polen tanesinin dışını zırh gibi saran ve milyonlarca yıllık kaya katmanlarında bile bozulmadan fosilleşerek geçmiş orman kuşaklarının haritasını çıkarmamızı (palinoloji) sağlayan doğanın en dayanıklı organik polimeri hangisidir?', 'Asitlere, bazlara ve çürümeye olağanüstü dirençli \'sporopolenin\' tabakası', ['Suda hızla şişerek dağılan yumuşak \'pektin ve hemiselüloz\' kılıfı', 'Yalnızca böcek kabuklarında bulunan azotlu \'kitin\' polisakkariti', 'Güneş ışığında birkaç günde parçalanan \'klorofil\' ester halkası'], 'Polenlerin dış zarı (ekzin) \'sporopolenin\' adı verilen biyopolimerden oluşur; göl tabanı çamurlarında on binlerce yıl şeklini ve türe özgü yüzey desenlerini koruduğu için buzul çağlarında kayın, meşe, çam ve step otlarının nasıl yer değiştirdiğini kesin olarak okutur.'),
  ('Ege ve Akdeniz\'de \'delice\' olarak bilinen yabani zeytin çalıları ile kültür zeytini (Olea europaea) karşılaştırıldığında binlerce yıllık kültüre alma (evcilleştirme) süreci meyve ve dal yapısında hangi belirgin değişimi sağlamıştır?', 'Kuşların yutabileceği küçük çekirdekli az etli meyveler ve dikenli alt sürgünler yerine, dikensiz dallar ile iri ve yüksek yağ oranlı meyve eti seçilmiştir', ['Yabani zeytinin kışın dökülen ince yaprakları kültür zeytininde dört mevsim yeşil iğne yapraklara dönüştürülmüştür', 'Rüzgârla tozlaşan yabani zeytin, iri kırmızı taç yapraklı ve sinekkuşuyla tozlaşan kültür formuna çevrilmiştir', 'Yabani zeytinin kanatlı kuru meyveleri, suda yüzebilen içi boş lifli kapsüllere dönüştürülmüştür'], 'Yabani zeytin (Olea europaea var. sylvestris / oleaster) dikenli genç dallara ve ardıç/karatavuk kuşlarının kolayca yuttuğu nohut iriliğinde az yağlı meyvelere sahiptir; Doğu Akdeniz\'de kalem aşısıyla klonal çoğaltılan kültür çeşitlerinde yağlı mezokarp katbekat büyütülmüştür.'),
  ('Çöl ve step bölgelerindeki birçok çalı (örneğin Amerika çölündeki kreozot çalısı - Larrea tridentata veya Akdeniz\'deki bazı adaçayı/cehri türleri) düz bir ovada yukarıdan fotoğraflandığında rastgele kümeler yerine cetvelle çizilmiş gibi birbirinden eşit mesafede (\'düzenli/üniform dağılım\') dizilir. Bunun nedeni nedir?', 'Yüzeysel köklerin kısıtlı yağmur suyu için şiddetli rekabet etmesi ve kök/yapraklardan yıkanan allelopatik kimyasalların yakın fideleri engellemesi', ['Çöl rüzgârlarının tohumları her zaman tam beşer metre aralıklarla kum çukurlarına bırakması', 'Karınca kolonilerinin çalı tohumlarını geometrik ızgara planına göre ölçerek ekmesi', 'Çalıların gölgelerinin birbirine değmesi halinde fotosentezin tamamen durması'], 'Bitki ekolojisinde kümeli dağılım besin ve tohum yayılımı yakınlığından doğarken, \'düzenli (üniform) dağılım\' hemen her zaman kıt kaynak (çölde su) için kıyasıya kök rekabetinin ve kimyasal engellemenin (allelopatinin) imzasıdır.'),
  ('Yüksek dağların rüzgârlı zirvelerinde (örneğin Toroslar, Erciyes ve Alplerde) birbirinden farklı familyalardan gelen çöven (Acantholimon), geven (Astragalus) ve taşkıran (Saxifraga) bitkilerinin ortaklaşa sıkı yarım küre (\'yastık bitki / cushion plant\') formu alması mikroiklimi nasıl değiştirir?', 'Rüzgârı %90\'dan fazla keser, yastık içindeki sıcaklığı dış havadan 10-15 °C sıcak tutar ve kendi ölü yaprak humusuyla nemli bir \'hemşire yatak\' yaratır', ['Kar örtüsünü üzerinden tamamen iterek bitkinin kışın eksi otuz derece ayazla doğrudan temas etmesini sağlar', 'Yastık içindeki havayı tamamen vakumlayarak böceklerin ve diğer bitkilerin yaşamasını engeller', 'Küre şekliyle yamaçtan kopup rüzgârla vadi tabanına yuvarlanmayı kolaylaştırır'], 'Alpin kuşakta \'ekosistem mühendisi\' ve \'hemşire bitki\' olarak çalışan yastık bitkiler, kendi kubbeleri içinde ılık, nemli ve humuslu bir mikro-sera kurar; öyle ki birçok narin alpin otsu tür yalnızca bu yastık bitkilerin içine sığınarak yaşayabilir!'),
  ('Brezilya\'nın Atlantik kıyısındaki yağmur ormanlarında yetişen ve Portekizli denizcilerin içinden çıkardığı parlak kor kırmızısı \'brazilein\' boyası yüzünden koca bir ülkeye \'Brezilya\' (kor/ateş ağacı ülkesi) adını veren, keman yayı (arşe) yapımında da eşsiz olan baklagil ağacı hangisidir?', 'Pernambuko / Brezilya boya ağacı (Paubrasilia echinata)', ['Amazon sütlü kauçuk ağacı (Hevea brasiliensis)', 'Güney Amerika mate çayı ağacı (Ilex paraguariensis)', 'Orta Amerika balsa odunu ağacı (Ochroma pyramidale)'], 'Tarihte bir ulusa adını veren tek ağaç olan Paubrasilia echinata (eski adıyla Caesalpinia echinata), 16. yüzyılda kırmızı tekstil boyası için aşırı kesilmiş, yoğun ve yaylanma kabiliyeti mükemmel öz odunu ise profesyonel keman yaylarının standart malzemesi olmuştur.'),
];
